-- 오늘의 퀴즈 (정민재): OX 12문항 + 4지선다 1,000문항
-- 4지선다는 프론트 문항 은행(frontend/src/quiz/data)에서 변환, 아직 사람 검수 전
-- 보기는 JSON_ARRAY/JSON_OBJECT로 만들어 백슬래시 이스케이프가 필요 없게 함
SET NAMES utf8mb4;
INSERT INTO quiz_questions (question_type, question_text, options, explanation, topic, difficulty, quiz_answer)
VALUES ('multiple_choice', '운동 후 가벼운 스트레칭을 하면 좋은 시점은 언제일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '몸이 완전히 식은 뒤 한참 후'), JSON_OBJECT('id', 'B', 'text', '운동 시작 전 아무 준비 없이'), JSON_OBJECT('id', 'C', 'text', '몸이 따뜻한 운동 직후나 정리 운동 때'), JSON_OBJECT('id', 'D', 'text', '운동 중 숨을 참고')), '몸이 따뜻할 때 스트레칭하면 근육이 부드럽게 늘어나 편안하게 할 수 있습니다.', 'recovery', 'easy', 'C'),
       ('multiple_choice', '식이 균형을 위해 "한 가지 식품군 위주"로 치우치지 않도록 하는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '필요한 영양소가 골고루 공급되지 않을 수 있어서'), JSON_OBJECT('id', 'B', 'text', '식비가 오르기 때문'), JSON_OBJECT('id', 'C', 'text', '조리가 어렵기 때문'), JSON_OBJECT('id', 'D', 'text', '맛이 없기 때문')), '식품군마다 제공하는 영양소가 달라 골고루 먹어야 영양 균형을 이룹니다.', 'balance', 'medium', 'A'),
       ('multiple_choice', '건강한 식단을 시작하는 첫걸음으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 음식을 한꺼번에 바꾸기'), JSON_OBJECT('id', 'B', 'text', '식사를 줄이기'), JSON_OBJECT('id', 'C', 'text', '유행하는 식단 따라 하기'), JSON_OBJECT('id', 'D', 'text', '작고 실천 가능한 목표 정하기')), '작은 목표부터 시작하면 부담 없이 습관으로 이어가기 쉽습니다.', 'practice', 'easy', 'D'),
       ('multiple_choice', '굿모닝 운동처럼 상체를 숙이는 동작에서 가장 중요한 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '최대 무게로 하기'), JSON_OBJECT('id', 'B', 'text', '척추 중립과 무게를 적절히 선택하기'), JSON_OBJECT('id', 'C', 'text', '허리를 크게 말기'), JSON_OBJECT('id', 'D', 'text', '속도를 최대로 올리기')), '허리를 숙이는 동작은 부담이 크므로 척추 중립을 유지하고 알맞은 무게로 해야 합니다.', 'form', 'medium', 'B'),
       ('multiple_choice', '러닝을 하기 전 알맞은 준비는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '곧바로 전력 질주'), JSON_OBJECT('id', 'B', 'text', '긴 정적 스트레칭만 하기'), JSON_OBJECT('id', 'C', 'text', '가볍게 걷다가 천천히 달리기 시작하기'), JSON_OBJECT('id', 'D', 'text', '앉아서 휴식만 하기')), '걷기에서 시작해 조깅으로 서서히 속도를 올리면 몸이 달리기에 맞게 준비됩니다.', 'warmup', 'easy', 'C'),
       ('multiple_choice', '체중 감량 중 외식을 할 때 현실적인 대처로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '메뉴를 미리 보고 양을 조절하며 채소·단백질 위주로 선택하기'), JSON_OBJECT('id', 'B', 'text', '아예 외식을 금지하기'), JSON_OBJECT('id', 'C', 'text', '이전 끼니를 굶기'), JSON_OBJECT('id', 'D', 'text', '무제한으로 먹기')), '완전 금지보다 선택과 양 조절을 하면 사회적 식사와 감량을 병행하기 쉽습니다.', 'habit', 'hard', 'A'),
       ('multiple_choice', '도시락을 만들어 가져갈 때 위생을 지키는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '뜨거운 채로 밀폐해 두기'), JSON_OBJECT('id', 'B', 'text', '충분히 식힌 뒤 담고 보냉 용품을 활용하기'), JSON_OBJECT('id', 'C', 'text', '실온에 오래 두기'), JSON_OBJECT('id', 'D', 'text', '햇빛에 두기')), '음식을 식힌 후 담고 보냉 가방이나 아이스팩을 쓰면 세균 증식을 줄일 수 있습니다.', 'hygiene', 'medium', 'B'),
       ('multiple_choice', '정적 스트레칭과 동적 스트레칭의 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 같은 방식'), JSON_OBJECT('id', 'B', 'text', '동적은 쉬는 방식'), JSON_OBJECT('id', 'C', 'text', '정적은 점프 운동'), JSON_OBJECT('id', 'D', 'text', '정적은 자세를 유지하고 동적은 움직이며 가동 범위를 넓힌다')), '정적 스트레칭은 일정 시간 자세를 유지하고, 동적 스트레칭은 움직임을 반복하며 근육을 준비시킵니다.', 'recovery', 'hard', 'D'),
       ('multiple_choice', '근력 향상을 목표로 할 때 상대적으로 알맞은 방식은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '아주 가벼운 무게로 수백 번'), JSON_OBJECT('id', 'B', 'text', '휴식 없이 계속하기'), JSON_OBJECT('id', 'C', 'text', '무거운 무게로 적은 반복을 충분한 휴식과 함께'), JSON_OBJECT('id', 'D', 'text', '무게를 전혀 바꾸지 않기')), '높은 부하로 적은 반복을 하면 신경과 근육이 함께 적응해 최대 근력 향상에 유리합니다.', 'intensity', 'medium', 'C'),
       ('multiple_choice', '케틀벨 스윙에서 힘은 주로 어디서 나와야 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '팔로 들어 올리기'), JSON_OBJECT('id', 'B', 'text', '허리를 앞으로 꺾기'), JSON_OBJECT('id', 'C', 'text', '엉덩이를 밀어내는 고관절 폭발'), JSON_OBJECT('id', 'D', 'text', '어깨를 으쓱하기')), '스윙은 팔로 드는 것이 아니라 고관절을 힘 있게 펴는 움직임에서 힘이 나옵니다.', 'form', 'medium', 'C'),
       ('multiple_choice', '케이블 크로스오버는 주로 어느 근육을 쓰는 운동일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '종아리'), JSON_OBJECT('id', 'B', 'text', '복부'), JSON_OBJECT('id', 'C', 'text', '가슴'), JSON_OBJECT('id', 'D', 'text', '허벅지 뒤쪽')), '양손을 앞으로 모으는 동작은 가슴 근육을 중심으로 쓰는 운동입니다.', 'form', 'medium', 'C'),
       ('multiple_choice', '물을 마시기 좋은 시간으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '자기 직전 많이'), JSON_OBJECT('id', 'B', 'text', '식사 직전 아주 많이'), JSON_OBJECT('id', 'C', 'text', '식사 사이, 운동 전후, 기상 후'), JSON_OBJECT('id', 'D', 'text', '마시지 않는 시간')), '하루 중 여러 번 나누어 마시면 수분 균형을 유지하기 쉽습니다.', 'water', 'easy', 'C'),
       ('multiple_choice', '"배고픔 척도"를 활용하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사량을 숨기기'), JSON_OBJECT('id', 'B', 'text', '식사를 건너뛰기'), JSON_OBJECT('id', 'C', 'text', '배고픔을 무시하기'), JSON_OBJECT('id', 'D', 'text', '식사 전후 배고픔 정도를 점수로 체크해 알맞은 양을 가늠하기')), '배고픔과 포만감을 숫자로 체크하면 몸의 신호를 알아차리는 연습에 도움이 됩니다.', 'habit', 'medium', 'D'),
       ('multiple_choice', '물은 우리 몸에서 어떤 역할을 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체온 조절과 영양소·노폐물 운반'), JSON_OBJECT('id', 'B', 'text', '근육을 직접 만든다'), JSON_OBJECT('id', 'C', 'text', '열량을 가장 많이 낸다'), JSON_OBJECT('id', 'D', 'text', '뼈의 주성분이다')), '물은 체온 조절, 영양소와 노폐물의 이동 등에 필요합니다.', 'nutrients', 'easy', 'A'),
       ('multiple_choice', '식사 후 바로 커피나 단 음료를 마시는 습관이 영양에 미칠 수 있는 영향은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 영양소 흡수가 좋아진다'), JSON_OBJECT('id', 'B', 'text', '영향이 전혀 없다'), JSON_OBJECT('id', 'C', 'text', '당 섭취가 늘거나 철분 흡수에 영향을 줄 수 있다'), JSON_OBJECT('id', 'D', 'text', '단백질이 사라진다')), '커피의 탄닌은 철분 흡수에 영향을 줄 수 있고 단 음료는 당 섭취를 늘립니다.', 'habit', 'medium', 'C'),
       ('multiple_choice', '폼롤러 사용 시 주의할 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '뼈 위에서 세게 굴리기'), JSON_OBJECT('id', 'B', 'text', '통증을 참고 계속하기'), JSON_OBJECT('id', 'C', 'text', '빠르게 반동으로 굴리기'), JSON_OBJECT('id', 'D', 'text', '뼈나 관절 위는 피하고 근육 부위를 천천히 굴리기')), '근육 부위를 통증이 심하지 않은 정도로 천천히 굴리는 것이 안전합니다.', 'recovery', 'medium', 'D'),
       ('multiple_choice', '칼륨의 역할로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '뼈를 만든다'), JSON_OBJECT('id', 'B', 'text', '나트륨 배출을 돕고 근육·신경 기능에 관여한다'), JSON_OBJECT('id', 'C', 'text', '열량을 낸다'), JSON_OBJECT('id', 'D', 'text', '혈액을 응고시킨다')), '칼륨은 체액 균형과 근육·신경 기능에 관여하며 나트륨 배출에도 도움을 줍니다.', 'nutrients', 'medium', 'B'),
       ('multiple_choice', '운동 강도를 최대 심박수의 비율로 정할 때 흔히 쓰는 추정식은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '220에서 나이를 뺀 값'), JSON_OBJECT('id', 'B', 'text', '100에서 나이를 더한 값'), JSON_OBJECT('id', 'C', 'text', '체중에 2를 곱한 값'), JSON_OBJECT('id', 'D', 'text', '키에서 100을 뺀 값')), '최대 심박수는 대략 220에서 나이를 뺀 값으로 추정하지만 개인차가 있어 참고용으로만 씁니다.', 'basics', 'hard', 'A'),
       ('multiple_choice', '운동 강도를 느낌으로 가늠할 때 "조금 힘들다"에 해당하는 정도는 어떤 운동일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '전혀 힘들지 않은 운동'), JSON_OBJECT('id', 'B', 'text', '숨이 너무 차서 말을 못 하는 운동'), JSON_OBJECT('id', 'C', 'text', '숨이 약간 차지만 대화는 가능한 운동'), JSON_OBJECT('id', 'D', 'text', '움직이지 않는 상태')), '약간 숨이 차면서도 대화가 가능한 정도는 흔히 중강도로 분류됩니다.', 'intensity', 'easy', 'C'),
       ('multiple_choice', '근력 운동 후 근육이 회복되며 강해지는 시기는 언제일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 뒤 휴식하는 동안'), JSON_OBJECT('id', 'B', 'text', '운동하는 도중에만'), JSON_OBJECT('id', 'C', 'text', '전혀 쉬지 않을 때'), JSON_OBJECT('id', 'D', 'text', '잠을 자지 않을 때')), '운동은 근육에 자극을 주고, 실제 회복과 적응은 휴식하는 동안 일어납니다.', 'basics', 'easy', 'A'),
       ('multiple_choice', '도마를 재질별로 관리할 때 알맞은 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '사용 후 세제로 씻고 완전히 말리기'), JSON_OBJECT('id', 'B', 'text', '젖은 채로 쌓아 두기'), JSON_OBJECT('id', 'C', 'text', '씻지 않고 계속 쓰기'), JSON_OBJECT('id', 'D', 'text', '물에 계속 담가 두기')), '도마는 균열에 세균이 남을 수 있어 세척 후 건조하는 것이 중요합니다.', 'hygiene', 'medium', 'A'),
       ('multiple_choice', '데드리프트에서 허리를 보호하기 위해 유지해야 하는 자세는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '허리를 둥글게 말기'), JSON_OBJECT('id', 'B', 'text', '목을 과하게 꺾기'), JSON_OBJECT('id', 'C', 'text', '척추를 중립으로 유지하고 고관절을 접어 내리기'), JSON_OBJECT('id', 'D', 'text', '무릎을 잠그고 허리만 숙이기')), '척추를 중립으로 유지하고 고관절 힌지로 움직이면 허리 부담을 줄이고 둔근·햄스트링을 쓸 수 있습니다.', 'form', 'medium', 'C'),
       ('multiple_choice', '운동 시작 후 몸이 따라오지 않는 날 알맞은 선택은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '강도나 시간을 낮추어 가볍게 하기'), JSON_OBJECT('id', 'B', 'text', '무리해서 평소보다 더 하기'), JSON_OBJECT('id', 'C', 'text', '통증이 있어도 계속하기'), JSON_OBJECT('id', 'D', 'text', '운동을 영영 그만두기')), '컨디션이 좋지 않은 날은 가볍게 조절하면 꾸준함을 지킬 수 있습니다.', 'intensity', 'easy', 'A'),
       ('multiple_choice', '스쿼트 점프의 안전한 착지 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무릎을 편 채 쿵 하고 착지하기'), JSON_OBJECT('id', 'B', 'text', '발끝 한 점으로 착지하기'), JSON_OBJECT('id', 'C', 'text', '눈을 감고 착지하기'), JSON_OBJECT('id', 'D', 'text', '무릎을 굽혀 부드럽게 충격을 흡수하며 착지하기')), '무릎과 고관절을 굽혀 충격을 나누어 받으면 관절 부담이 줄어듭니다.', 'form', 'medium', 'D'),
       ('multiple_choice', '"과일 주스"와 "과일 음료"를 비교할 때 확인할 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '병의 모양'), JSON_OBJECT('id', 'B', 'text', '라벨 색'), JSON_OBJECT('id', 'C', 'text', '과즙 함량과 당류 첨가 여부'), JSON_OBJECT('id', 'D', 'text', '제조 장소')), '과즙 함량이 낮거나 당이 첨가된 음료는 과일을 먹는 것과 영양적으로 차이가 큽니다.', 'label', 'medium', 'C'),
       ('multiple_choice', '채소를 씻는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 번만 물에 담갔다 건지기'), JSON_OBJECT('id', 'B', 'text', '흐르는 물에 여러 번 헹구기'), JSON_OBJECT('id', 'C', 'text', '씻지 않기'), JSON_OBJECT('id', 'D', 'text', '세제로 씻기')), '흐르는 물에서 충분히 헹구면 표면의 흙과 이물질을 줄일 수 있습니다.', 'hygiene', 'medium', 'B'),
       ('multiple_choice', '저강도 유산소 운동의 장점으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '부상 위험이 항상 가장 높다'), JSON_OBJECT('id', 'B', 'text', '효과가 전혀 없다'), JSON_OBJECT('id', 'C', 'text', '회복이 가장 오래 걸린다'), JSON_OBJECT('id', 'D', 'text', '부담이 적어 오래 지속하기 쉽다')), '저강도 운동은 부담이 낮아 꾸준히 오래 이어가기 쉬워 초보자와 회복일에 적합합니다.', 'basics', 'hard', 'D'),
       ('multiple_choice', '쓰레기와 음식물 쓰레기를 처리한 뒤 해야 할 일은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '그대로 조리하기'), JSON_OBJECT('id', 'B', 'text', '손을 닦지 않기'), JSON_OBJECT('id', 'C', 'text', '장갑을 벗지 않기'), JSON_OBJECT('id', 'D', 'text', '손 씻기')), '쓰레기 처리 후에는 손을 씻어 오염이 음식에 옮겨가지 않도록 해야 합니다.', 'hygiene', 'easy', 'D'),
