       ('multiple_choice', '식단 실천이 어려울 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '목표를 더 작게 나누고 다시 시작하기'), JSON_OBJECT('id', 'B', 'text', '완전히 포기하기'), JSON_OBJECT('id', 'C', 'text', '더 큰 목표를 세우기'), JSON_OBJECT('id', 'D', 'text', '남을 탓하기')), '목표를 줄이고 다시 시작하는 것이 장기적으로 습관을 만드는 데 도움이 됩니다.', 'practice', 'medium', 'A'),
       ('multiple_choice', '운동을 쉬었다가 다시 시작할 때 좋은 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '쉬기 전 최대 강도로 바로 하기'), JSON_OBJECT('id', 'B', 'text', '이전보다 낮은 강도에서 다시 올려 가기'), JSON_OBJECT('id', 'C', 'text', '쉬었으니 두 배로 하기'), JSON_OBJECT('id', 'D', 'text', '준비운동 없이 시작하기')), '쉬는 동안 체력이 줄었으므로 이전보다 낮은 강도로 시작해 서서히 올리는 것이 안전합니다.', 'basics', 'medium', 'B'),
       ('multiple_choice', '"위험 온도 구간(danger zone)"이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '음식이 가장 맛있는 온도'), JSON_OBJECT('id', 'B', 'text', '가장 안전한 온도'), JSON_OBJECT('id', 'C', 'text', '세균이 빠르게 증식하는 약 5℃~60℃ 구간'), JSON_OBJECT('id', 'D', 'text', '냉동 온도')), '5℃~60℃ 사이에서는 세균이 빠르게 번식해 식품을 오래 두면 위험합니다.', 'hygiene', 'medium', 'C'),
       ('multiple_choice', '마운틴 클라이머에서 흔한 실수는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손을 어깨 아래에 두는 것'), JSON_OBJECT('id', 'B', 'text', '복부에 힘을 주는 것'), JSON_OBJECT('id', 'C', 'text', '엉덩이를 높이 들거나 낮추어 몸이 일직선에서 벗어나는 것'), JSON_OBJECT('id', 'D', 'text', '호흡하며 하는 것')), '몸을 일직선으로 유지하지 못하면 복부 힘이 새고 어깨와 허리에 부담이 생깁니다.', 'form', 'medium', 'C'),
       ('multiple_choice', '식중독을 일으키는 대표적인 세균으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '유산균'), JSON_OBJECT('id', 'B', 'text', '살모넬라, 대장균, 황색포도상구균'), JSON_OBJECT('id', 'C', 'text', '비피더스균'), JSON_OBJECT('id', 'D', 'text', '효모')), '살모넬라나 병원성 대장균, 황색포도상구균 등이 식중독을 일으키는 대표적인 세균입니다.', 'hygiene', 'medium', 'B'),
       ('multiple_choice', '영양성분표를 볼 때 가장 먼저 확인해야 할 기준은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '1회 제공량(기준량)'), JSON_OBJECT('id', 'B', 'text', '제품 이름'), JSON_OBJECT('id', 'C', 'text', '포장 색상'), JSON_OBJECT('id', 'D', 'text', '제조 공장 위치')), '영양성분 함량은 제공량 기준이므로 먼저 몇 g, 몇 개 기준인지 확인해야 합니다.', 'label', 'easy', 'A'),
       ('multiple_choice', '장보기 목록을 미리 작성하는 습관의 장점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식비가 항상 늘어난다'), JSON_OBJECT('id', 'B', 'text', '신선도가 떨어진다'), JSON_OBJECT('id', 'C', 'text', '식재료가 사라진다'), JSON_OBJECT('id', 'D', 'text', '충동구매를 줄이고 필요한 식품을 균형 있게 사기 쉽다')), '목록을 만들면 불필요한 가공식품 구입을 줄이고 식단 계획을 세우기 쉽습니다.', 'label', 'medium', 'D'),
       ('multiple_choice', '운동 직전 짧은 동적 스트레칭의 장점으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '순간 힘을 크게 줄인다'), JSON_OBJECT('id', 'B', 'text', '체온을 낮춘다'), JSON_OBJECT('id', 'C', 'text', '운동 수행과 움직임 범위를 해치지 않고 준비를 돕는다'), JSON_OBJECT('id', 'D', 'text', '심박을 정지시킨다')), '동적 스트레칭은 운동 직전에 움직임 범위를 확보하면서 수행 능력을 해치지 않는 것으로 알려져 있습니다.', 'warmup', 'hard', 'C'),
       ('multiple_choice', '간식을 먹을 때 포장째 먹는 습관의 문제는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '먹는 양이 항상 줄어든다'), JSON_OBJECT('id', 'B', 'text', '맛이 좋아진다'), JSON_OBJECT('id', 'C', 'text', '소화가 잘된다'), JSON_OBJECT('id', 'D', 'text', '먹는 양을 알아차리기 어려워 과식하기 쉽다')), '포장째 먹으면 먹은 양을 파악하기 어려워 덜어 먹는 것이 좋습니다.', 'habit', 'easy', 'D'),
       ('multiple_choice', '중강도 활동으로 흔히 분류되는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '빠르게 걷기'), JSON_OBJECT('id', 'B', 'text', '전력 질주'), JSON_OBJECT('id', 'C', 'text', '누워서 휴식하기'), JSON_OBJECT('id', 'D', 'text', '앉아서 TV 보기')), '속도를 내어 걷는 것은 대표적인 중강도 신체활동입니다.', 'basics', 'medium', 'A'),
