       ('multiple_choice', '버피에서 시작 자세로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '선 자세에서 앉아 손을 바닥에 짚기'), JSON_OBJECT('id', 'B', 'text', '누운 자세에서 바로 점프'), JSON_OBJECT('id', 'C', 'text', '앉은 채 팔만 흔들기'), JSON_OBJECT('id', 'D', 'text', '벽에 기대기')), '버피는 선 자세 → 쭈그려 앉아 손 짚기 → 플랭크 → 다시 일어나 점프로 이어지는 전신 운동입니다.', 'form', 'easy', 'A'),
       ('multiple_choice', '식품의 제조일자가 의미하는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식품이 만들어진 날짜'), JSON_OBJECT('id', 'B', 'text', '식품이 폐기되는 날짜'), JSON_OBJECT('id', 'C', 'text', '식품을 먹어야 하는 날짜'), JSON_OBJECT('id', 'D', 'text', '식품의 가격')), '제조일자는 식품이 제조된 날짜를 의미합니다.', 'label', 'easy', 'A'),
       ('multiple_choice', '운동 후 몇 시간 동안 에너지 소비가 약간 높게 유지되는 현상을 무엇이라 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 후 초과 산소 소비'), JSON_OBJECT('id', 'B', 'text', '운동 전 예열'), JSON_OBJECT('id', 'C', 'text', '수면 지연'), JSON_OBJECT('id', 'D', 'text', '근육 위축')), '고강도 운동 후 몸이 회복하는 동안 산소와 에너지 소비가 안정 때보다 약간 높게 유지되는 현상입니다.', 'basics', 'medium', 'A'),
       ('multiple_choice', '식단 실천을 도와주는 도구의 활용법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '숫자에만 집착하기'), JSON_OBJECT('id', 'B', 'text', '식사 기록 앱으로 섭취량을 점검하되 숫자에 지나치게 집착하지 않기'), JSON_OBJECT('id', 'C', 'text', '기록하지 않기'), JSON_OBJECT('id', 'D', 'text', '앱을 삭제하기')), '도구는 참고용으로 활용하고 몸의 신호와 식사의 질을 함께 보는 것이 좋습니다.', 'practice', 'hard', 'B'),
       ('multiple_choice', '"식물성 대체 식품"을 선택할 때 확인해야 할 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '단백질·나트륨·포화지방 등 영양 성분과 첨가물'), JSON_OBJECT('id', 'B', 'text', '포장 색상'), JSON_OBJECT('id', 'C', 'text', '이름'), JSON_OBJECT('id', 'D', 'text', '광고 문구')), '대체 식품도 제품마다 영양 구성이 다르므로 영양성분표를 확인해야 합니다.', 'label', 'hard', 'A'),
       ('multiple_choice', '운동 중 심박수가 갑자기 비정상적으로 빨라지거나 불규칙할 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '계속 달리기'), JSON_OBJECT('id', 'B', 'text', '더 빨리 달리기'), JSON_OBJECT('id', 'C', 'text', '카페인 마시기'), JSON_OBJECT('id', 'D', 'text', '운동을 멈추고 증상이 지속되면 진료받기')), '비정상적인 심박은 심장 문제의 신호일 수 있어 멈추고 필요하면 진료를 받아야 합니다.', 'safety', 'medium', 'D'),
