       ('multiple_choice', '점심 식사로 알맞은 구성은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '과자와 탄산음료'), JSON_OBJECT('id', 'B', 'text', '사탕과 초콜릿'), JSON_OBJECT('id', 'C', 'text', '탄산수만'), JSON_OBJECT('id', 'D', 'text', '밥, 생선구이, 나물 반찬')), '곡류, 단백질, 채소가 포함된 식사가 균형에 도움이 됩니다.', 'balance', 'easy', 'D'),
       ('multiple_choice', '식사 중 "음식을 남기지 않기" 규칙의 부작용은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사량이 항상 줄어든다'), JSON_OBJECT('id', 'B', 'text', '배가 불러도 계속 먹어 과식할 수 있다'), JSON_OBJECT('id', 'C', 'text', '음식이 사라진다'), JSON_OBJECT('id', 'D', 'text', '소화가 항상 잘된다')), '남기지 않으려는 압박은 포만감을 무시하고 먹게 해 과식으로 이어질 수 있습니다.', 'habit', 'medium', 'B'),
       ('multiple_choice', '운동 중 관절이 "딱" 소리가 나지만 통증이 없을 때의 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '항상 관절이 부러진 것이다'), JSON_OBJECT('id', 'B', 'text', '통증이 없다면 대부분 문제가 없지만 통증·부기가 동반되면 확인이 필요하다'), JSON_OBJECT('id', 'C', 'text', '아무 의미 없고 통증이 있어도 무시'), JSON_OBJECT('id', 'D', 'text', '소리가 나면 운동을 영영 못 한다')), '통증이 없는 관절 소리는 흔하지만 통증이나 붓기가 함께 있으면 진료가 필요할 수 있습니다.', 'safety', 'hard', 'B'),
       ('multiple_choice', '운동 중 화장실에 가고 싶을 때 알맞은 행동은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '참으면서 계속 운동하기'), JSON_OBJECT('id', 'B', 'text', '물을 전혀 마시지 않기'), JSON_OBJECT('id', 'C', 'text', '더 격하게 운동하기'), JSON_OBJECT('id', 'D', 'text', '참지 말고 잠시 쉬며 다녀오기')), '몸의 신호를 참으며 운동하면 불편함과 집중력 저하로 자세가 무너질 수 있어 잠시 쉬는 것이 좋습니다.', 'safety', 'easy', 'D'),
       ('multiple_choice', '식사 습관 개선에서 행동 변화 전략으로 널리 쓰이는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '구체적 목표 설정, 자기 점검, 환경 정돈'), JSON_OBJECT('id', 'B', 'text', '목표 없이 의지만 믿기'), JSON_OBJECT('id', 'C', 'text', '기록하지 않기'), JSON_OBJECT('id', 'D', 'text', '주변 환경을 그대로 두기')), '구체적인 목표와 점검, 환경 조정은 행동 변화에 효과적인 방법으로 알려져 있습니다.', 'habit', 'hard', 'A'),
       ('multiple_choice', '운동 강도를 %1RM으로 정하는 것의 장점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 사람에게 같은 무게를 정할 수 있다'), JSON_OBJECT('id', 'B', 'text', '무게를 쓸 필요가 없다'), JSON_OBJECT('id', 'C', 'text', '개인의 최대 능력에 맞는 상대적인 강도를 정할 수 있다'), JSON_OBJECT('id', 'D', 'text', '운동을 쉬게 한다')), '개인 최대치 대비 비율로 강도를 정하면 사람마다 알맞은 부하를 설정하기 쉽습니다.', 'intensity', 'hard', 'C'),
       ('multiple_choice', '식품첨가물이 들어간 제품을 고를 때 알맞은 태도는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '원재료명을 확인하고 필요한 양만 선택하기'), JSON_OBJECT('id', 'B', 'text', '확인하지 않고 많이 먹기'), JSON_OBJECT('id', 'C', 'text', '모두 해롭다고 단정하기'), JSON_OBJECT('id', 'D', 'text', '무조건 안전하다고 단정하기')), '허용 기준 안에서 사용되지만 원재료를 확인하고 섭취량을 조절하는 태도가 알맞습니다.', 'label', 'easy', 'A'),
       ('multiple_choice', '식단 실천에서 "완벽주의"가 문제될 수 있는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '항상 더 건강해져서'), JSON_OBJECT('id', 'B', 'text', '식사량이 줄어서'), JSON_OBJECT('id', 'C', 'text', '한 번의 실수에 포기하여 장기적으로 지속하기 어려울 수 있어서'), JSON_OBJECT('id', 'D', 'text', '문제가 없어서')), '"전부 아니면 전무" 사고는 작은 실수에 좌절해 습관을 포기하게 만들 수 있습니다.', 'practice', 'hard', 'C'),
       ('multiple_choice', '다음 중 불포화지방이 풍부한 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '견과류와 생선'), JSON_OBJECT('id', 'B', 'text', '버터'), JSON_OBJECT('id', 'C', 'text', '라드'), JSON_OBJECT('id', 'D', 'text', '쇼트닝')), '견과류와 생선, 식물성 기름에는 불포화지방이 비교적 많이 들어 있습니다.', 'nutrients', 'easy', 'A'),
       ('multiple_choice', '밥, 반찬, 국으로 구성된 한식 식단의 영양적 특징으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '항상 영양소가 부족하다'), JSON_OBJECT('id', 'B', 'text', '항상 나트륨이 적다'), JSON_OBJECT('id', 'C', 'text', '열량이 전혀 없다'), JSON_OBJECT('id', 'D', 'text', '곡류와 채소, 단백질을 함께 먹기 쉬운 구조이나 국과 찌개의 나트륨은 주의가 필요하다')), '한식은 구성이 다양해 균형을 맞추기 좋지만 국, 찌개, 젓갈 등의 나트륨을 줄이는 것이 좋습니다.', 'balance', 'medium', 'D'),
       ('multiple_choice', '튀김 대신 선택하기 좋은 조리법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '튀김을 더 하기'), JSON_OBJECT('id', 'B', 'text', '기름에 푹 담가 조리하기'), JSON_OBJECT('id', 'C', 'text', '찜, 구이, 삶기'), JSON_OBJECT('id', 'D', 'text', '버터를 추가하기')), '기름을 적게 쓰는 조리법은 열량과 포화지방 섭취를 줄이는 데 도움이 됩니다.', 'practice', 'easy', 'C'),
       ('multiple_choice', '준비운동은 보통 몇 분 정도 하는 것이 알맞을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '5~10분'), JSON_OBJECT('id', 'B', 'text', '1초'), JSON_OBJECT('id', 'C', 'text', '2시간'), JSON_OBJECT('id', 'D', 'text', '하루 종일')), '대체로 5~10분 정도 가볍게 몸을 데우면 본 운동을 시작하기에 알맞습니다.', 'warmup', 'easy', 'A'),
       ('multiple_choice', '곰팡이가 핀 식품을 발견했을 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '곰팡이 부위만 도려내지 말고 버리는 것이 안전하다'), JSON_OBJECT('id', 'B', 'text', '곰팡이만 닦고 먹기'), JSON_OBJECT('id', 'C', 'text', '더 오래 두기'), JSON_OBJECT('id', 'D', 'text', '냉동하고 먹기')), '곰팡이는 눈에 보이지 않는 곳까지 퍼져 있을 수 있고 독소를 만들 수 있어 버리는 것이 안전합니다.', 'hygiene', 'medium', 'A'),
       ('multiple_choice', '운동 전후로 체중을 재면 줄어 있는 경우가 많은 가장 큰 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '땀으로 수분이 빠졌기 때문'), JSON_OBJECT('id', 'B', 'text', '근육이 한 번에 사라졌기 때문'), JSON_OBJECT('id', 'C', 'text', '뼈 무게가 줄었기 때문'), JSON_OBJECT('id', 'D', 'text', '지방이 바로 모두 녹았기 때문')), '운동 직후 체중 감소의 대부분은 땀으로 나간 수분입니다. 지방이 그만큼 줄어든 것은 아닙니다.', 'basics', 'easy', 'A'),
       ('multiple_choice', '지방이 많은 부위와 적은 부위를 비교했을 때 열량이 낮은 선택은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '삼겹살'), JSON_OBJECT('id', 'B', 'text', '닭가슴살'), JSON_OBJECT('id', 'C', 'text', '베이컨'), JSON_OBJECT('id', 'D', 'text', '갈비')), '닭가슴살은 지방이 적은 부위로 같은 양 기준 열량이 낮은 편입니다.', 'nutrients', 'medium', 'B'),
       ('multiple_choice', '글리세믹 로드(GL)가 혈당 지수(GI)와 다른 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '맛을 반영한다'), JSON_OBJECT('id', 'B', 'text', '가격을 반영한다'), JSON_OBJECT('id', 'C', 'text', '식품의 1회 섭취량까지 반영한다'), JSON_OBJECT('id', 'D', 'text', '색을 반영한다')), 'GL은 GI에 실제 섭취하는 탄수화물의 양을 곱해 혈당에 미치는 영향을 더 현실적으로 나타냅니다.', 'nutrients', 'hard', 'C'),
       ('multiple_choice', '한 끼 열량을 조절하는 쉬운 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '포장째 먹기'), JSON_OBJECT('id', 'B', 'text', '먹는 양을 보지 않기'), JSON_OBJECT('id', 'C', 'text', '1회 제공량을 정해 덜어 먹기'), JSON_OBJECT('id', 'D', 'text', '배가 불러도 계속 먹기')), '미리 덜어서 먹으면 먹는 양을 파악하고 과식을 줄이기 쉽습니다.', 'balance', 'medium', 'C'),
