       ('true_false', '알코올은 열량이 없다.', NULL, '알코올은 1g당 약 7kcal의 열량을 냅니다.', '영양', 'easy', 'X'),
       ('multiple_choice', '저녁 식사를 너무 늦게 많이 먹으면 생길 수 있는 불편으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '소화가 불편하거나 수면에 영향을 줄 수 있다'), JSON_OBJECT('id', 'B', 'text', '키가 크게 자란다'), JSON_OBJECT('id', 'C', 'text', '피부가 반드시 좋아진다'), JSON_OBJECT('id', 'D', 'text', '체온이 낮아진다')), '늦은 시간의 과식은 소화 불편과 수면의 질 저하로 이어질 수 있습니다.', 'balance', 'easy', 'A'),
       ('multiple_choice', '운동 후 소변 색이 매우 진하거나 콜라색일 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '수분을 보충하고 증상이 지속되면 진료받기'), JSON_OBJECT('id', 'B', 'text', '무시하고 운동 계속하기'), JSON_OBJECT('id', 'C', 'text', '더 세게 운동하기'), JSON_OBJECT('id', 'D', 'text', '물을 마시지 않기')), '매우 진한 소변은 탈수나 드물게 근육 손상 신호일 수 있어 지속되면 진료가 필요합니다.', 'safety', 'medium', 'A'),
       ('multiple_choice', '지방 1g이 내는 열량은 약 얼마일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '약 4kcal'), JSON_OBJECT('id', 'B', 'text', '약 1kcal'), JSON_OBJECT('id', 'C', 'text', '약 2kcal'), JSON_OBJECT('id', 'D', 'text', '약 9kcal')), '지방은 1g당 약 9kcal로 3대 영양소 중 열량이 가장 높습니다.', 'nutrients', 'easy', 'D'),
       ('multiple_choice', '식사 시간이 불규칙한 사람이 개선하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사를 완전히 거르기'), JSON_OBJECT('id', 'B', 'text', '밤에 몰아 먹기'), JSON_OBJECT('id', 'C', 'text', '가능한 범위에서 식사 시간을 일정하게 정하고 간식을 계획하기'), JSON_OBJECT('id', 'D', 'text', '식사 시간을 매번 무작위로 정하기')), '규칙적인 시간에 먹으면 허기를 조절하고 과식을 줄이기 쉽습니다.', 'balance', 'medium', 'C'),
       ('multiple_choice', '대퇴사두근에 포함되는 근육 개수와 의미는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '네 개의 머리를 가진 허벅지 앞쪽 근육군'), JSON_OBJECT('id', 'B', 'text', '두 개의 뼈'), JSON_OBJECT('id', 'C', 'text', '세 개의 인대'), JSON_OBJECT('id', 'D', 'text', '한 개의 힘줄')), '대퇴사두근은 대퇴직근, 내측광근, 외측광근, 중간광근 네 부분으로 이루어진 근육군입니다.', 'body', 'hard', 'A'),
       ('multiple_choice', '규칙적으로 식사하는 습관의 장점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식욕이 사라진다'), JSON_OBJECT('id', 'B', 'text', '허기를 조절하고 과식을 줄이는 데 도움이 된다'), JSON_OBJECT('id', 'C', 'text', '소화가 되지 않는다'), JSON_OBJECT('id', 'D', 'text', '체력이 떨어진다')), '일정한 시간에 먹으면 몸의 리듬이 안정되고 폭식을 줄이기 쉽습니다.', 'habit', 'easy', 'B'),
       ('multiple_choice', '준비운동을 건너뛰고 바로 본 운동을 시작하면 어떤 위험이 커질까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '키 성장'), JSON_OBJECT('id', 'B', 'text', '체온 상승'), JSON_OBJECT('id', 'C', 'text', '수분 증가'), JSON_OBJECT('id', 'D', 'text', '근육과 관절 부상')), '준비 없이 갑자기 강한 운동을 하면 근육과 관절이 놀라 부상 위험이 커질 수 있습니다.', 'warmup', 'easy', 'D'),
       ('multiple_choice', '원재료명은 어떤 순서로 표시되나요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '가나다 순서'), JSON_OBJECT('id', 'B', 'text', '가격 순서'), JSON_OBJECT('id', 'C', 'text', '많이 사용된 순서'), JSON_OBJECT('id', 'D', 'text', '무작위')), '원재료명은 일반적으로 사용량이 많은 순서대로 표시됩니다.', 'label', 'easy', 'C'),
       ('multiple_choice', '위팔 앞쪽 근육은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '상완삼두근'), JSON_OBJECT('id', 'B', 'text', '대둔근'), JSON_OBJECT('id', 'C', 'text', '복직근'), JSON_OBJECT('id', 'D', 'text', '상완이두근')), '이두근은 팔꿈치를 굽힐 때 주로 쓰이는 위팔 앞쪽 근육입니다.', 'body', 'easy', 'D'),
       ('multiple_choice', '운동 시작 전 잊지 말고 해야 할 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사를 완전히 건너뛰고 시작하기'), JSON_OBJECT('id', 'B', 'text', '준비 없이 바로 최대 강도'), JSON_OBJECT('id', 'C', 'text', '물을 준비하고 준비 운동 하기'), JSON_OBJECT('id', 'D', 'text', '신발 끈 풀고 시작')), '수분과 준비 운동은 안전한 운동의 기본입니다.', 'safety', 'easy', 'C'),
       ('true_false', '단백질 1g은 약 4kcal의 열량을 낸다.', NULL, '단백질과 탄수화물은 1g당 약 4kcal, 지방은 약 9kcal입니다.', '영양', 'easy', 'O'),
       ('multiple_choice', '식단에서 간식을 정할 때 고려하면 좋은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '광고 문구'), JSON_OBJECT('id', 'B', 'text', '포장 색상'), JSON_OBJECT('id', 'C', 'text', '이름의 길이'), JSON_OBJECT('id', 'D', 'text', '하루 총 섭취량과 영양 균형')), '간식도 하루 전체 열량과 영양 균형 안에서 정하는 것이 좋습니다.', 'balance', 'easy', 'D'),
       ('multiple_choice', '"반복 횟수(렙)"란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동한 날의 수'), JSON_OBJECT('id', 'B', 'text', '쉬는 시간의 길이'), JSON_OBJECT('id', 'C', 'text', '운동 기구의 무게'), JSON_OBJECT('id', 'D', 'text', '한 세트에서 같은 동작을 되풀이한 횟수')), '렙(rep)은 한 세트 안에서 동작을 한 번 수행한 횟수를 뜻합니다.', 'intensity', 'easy', 'D'),
       ('multiple_choice', '삔(염좌) 직후 흔히 알려진 초기 대처 원칙(RICE)의 R은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '휴식(Rest)'), JSON_OBJECT('id', 'B', 'text', '달리기(Run)'), JSON_OBJECT('id', 'C', 'text', '반복(Repeat)'), JSON_OBJECT('id', 'D', 'text', '회전(Rotate)')), 'RICE는 휴식, 냉찜질, 압박, 거상의 앞 글자를 딴 급성 부상 초기 관리 원칙입니다.', 'safety', 'medium', 'A'),
       ('multiple_choice', '수분 섭취를 늘리는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '물병을 가까이 두고 알림을 활용해 마시기'), JSON_OBJECT('id', 'B', 'text', '갈증을 참기'), JSON_OBJECT('id', 'C', 'text', '단 음료로 대체하기'), JSON_OBJECT('id', 'D', 'text', '식사 때만 마시기')), '물병을 곁에 두고 마시는 시간을 정하면 수분 섭취를 늘리기 쉽습니다.', 'water', 'medium', 'A'),
       ('multiple_choice', '고관절 힌지(엉덩이 접기) 동작의 핵심은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무릎만 앞으로 굽히는 것'), JSON_OBJECT('id', 'B', 'text', '허리를 둥글게 말아 숙이는 것'), JSON_OBJECT('id', 'C', 'text', '발뒤꿈치를 드는 것'), JSON_OBJECT('id', 'D', 'text', '엉덩이를 뒤로 보내며 상체를 숙이는 것')), '힌지는 허리가 아니라 고관절에서 접히며 엉덩이를 뒤로 미는 움직임입니다.', 'form', 'medium', 'D'),
       ('multiple_choice', '운동 후 심박수가 평소 상태로 돌아오는 시간이 짧아지는 것은 무엇을 시사할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동이 해롭다는 뜻'), JSON_OBJECT('id', 'B', 'text', '운동을 멈춰야 한다는 뜻'), JSON_OBJECT('id', 'C', 'text', '아무 의미 없다'), JSON_OBJECT('id', 'D', 'text', '심폐 체력이 좋아지고 있음')), '같은 강도에서 회복이 빨라지면 심폐 체력이 향상되었다고 볼 수 있습니다.', 'intensity', 'medium', 'D'),
