       ('multiple_choice', '정리운동으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '천천히 걷기와 가벼운 스트레칭'), JSON_OBJECT('id', 'B', 'text', '갑자기 앉아 가만히 있기'), JSON_OBJECT('id', 'C', 'text', '곧바로 최대 속도로 달리기'), JSON_OBJECT('id', 'D', 'text', '찬물에 바로 들어가기')), '운동 직후에는 속도를 낮추어 걷거나 가볍게 스트레칭하며 호흡을 가라앉힙니다.', 'warmup', 'easy', 'A'),
       ('multiple_choice', '혈액량과 수분의 관계로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '탈수되면 혈액량이 늘어난다'), JSON_OBJECT('id', 'B', 'text', '수분은 혈액과 무관하다'), JSON_OBJECT('id', 'C', 'text', '탈수되면 체온이 낮아진다'), JSON_OBJECT('id', 'D', 'text', '탈수되면 혈액량이 줄어 심박수가 올라갈 수 있다')), '탈수로 혈액량이 줄면 심장이 더 빨리 뛰어 보충하려 할 수 있습니다.', 'water', 'hard', 'D'),
       ('multiple_choice', '식재료를 효율적으로 사용하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '남은 채소로 국이나 볶음을 만들기'), JSON_OBJECT('id', 'B', 'text', '모두 버리기'), JSON_OBJECT('id', 'C', 'text', '방치하기'), JSON_OBJECT('id', 'D', 'text', '먹지 않기')), '남은 재료를 활용하면 낭비를 줄이고 채소 섭취도 늘릴 수 있습니다.', 'practice', 'easy', 'A'),
       ('multiple_choice', '아침 식사를 하면 좋은 점으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '반드시 살이 찐다'), JSON_OBJECT('id', 'B', 'text', '잠이 오지 않는다'), JSON_OBJECT('id', 'C', 'text', '하루 활동에 필요한 에너지를 얻는 데 도움이 된다'), JSON_OBJECT('id', 'D', 'text', '위가 약해진다')), '아침 식사는 오전 활동에 필요한 에너지와 영양소를 공급하는 데 도움이 됩니다.', 'balance', 'easy', 'C'),
       ('multiple_choice', '노년기 식단에서 특히 신경 써야 할 영양소로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '단백질, 칼슘, 비타민 D'), JSON_OBJECT('id', 'B', 'text', '설탕'), JSON_OBJECT('id', 'C', 'text', '포화지방'), JSON_OBJECT('id', 'D', 'text', '카페인')), '노년기에는 근육과 뼈 건강 유지를 위해 단백질과 칼슘, 비타민 D 섭취가 특히 중요합니다.', 'balance', 'hard', 'A'),
