       ('multiple_choice', '스쿼트 깊이를 정할 때 가장 중요한 기준은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무조건 최대로 깊게'), JSON_OBJECT('id', 'B', 'text', '통증 없이 자세를 유지하며 조절할 수 있는 범위'), JSON_OBJECT('id', 'C', 'text', '무조건 얕게'), JSON_OBJECT('id', 'D', 'text', '친구와 똑같이')), '개인의 유연성과 구조가 다르므로 통증 없이 자세를 통제할 수 있는 깊이가 기준이 됩니다.', 'form', 'hard', 'B'),
       ('multiple_choice', '고유수용성 신경근 촉진법(PNF) 스트레칭의 원리는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육을 수축했다 이완하며 가동 범위를 늘리는 것'), JSON_OBJECT('id', 'B', 'text', '근육을 끊어 길게 만드는 것'), JSON_OBJECT('id', 'C', 'text', '운동 없이 쉬는 것'), JSON_OBJECT('id', 'D', 'text', '근육을 얼리는 것')), 'PNF는 수축과 이완을 번갈아 하며 신경 반응을 활용해 유연성을 높이는 방법으로 안전한 지도가 중요합니다.', 'recovery', 'hard', 'A'),
       ('multiple_choice', '식품의 "식이섬유" 함량을 확인하면 좋은 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '장 건강과 포만감에 도움이 되는 정도를 알 수 있어서'), JSON_OBJECT('id', 'B', 'text', '열량이 가장 높아서'), JSON_OBJECT('id', 'C', 'text', '가격을 알 수 있어서'), JSON_OBJECT('id', 'D', 'text', '맛을 알 수 있어서')), '식이섬유 함량이 높은 식품은 포만감과 배변 활동에 도움이 될 수 있습니다.', 'label', 'medium', 'A'),
       ('multiple_choice', '영양소 상한 섭취량(UL)이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '최소한 먹어야 하는 양'), JSON_OBJECT('id', 'B', 'text', '건강에 해가 없다고 판단되는 하루 최대 섭취 수준'), JSON_OBJECT('id', 'C', 'text', '가장 맛있는 양'), JSON_OBJECT('id', 'D', 'text', '평균 섭취량')), 'UL을 넘어 계속 섭취하면 건강에 해로울 위험이 커질 수 있다는 기준입니다.', 'nutrients', 'hard', 'B'),
       ('multiple_choice', '식이섬유를 수용성과 불용성으로 나눌 때 불용성 식이섬유의 특징은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '물에 모두 녹는다'), JSON_OBJECT('id', 'B', 'text', '열량이 매우 높다'), JSON_OBJECT('id', 'C', 'text', '단백질로 바뀐다'), JSON_OBJECT('id', 'D', 'text', '물에 녹지 않고 배변량을 늘리는 데 도움을 준다')), '불용성 식이섬유는 장 내용물의 부피를 늘려 배변 활동을 돕습니다.', 'nutrients', 'medium', 'D'),
       ('multiple_choice', '레그 레이즈와 크런치의 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 완전히 같다'), JSON_OBJECT('id', 'B', 'text', '레그 레이즈는 하복부 쪽 개입이 크고 크런치는 상복부 쪽 개입이 큰 경향'), JSON_OBJECT('id', 'C', 'text', '레그 레이즈는 팔 운동이다'), JSON_OBJECT('id', 'D', 'text', '크런치는 하체 운동이다')), '다리를 드는 동작은 하복부와 고관절 굴곡근, 상체를 말아 올리는 동작은 상복부 쪽 개입이 큰 경향이 있습니다.', 'form', 'medium', 'B'),
       ('multiple_choice', '고립 운동의 활용 목적으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '전신을 한 번에 쓰는 것'), JSON_OBJECT('id', 'B', 'text', '운동을 쉬는 것'), JSON_OBJECT('id', 'C', 'text', '호흡을 연습하는 것'), JSON_OBJECT('id', 'D', 'text', '특정 근육을 집중해 보완하는 것')), '덤벨 컬 같은 고립 운동은 특정 근육을 집중적으로 보완하는 데 유용합니다.', 'form', 'hard', 'D'),
       ('multiple_choice', '운동하면 근육이 커지는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동하면 뼈가 늘어나서'), JSON_OBJECT('id', 'B', 'text', '피가 많아져서만'), JSON_OBJECT('id', 'C', 'text', '피부가 두꺼워져서'), JSON_OBJECT('id', 'D', 'text', '자극과 회복을 거치며 근섬유가 적응하기 때문')), '근력 운동으로 생긴 자극에 몸이 회복·적응하며 근섬유가 굵어집니다.', 'body', 'easy', 'D'),
       ('multiple_choice', '운동복을 고를 때 고려하면 좋은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '몸을 꽉 조여 호흡이 힘든 옷'), JSON_OBJECT('id', 'B', 'text', '움직임이 편하고 땀이 잘 마르는 소재'), JSON_OBJECT('id', 'C', 'text', '두꺼워서 땀이 차는 옷만'), JSON_OBJECT('id', 'D', 'text', '신발 끈이 없는 옷')), '움직임을 방해하지 않고 땀이 잘 마르는 옷은 체온 조절과 활동에 도움이 됩니다.', 'basics', 'easy', 'B'),
       ('multiple_choice', '로우(당기는) 운동에서 주로 쓰이는 근육은 어디일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '종아리'), JSON_OBJECT('id', 'B', 'text', '등과 위팔 뒤쪽·앞쪽'), JSON_OBJECT('id', 'C', 'text', '이마'), JSON_OBJECT('id', 'D', 'text', '손톱')), '당기는 동작은 등 근육과 팔의 근육이 함께 쓰이는 대표적인 운동입니다.', 'form', 'easy', 'B'),
       ('multiple_choice', '간식으로 먹기 좋은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '과일, 견과류, 무가당 요거트'), JSON_OBJECT('id', 'B', 'text', '사탕과 과자'), JSON_OBJECT('id', 'C', 'text', '탄산음료'), JSON_OBJECT('id', 'D', 'text', '튀김 과자')), '영양소를 함께 얻을 수 있는 간식이 좋습니다.', 'practice', 'easy', 'A'),
       ('multiple_choice', '운동 전 식사로 알맞은 선택은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '소화가 잘되는 탄수화물 중심의 가벼운 식사'), JSON_OBJECT('id', 'B', 'text', '기름진 튀김을 아주 많이'), JSON_OBJECT('id', 'C', 'text', '아무것도 먹지 않고 물만'), JSON_OBJECT('id', 'D', 'text', '술과 안주')), '운동 전에는 소화 부담이 적은 탄수화물을 중심으로 가볍게 먹는 것이 일반적으로 권장됩니다.', 'balance', 'medium', 'A'),
       ('multiple_choice', '열량 표시가 "100g당"일 때 알맞은 해석은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '1개를 먹었을 때의 열량이다'), JSON_OBJECT('id', 'B', 'text', '포장 전체의 열량이다'), JSON_OBJECT('id', 'C', 'text', '하루 권장 열량이다'), JSON_OBJECT('id', 'D', 'text', '100g을 먹었을 때의 열량이다')), '"100g당"은 100g 기준 열량이므로 실제 섭취량에 따라 환산해야 합니다.', 'label', 'easy', 'D'),
       ('multiple_choice', '음식을 먹기 전에 접시에 덜어 먹는 습관의 장점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '더 많이 먹게 된다'), JSON_OBJECT('id', 'B', 'text', '먹는 양을 알기 쉬워 과식을 줄일 수 있다'), JSON_OBJECT('id', 'C', 'text', '식사가 길어진다'), JSON_OBJECT('id', 'D', 'text', '식사를 잊게 된다')), '덜어 먹으면 섭취량을 눈으로 확인할 수 있어 과식을 막는 데 도움이 됩니다.', 'habit', 'easy', 'B'),
       ('multiple_choice', '운동 중 코피나 출혈이 있을 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '계속 운동하기'), JSON_OBJECT('id', 'B', 'text', '운동을 멈추고 상처를 눌러 지혈하기'), JSON_OBJECT('id', 'C', 'text', '상처를 문지르기'), JSON_OBJECT('id', 'D', 'text', '물 대신 음료를 마시기')), '출혈이 있으면 운동을 멈추고 깨끗한 천으로 압박하여 지혈해야 합니다.', 'safety', 'easy', 'B'),
       ('multiple_choice', '식품을 구입할 때 냉동식품을 마지막에 담는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무게가 가벼워서'), JSON_OBJECT('id', 'B', 'text', '포장이 예뻐서'), JSON_OBJECT('id', 'C', 'text', '가격이 싸서'), JSON_OBJECT('id', 'D', 'text', '실온에 노출되는 시간을 줄여 품질을 유지하기 위해서')), '냉동·냉장 식품은 실온에 오래 있으면 품질이 떨어져 마지막에 담고 빨리 보관합니다.', 'hygiene', 'easy', 'D'),
       ('multiple_choice', '식품첨가물 중 "보존료"의 사용 목적으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '미생물 증식을 억제해 보존성을 높이는 것'), JSON_OBJECT('id', 'B', 'text', '색을 바꾸는 것'), JSON_OBJECT('id', 'C', 'text', '맛을 쓰게 하는 것'), JSON_OBJECT('id', 'D', 'text', '열량을 높이는 것')), '보존료는 식품의 부패와 변질을 막아 저장 기간을 늘리는 데 사용됩니다.', 'label', 'hard', 'A'),
       ('multiple_choice', '혈당 지수(GI)란 무엇을 나타낼까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식품의 가격'), JSON_OBJECT('id', 'B', 'text', '식품의 무게'), JSON_OBJECT('id', 'C', 'text', '식품이 혈당을 올리는 속도와 정도의 상대적 지표'), JSON_OBJECT('id', 'D', 'text', '식품의 맛')), 'GI는 같은 양의 탄수화물을 먹었을 때 혈당이 올라가는 정도를 비교한 지표입니다.', 'nutrients', 'medium', 'C'),
       ('multiple_choice', '체중 감량을 위한 식단 실천에서 중요한 원칙은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '극단적으로 굶기'), JSON_OBJECT('id', 'B', 'text', '한 가지 음식만 먹기'), JSON_OBJECT('id', 'C', 'text', '식사를 완전히 끊기'), JSON_OBJECT('id', 'D', 'text', '영양을 유지하면서 열량을 서서히 줄이기')), '지속 가능한 감량을 위해서는 균형을 유지하며 점진적으로 조절해야 합니다.', 'practice', 'medium', 'D'),
       ('multiple_choice', '반찬 가짓수가 많은 식사가 반드시 균형 잡힌 식사일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '그렇다, 많을수록 항상 좋다'), JSON_OBJECT('id', 'B', 'text', '반찬은 적을수록 항상 좋다'), JSON_OBJECT('id', 'C', 'text', '아니다, 영양소가 고르게 포함되어야 한다'), JSON_OBJECT('id', 'D', 'text', '반찬은 영양과 무관하다')), '가짓수보다 필요한 식품군이 고르게 포함되는지가 더 중요합니다.', 'balance', 'easy', 'C'),
       ('multiple_choice', '운동 후 근육이 뻐근할 때 가벼운 걷기나 스트레칭이 도움이 되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육을 찢어 새로 만들기 때문'), JSON_OBJECT('id', 'B', 'text', '근육통을 영구적으로 없애기 때문'), JSON_OBJECT('id', 'C', 'text', '심박을 위험하게 높이기 때문'), JSON_OBJECT('id', 'D', 'text', '혈액 순환을 도와 뻐근함을 줄이는 데 도움이 되기 때문')), '가벼운 움직임은 혈액 순환을 돕고 뻐근함을 덜어 주는 데 도움이 될 수 있습니다.', 'basics', 'easy', 'D'),
       ('multiple_choice', '어깨 운동인 사이드 레터럴 레이즈에서 팔을 올리는 높이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '머리 위 끝까지'), JSON_OBJECT('id', 'B', 'text', '어깨 높이 근처'), JSON_OBJECT('id', 'C', 'text', '허리 아래까지만'), JSON_OBJECT('id', 'D', 'text', '뒤쪽으로 크게')), '일반적으로 팔을 어깨 높이 정도까지 올려 어깨 옆쪽 근육을 쓰게 합니다.', 'form', 'easy', 'B'),
