       ('multiple_choice', '운동 전 가벼운 식사를 할 때 알맞은 시간 간격은 대체로 어느 정도일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 직전 1분 전'), JSON_OBJECT('id', 'B', 'text', '운동 5시간 후에만'), JSON_OBJECT('id', 'C', 'text', '식사를 전혀 하지 않기'), JSON_OBJECT('id', 'D', 'text', '운동 1~2시간 전쯤')), '식사 직후 바로 운동하면 속이 불편할 수 있어 보통 1~2시간 정도 간격을 두고, 가벼운 간식은 더 가깝게 먹기도 합니다.', 'basics', 'easy', 'D'),
       ('multiple_choice', '식품 표시 중 "GMO(유전자변형) 표시"가 의미하는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '유전자변형 원료를 사용한 식품임을 알리는 표시'), JSON_OBJECT('id', 'B', 'text', '무조건 해로운 식품'), JSON_OBJECT('id', 'C', 'text', '유기농 식품'), JSON_OBJECT('id', 'D', 'text', '칼로리가 낮은 식품')), 'GMO 표시는 소비자가 원재료 정보를 알고 선택할 수 있도록 알리는 제도입니다.', 'label', 'medium', 'A'),
       ('multiple_choice', '장요근의 대표적인 역할은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '팔꿈치를 편다'), JSON_OBJECT('id', 'B', 'text', '목을 돌린다'), JSON_OBJECT('id', 'C', 'text', '발가락을 모은다'), JSON_OBJECT('id', 'D', 'text', '고관절을 굽혀 다리를 들어 올린다')), '장요근은 허리와 골반에서 허벅지로 이어져 다리를 앞으로 들어 올리는 데 쓰입니다.', 'body', 'medium', 'D'),
       ('multiple_choice', '식품 안전 표시에서 "HACCP" 인증이 의미하는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '맛이 가장 좋다는 의미'), JSON_OBJECT('id', 'B', 'text', '열량이 낮다는 의미'), JSON_OBJECT('id', 'C', 'text', '가격이 저렴하다는 의미'), JSON_OBJECT('id', 'D', 'text', '식품의 위해요소를 분석하고 관리하는 체계를 인증받았다는 의미')), 'HACCP은 위해요소 분석과 중요관리점 관리 체계를 통해 식품 안전을 확보하는 제도입니다.', 'label', 'hard', 'D'),
       ('multiple_choice', '위팔 뒤쪽 근육은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '상완이두근'), JSON_OBJECT('id', 'B', 'text', '상완삼두근'), JSON_OBJECT('id', 'C', 'text', '비복근'), JSON_OBJECT('id', 'D', 'text', '광배근')), '삼두근은 팔꿈치를 펼 때 쓰이는 위팔 뒤쪽 근육입니다.', 'body', 'easy', 'B'),
