       ('multiple_choice', '칼륨이 풍부한 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '설탕'), JSON_OBJECT('id', 'B', 'text', '바나나와 감자'), JSON_OBJECT('id', 'C', 'text', '식용유'), JSON_OBJECT('id', 'D', 'text', '사탕')), '바나나, 감자, 시금치 등에는 칼륨이 비교적 풍부합니다.', 'nutrients', 'easy', 'B'),
       ('multiple_choice', '운동 중 열 관련 질환을 예방하기 위한 환경 지표로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '풍향만'), JSON_OBJECT('id', 'B', 'text', '기온과 습도를 함께 보는 체감 온도나 열지수'), JSON_OBJECT('id', 'C', 'text', '조명 밝기'), JSON_OBJECT('id', 'D', 'text', '소음 크기')), '고온 다습한 날씨에서는 체감 온도가 높아 열 질환 위험이 커지므로 지수를 참고하면 도움이 됩니다.', 'safety', 'hard', 'B'),
       ('multiple_choice', '냉동식품을 구입할 때 확인할 사항으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '포장 색상만'), JSON_OBJECT('id', 'B', 'text', '이름의 길이'), JSON_OBJECT('id', 'C', 'text', '인쇄 글꼴'), JSON_OBJECT('id', 'D', 'text', '포장이 찢어지지 않았는지와 얼음 결정 상태')), '포장이 손상되었거나 해동·재냉동된 흔적이 있으면 품질과 안전에 문제가 있을 수 있습니다.', 'label', 'easy', 'D'),
       ('multiple_choice', '가슴 근육의 이름으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '광배근'), JSON_OBJECT('id', 'B', 'text', '대흉근'), JSON_OBJECT('id', 'C', 'text', '승모근'), JSON_OBJECT('id', 'D', 'text', '비복근')), '대흉근은 가슴 앞쪽에 넓게 자리한 근육으로 푸시업과 벤치 프레스에서 주로 쓰입니다.', 'body', 'easy', 'B'),
       ('multiple_choice', '식품 보관에서 "캠필로박터" 식중독을 줄이는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '닭고기를 날것으로 먹기'), JSON_OBJECT('id', 'B', 'text', '도마를 구분하지 않기'), JSON_OBJECT('id', 'C', 'text', '닭고기를 충분히 익히고 날 닭고기와 다른 식품을 분리하기'), JSON_OBJECT('id', 'D', 'text', '손을 씻지 않기')), '캠필로박터는 날 닭고기에서 흔히 발견되어 충분한 가열과 교차 오염 방지가 중요합니다.', 'hygiene', 'hard', 'C'),
       ('multiple_choice', '식사 속도를 늦추기 위해 젓가락 사용이 도움이 될 수 있는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 번에 먹는 양이 줄어들 수 있어서'), JSON_OBJECT('id', 'B', 'text', '식사량이 늘어나서'), JSON_OBJECT('id', 'C', 'text', '소화가 항상 안 돼서'), JSON_OBJECT('id', 'D', 'text', '맛이 없어져서')), '도구를 바꾸면 한 입의 양이 줄어 천천히 먹는 데 도움이 될 수 있습니다.', 'habit', 'medium', 'A'),
       ('multiple_choice', '"빈 열량(empty calories)" 식품에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '영양소가 매우 많은 식품이다'), JSON_OBJECT('id', 'B', 'text', '열량이 전혀 없는 식품이다'), JSON_OBJECT('id', 'C', 'text', '단백질이 풍부한 식품이다'), JSON_OBJECT('id', 'D', 'text', '열량은 있으나 영양소가 적은 식품이다')), '설탕이 많은 음료나 과자처럼 열량은 높지만 다른 영양소는 적은 식품을 빈 열량 식품이라고 합니다.', 'nutrients', 'medium', 'D'),
       ('multiple_choice', '식품 구매 시 "영양표시 대상 식품"과 "영양표시가 없는 식품"의 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '일부 식품은 법적으로 영양표시 의무가 없어 직접 성분을 가늠해야 한다'), JSON_OBJECT('id', 'B', 'text', '모든 식품에 영양표시가 있다'), JSON_OBJECT('id', 'C', 'text', '영양표시가 없으면 열량이 0이다'), JSON_OBJECT('id', 'D', 'text', '영양표시가 없으면 안전하지 않다')), '표시 의무 대상이 아닌 식품도 있어 이런 경우 식품 데이터베이스 등을 참고해 영양 정보를 확인할 수 있습니다.', 'label', 'medium', 'A'),
       ('multiple_choice', '레그 컬 기구는 주로 어느 근육을 쓸까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '허벅지 앞쪽'), JSON_OBJECT('id', 'B', 'text', '허벅지 뒤쪽(햄스트링)'), JSON_OBJECT('id', 'C', 'text', '복부'), JSON_OBJECT('id', 'D', 'text', '가슴')), '다리를 굽히는 동작은 허벅지 뒤쪽 햄스트링을 주로 사용합니다.', 'form', 'medium', 'B'),
       ('multiple_choice', '식사 패턴에서 단백질을 하루 세 끼에 고르게 나누는 접근의 근거로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '단백질은 저장이 무제한이라서'), JSON_OBJECT('id', 'B', 'text', '단백질은 하루 한 번만 필요해서'), JSON_OBJECT('id', 'C', 'text', '한 번에 합성할 수 있는 근단백질에 한계가 있을 수 있다는 연구'), JSON_OBJECT('id', 'D', 'text', '단백질은 열량이 없어서')), '여러 끼에 고르게 섭취하면 하루 동안 근단백질 합성을 지속적으로 돕는다는 연구가 있으나 총섭취량이 가장 중요합니다.', 'balance', 'hard', 'C'),
       ('multiple_choice', '식품 라벨에서 "총 당류"와 "첨가당"이 구분되어 있다면 의미는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 완전히 같다'), JSON_OBJECT('id', 'B', 'text', '원재료에 원래 있는 당과 가공 중 첨가된 당을 구분해 볼 수 있다'), JSON_OBJECT('id', 'C', 'text', '첨가당은 식이섬유이다'), JSON_OBJECT('id', 'D', 'text', '총 당류는 단백질이다')), '첨가당은 제조 과정에서 추가된 당으로, 섭취를 줄이도록 권고되는 항목입니다.', 'label', 'hard', 'B'),
       ('multiple_choice', '"1RM"이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 번 쉬는 시간'), JSON_OBJECT('id', 'B', 'text', '한 번 들 수 있는 최대 무게'), JSON_OBJECT('id', 'C', 'text', '1분간의 반복 횟수'), JSON_OBJECT('id', 'D', 'text', '하루 운동 시간')), '1RM은 한 번만 들 수 있는 최대 중량을 뜻하며 안전을 위해 보조자와 함께 측정하는 것이 좋습니다.', 'intensity', 'hard', 'B'),
       ('multiple_choice', '근력 운동에서 같은 무게를 계속 쓰면 어떻게 될까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '몸이 적응해 더 이상 자극이 줄어들 수 있다'), JSON_OBJECT('id', 'B', 'text', '항상 더 강해진다'), JSON_OBJECT('id', 'C', 'text', '근육이 사라진다'), JSON_OBJECT('id', 'D', 'text', '관절이 강해진다')), '몸은 적응하므로 자극을 이어가려면 횟수·무게·난이도를 조금씩 조절해야 합니다.', 'intensity', 'easy', 'A'),
       ('multiple_choice', '전경골근은 어디에 있고 무엇을 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '허벅지 뒤쪽에서 무릎을 굽힌다'), JSON_OBJECT('id', 'B', 'text', '등에서 팔을 당긴다'), JSON_OBJECT('id', 'C', 'text', '정강이 앞쪽에서 발끝을 위로 당긴다'), JSON_OBJECT('id', 'D', 'text', '어깨에서 팔을 든다')), '전경골근은 정강이 앞쪽에 있으며 발목을 위로 들어 올려 걸을 때 발이 걸리지 않게 합니다.', 'body', 'medium', 'C'),
       ('multiple_choice', '엎드려서 하는 플랭크가 어려울 때 난이도를 낮추는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손을 발보다 낮게 두기'), JSON_OBJECT('id', 'B', 'text', '다리를 높이 들기'), JSON_OBJECT('id', 'C', 'text', '눈을 감기'), JSON_OBJECT('id', 'D', 'text', '무릎을 대고 하거나 손을 높은 곳에 올리기')), '무릎을 대거나 손을 의자 위에 올리면 체중 부담이 줄어 자세를 유지하기 쉽습니다.', 'form', 'medium', 'D'),
       ('multiple_choice', '푸시업 중 팔꿈치를 너무 벌리면 어떤 부담이 생길 수 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손목이 강해진다'), JSON_OBJECT('id', 'B', 'text', '허리가 펴진다'), JSON_OBJECT('id', 'C', 'text', '종아리가 풀린다'), JSON_OBJECT('id', 'D', 'text', '어깨 관절에 부담이 커질 수 있다')), '팔꿈치를 몸통과 약 45도 정도로 두면 어깨 관절의 부담이 줄어듭니다.', 'form', 'medium', 'D'),
       ('multiple_choice', '수면이 부족하면 운동 수행에 어떤 영향이 있을 수 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '항상 더 좋아진다'), JSON_OBJECT('id', 'B', 'text', '집중력과 힘이 떨어지고 부상 위험이 커질 수 있다'), JSON_OBJECT('id', 'C', 'text', '체력이 즉시 회복된다'), JSON_OBJECT('id', 'D', 'text', '아무 영향이 없다')), '수면이 부족하면 반응 속도, 힘, 집중력이 떨어져 수행과 안전에 영향을 줄 수 있습니다.', 'recovery', 'easy', 'B'),
       ('multiple_choice', '쌀과 콩을 함께 먹는 것이 영양적으로 좋은 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '서로 부족한 아미노산을 보완하기 때문'), JSON_OBJECT('id', 'B', 'text', '열량이 0이 되어서'), JSON_OBJECT('id', 'C', 'text', '소화가 되지 않아서'), JSON_OBJECT('id', 'D', 'text', '비타민이 사라져서')), '곡류와 콩류는 서로 부족한 필수 아미노산을 보완해 단백질의 질을 높일 수 있습니다.', 'nutrients', 'medium', 'A'),
       ('multiple_choice', '근육 이완을 위한 호흡법으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '숨 참기'), JSON_OBJECT('id', 'B', 'text', '아주 빠른 호흡'), JSON_OBJECT('id', 'C', 'text', '복식호흡(배로 천천히 호흡)'), JSON_OBJECT('id', 'D', 'text', '입을 막고 호흡')), '복식호흡은 몸의 긴장을 낮추고 안정감을 주는 호흡법입니다.', 'recovery', 'medium', 'C'),
       ('multiple_choice', '운동 중 숨이 너무 차오를 때 알맞은 행동은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '더 세게 달리기'), JSON_OBJECT('id', 'B', 'text', '숨을 참기'), JSON_OBJECT('id', 'C', 'text', '속도를 줄이거나 잠시 쉬며 호흡 고르기'), JSON_OBJECT('id', 'D', 'text', '무시하고 계속하기')), '숨이 가쁘면 강도를 낮추고 호흡을 안정시켜야 합니다.', 'safety', 'easy', 'C'),
       ('multiple_choice', '식품을 살 때 신선도를 확인하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무게만 확인하기'), JSON_OBJECT('id', 'B', 'text', '색, 냄새, 탄력 등을 확인하기'), JSON_OBJECT('id', 'C', 'text', '가격만 확인하기'), JSON_OBJECT('id', 'D', 'text', '포장만 확인하기')), '신선식품은 색과 냄새, 탄력 등을 살펴 신선도를 판단할 수 있습니다.', 'label', 'easy', 'B'),
       ('multiple_choice', '동적 스트레칭의 예로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 자세로 1분 가만히 있기'), JSON_OBJECT('id', 'B', 'text', '누워서 쉬기'), JSON_OBJECT('id', 'C', 'text', '다리를 앞뒤로 천천히 흔들기'), JSON_OBJECT('id', 'D', 'text', '앉아서 눈 감기')), '레그 스윙처럼 관절을 움직이며 근육을 늘리는 동작이 동적 스트레칭입니다.', 'warmup', 'medium', 'C'),
       ('multiple_choice', '햄스트링을 구성하는 근육 개수로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 개'), JSON_OBJECT('id', 'B', 'text', '다섯 개'), JSON_OBJECT('id', 'C', 'text', '열 개'), JSON_OBJECT('id', 'D', 'text', '세 개(반건양근, 반막양근, 대퇴이두근)')), '햄스트링은 반건양근, 반막양근, 대퇴이두근 세 근육으로 구성됩니다.', 'body', 'hard', 'D'),
       ('multiple_choice', '탄수화물을 지나치게 적게 먹는 식사의 위험으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '키가 자란다'), JSON_OBJECT('id', 'B', 'text', '에너지 부족과 피로, 영양 불균형 가능성'), JSON_OBJECT('id', 'C', 'text', '시력이 좋아진다'), JSON_OBJECT('id', 'D', 'text', '항상 건강해진다')), '탄수화물을 극단적으로 줄이면 에너지와 식이섬유, 영양소의 균형이 깨질 수 있습니다.', 'nutrients', 'medium', 'B'),
       ('multiple_choice', '운동을 마친 뒤 땀에 젖은 옷을 오래 입고 있으면 어떤 점이 좋지 않을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 바로 커진다'), JSON_OBJECT('id', 'B', 'text', '심박수가 영구히 높아진다'), JSON_OBJECT('id', 'C', 'text', '뼈가 튼튼해진다'), JSON_OBJECT('id', 'D', 'text', '체온이 떨어져 몸이 차가워질 수 있다')), '젖은 옷은 체온을 빼앗아 몸이 식고 감기에 걸린 듯한 느낌이 들 수 있으니 운동 후 마른 옷으로 갈아입는 것이 좋습니다.', 'basics', 'easy', 'D'),
       ('multiple_choice', '운동 후 가벼운 스트레칭을 하는 목적은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육을 사라지게 하려고'), JSON_OBJECT('id', 'B', 'text', '심박수를 올리려고'), JSON_OBJECT('id', 'C', 'text', '근육의 긴장을 풀고 유연성을 유지하려고'), JSON_OBJECT('id', 'D', 'text', '운동 기록을 쓰려고')), '운동 후 스트레칭은 긴장을 풀고 가동 범위를 유지하는 데 도움이 됩니다.', 'recovery', 'easy', 'C'),
       ('multiple_choice', '소변 색이 매우 진한 노란색일 때 가능한 의미는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '수분이 부족할 수 있다'), JSON_OBJECT('id', 'B', 'text', '수분이 넘친다'), JSON_OBJECT('id', 'C', 'text', '운동을 너무 안 했다'), JSON_OBJECT('id', 'D', 'text', '영양이 과다하다')), '진한 소변색은 수분 부족의 신호일 수 있어 물을 충분히 마시는 것이 좋습니다.', 'water', 'easy', 'A'),
       ('multiple_choice', '수용성 비타민에 해당하는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '비타민 A와 D'), JSON_OBJECT('id', 'B', 'text', '비타민 E와 K'), JSON_OBJECT('id', 'C', 'text', '철과 아연'), JSON_OBJECT('id', 'D', 'text', '비타민 B군과 C')), '비타민 B군과 C는 물에 녹는 수용성 비타민으로 몸에 오래 저장되지 않습니다.', 'nutrients', 'medium', 'D'),
       ('multiple_choice', '스쿼트에서 무릎이 발끝을 넘어가는 것에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '절대 넘어가서는 안 되고 넘으면 무릎이 부러진다'), JSON_OBJECT('id', 'B', 'text', '무조건 금지는 아니며 발목 유연성과 자세에 따라 다르다'), JSON_OBJECT('id', 'C', 'text', '넘어갈수록 항상 안전하다'), JSON_OBJECT('id', 'D', 'text', '발끝과 무릎은 서로 관련이 없다')), '무릎이 발끝을 약간 넘어가는 것은 흔한 움직임이며 중요한 것은 균형, 통증 없음, 체중 분배입니다.', 'form', 'hard', 'B'),
       ('multiple_choice', '식품군별 섭취 횟수를 정하는 식사 구성안이 개인에게 유용한 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '필요 에너지에 맞게 식품군별 섭취 횟수를 쉽게 정할 수 있어서'), JSON_OBJECT('id', 'B', 'text', '모든 사람이 똑같은 양을 먹게 해서'), JSON_OBJECT('id', 'C', 'text', '식비를 늘려서'), JSON_OBJECT('id', 'D', 'text', '식사 시간을 줄여서')), '식사 구성안은 열량 수준별로 식품군별 권장 횟수를 제시해 개인의 필요에 맞게 적용하기 쉽습니다.', 'balance', 'hard', 'A'),
       ('multiple_choice', '세트 간 휴식 시간이 너무 짧으면 어떤 일이 생기기 쉬울까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '항상 효과가 더 커진다'), JSON_OBJECT('id', 'B', 'text', '근육이 더 빨리 회복된다'), JSON_OBJECT('id', 'C', 'text', '회복이 부족해 다음 세트의 자세와 횟수가 떨어질 수 있다'), JSON_OBJECT('id', 'D', 'text', '피로가 사라진다')), '충분히 회복하지 못하면 이어지는 세트에서 수행 능력이 떨어지기 쉽습니다.', 'intensity', 'medium', 'C'),
       ('multiple_choice', '정적 스트레칭을 한 부위를 유지하는 시간으로 흔히 권장되는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '약 15~30초'), JSON_OBJECT('id', 'B', 'text', '1초'), JSON_OBJECT('id', 'C', 'text', '10분'), JSON_OBJECT('id', 'D', 'text', '1시간')), '많은 지침이 한 자세를 15~30초 정도 유지하는 정적 스트레칭을 제시합니다.', 'recovery', 'medium', 'A'),
       ('multiple_choice', '비타민의 역할로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '몸의 기능을 조절하는 데 필요하다'), JSON_OBJECT('id', 'B', 'text', '에너지를 가장 많이 낸다'), JSON_OBJECT('id', 'C', 'text', '근육만 만든다'), JSON_OBJECT('id', 'D', 'text', '몸에서 필요 없다')), '비타민은 열량은 거의 없지만 대사와 몸의 기능 조절에 꼭 필요한 영양소입니다.', 'nutrients', 'easy', 'A'),
       ('multiple_choice', '고온 환경에서 운동 시 수분과 나트륨 보충이 함께 필요한 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '땀에는 물만 있어서'), JSON_OBJECT('id', 'B', 'text', '나트륨은 해로워서'), JSON_OBJECT('id', 'C', 'text', '수분은 필요 없어서'), JSON_OBJECT('id', 'D', 'text', '땀으로 수분과 나트륨이 함께 손실되기 때문')), '땀에는 나트륨이 포함되어 있어 장시간 활동 시 함께 보충해야 할 수 있습니다.', 'water', 'hard', 'D'),
       ('multiple_choice', '식품 알레르기와 식품 불내증의 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 완전히 같다'), JSON_OBJECT('id', 'B', 'text', '불내증은 면역 반응이다'), JSON_OBJECT('id', 'C', 'text', '알레르기는 면역 반응이고 불내증은 소화·대사 문제인 경우가 많다'), JSON_OBJECT('id', 'D', 'text', '알레르기는 소화 문제이다')), '식품 알레르기는 면역 반응이 관여하고 불내증은 주로 소화·대사 이상과 관련됩니다.', 'nutrients', 'hard', 'C'),
       ('multiple_choice', '"배고픈 상태로 장보기"가 식습관에 미치는 영향은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '건강한 식품만 사게 된다'), JSON_OBJECT('id', 'B', 'text', '식비가 항상 줄어든다'), JSON_OBJECT('id', 'C', 'text', '영향이 없다'), JSON_OBJECT('id', 'D', 'text', '충동구매와 고열량 식품 구입이 늘기 쉽다')), '허기 상태에서는 간식이나 고열량 식품을 더 많이 사기 쉽습니다.', 'habit', 'medium', 'D'),
       ('multiple_choice', '목 스트레칭을 할 때 알맞은 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '목을 빠르게 뒤로 젖히기'), JSON_OBJECT('id', 'B', 'text', '목을 세게 비틀기'), JSON_OBJECT('id', 'C', 'text', '천천히 부드럽게 움직이기'), JSON_OBJECT('id', 'D', 'text', '반동을 크게 주기')), '목은 민감한 부위이므로 천천히 부드럽게만 움직여야 합니다.', 'warmup', 'easy', 'C'),
       ('multiple_choice', '무기질에 해당하는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '포도당'), JSON_OBJECT('id', 'B', 'text', '칼슘'), JSON_OBJECT('id', 'C', 'text', '아미노산'), JSON_OBJECT('id', 'D', 'text', '지방산')), '칼슘, 철, 칼륨, 나트륨 등이 무기질에 해당합니다.', 'nutrients', 'easy', 'B'),
       ('multiple_choice', '질환이 있는 사람이 식단을 바꿀 때 알맞은 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '인터넷 정보만 따르기'), JSON_OBJECT('id', 'B', 'text', '의사나 영양사와 상의해 개인에게 맞는 식단 계획하기'), JSON_OBJECT('id', 'C', 'text', '약을 임의로 끊기'), JSON_OBJECT('id', 'D', 'text', '식사를 거르기')), '질환에 따라 필요한 영양과 제한이 달라 전문가와 상의해야 합니다.', 'practice', 'hard', 'B'),
       ('multiple_choice', '근육 회복에서 단백질 섭취를 하루 여러 끼에 나누어 먹는 방식이 제안되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '단백질이 사라지게 하려고'), JSON_OBJECT('id', 'B', 'text', '식사를 줄이려고'), JSON_OBJECT('id', 'C', 'text', '체중을 늘리려고'), JSON_OBJECT('id', 'D', 'text', '근육 합성을 지속적으로 자극하려고')), '여러 끼로 나누어 섭취하면 하루 동안 근단백질 합성을 지속적으로 돕는다는 연구가 있지만 총 섭취량이 더 중요합니다.', 'recovery', 'hard', 'D'),
       ('multiple_choice', '근력이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '오래 걷는 능력'), JSON_OBJECT('id', 'B', 'text', '유연한 정도'), JSON_OBJECT('id', 'C', 'text', '체온'), JSON_OBJECT('id', 'D', 'text', '근육이 낼 수 있는 힘의 크기')), '근력은 근육이 발휘할 수 있는 힘의 정도를 말합니다.', 'body', 'easy', 'D'),
       ('multiple_choice', '준비운동의 가장 큰 목적은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동을 일찍 끝내기'), JSON_OBJECT('id', 'B', 'text', '피로를 쌓기'), JSON_OBJECT('id', 'C', 'text', '몸을 서서히 깨워 운동에 대비시키기'), JSON_OBJECT('id', 'D', 'text', '체중을 바로 줄이기')), '준비운동은 체온과 심박수를 서서히 올리고 관절과 근육을 움직일 준비를 시켜 줍니다.', 'warmup', 'easy', 'C'),
       ('multiple_choice', '브릿지(엉덩이 들기) 동작에서 주로 쓰이는 근육은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손가락'), JSON_OBJECT('id', 'B', 'text', '이마'), JSON_OBJECT('id', 'C', 'text', '귓불'), JSON_OBJECT('id', 'D', 'text', '엉덩이와 허벅지 뒤쪽')), '누워서 엉덩이를 들어 올리면 둔근과 햄스트링이 주로 일합니다.', 'form', 'easy', 'D'),
       ('multiple_choice', 'MET(메트)은 무엇을 나타내는 단위일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육의 길이'), JSON_OBJECT('id', 'B', 'text', '운동 장소의 넓이'), JSON_OBJECT('id', 'C', 'text', '활동 시 에너지 소비를 안정 시 대비 몇 배인지 나타낸 값'), JSON_OBJECT('id', 'D', 'text', '땀의 양')), 'MET은 안정 상태의 에너지 소비를 1로 두고, 활동의 에너지 소비가 그 몇 배인지를 나타내는 값입니다.', 'basics', 'medium', 'C'),
       ('multiple_choice', '흉통이나 심한 호흡 곤란이 운동 중 생겼을 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '즉시 중단하고 응급 도움 요청하기'), JSON_OBJECT('id', 'B', 'text', '참고 계속하기'), JSON_OBJECT('id', 'C', 'text', '더 빨리 하기'), JSON_OBJECT('id', 'D', 'text', '잠시 눈 감고 무시하기')), '가슴 통증이나 심한 호흡 곤란은 응급 신호일 수 있어 즉시 중단하고 도움을 요청해야 합니다.', 'safety', 'medium', 'A'),
       ('multiple_choice', '음식을 재가열할 때 알맞은 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '미지근하게만 데우기'), JSON_OBJECT('id', 'B', 'text', '겉만 데우기'), JSON_OBJECT('id', 'C', 'text', '데우지 않고 먹기'), JSON_OBJECT('id', 'D', 'text', '속까지 충분히 뜨겁게 데워 먹기')), '재가열할 때는 중심까지 충분히 가열해야 세균을 줄일 수 있습니다.', 'hygiene', 'medium', 'D'),
       ('multiple_choice', '"1회 제공량"이 총 내용량보다 작을 때 주의할 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '아무것도 곱할 필요가 없다'), JSON_OBJECT('id', 'B', 'text', '포장째 먹으면 열량이 줄어든다'), JSON_OBJECT('id', 'C', 'text', '제공량은 의미가 없다'), JSON_OBJECT('id', 'D', 'text', '포장 전체를 먹으면 표시된 영양 값에 제공 횟수를 곱해야 한다')), '포장 전체를 먹었다면 1회 제공량 기준 영양 값을 먹은 횟수만큼 곱해 계산해야 합니다.', 'label', 'easy', 'D'),
       ('multiple_choice', '남은 음식을 보관하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '뜨거운 채로 실온에 두기'), JSON_OBJECT('id', 'B', 'text', '뚜껑 없이 방치하기'), JSON_OBJECT('id', 'C', 'text', '햇빛에 두기'), JSON_OBJECT('id', 'D', 'text', '식힌 뒤 뚜껑을 덮어 냉장 보관하기')), '남은 음식은 빨리 식혀 밀폐 용기에 담아 냉장하는 것이 좋습니다.', 'hygiene', 'easy', 'D'),
       ('multiple_choice', '식사 중 음료를 마시는 속도와 양이 식사에 미치는 영향으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사가 항상 불가능해진다'), JSON_OBJECT('id', 'B', 'text', '영양이 늘어난다'), JSON_OBJECT('id', 'C', 'text', '과하게 마시면 포만감이 먼저 와 영양 섭취가 줄 수 있다'), JSON_OBJECT('id', 'D', 'text', '열량이 사라진다')), '음료를 많이 마시면 배가 불러 영양가 있는 음식을 충분히 먹지 못할 수 있습니다.', 'habit', 'medium', 'C'),
       ('multiple_choice', '식재료를 사서 보관하기 전에 해야 할 일로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모두 실온에 두기'), JSON_OBJECT('id', 'B', 'text', '모두 한 봉지에 담기'), JSON_OBJECT('id', 'C', 'text', '씻지 않고 오래 두기'), JSON_OBJECT('id', 'D', 'text', '종류별로 구분해 냉장·냉동·실온 보관하기')), '식품 특성에 맞게 보관 온도를 구분하면 신선도와 안전성을 유지할 수 있습니다.', 'label', 'medium', 'D'),
       ('multiple_choice', '혈당을 천천히 올리는 경향이 있는 탄수화물 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '설탕'), JSON_OBJECT('id', 'B', 'text', '사탕'), JSON_OBJECT('id', 'C', 'text', '통곡물'), JSON_OBJECT('id', 'D', 'text', '탄산음료')), '통곡물처럼 식이섬유가 많은 식품은 소화·흡수가 비교적 느립니다.', 'nutrients', 'medium', 'C'),
       ('multiple_choice', '다음 중 포화지방이 비교적 많은 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '두부'), JSON_OBJECT('id', 'B', 'text', '삼겹살과 버터'), JSON_OBJECT('id', 'C', 'text', '오이'), JSON_OBJECT('id', 'D', 'text', '현미')), '동물성 지방과 버터 등에는 포화지방이 비교적 많이 들어 있습니다.', 'nutrients', 'easy', 'B'),
       ('multiple_choice', '필수 아미노산을 충분히 포함한 단백질을 일반적으로 무엇이라고 부를까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '불완전 지방'), JSON_OBJECT('id', 'B', 'text', '단순 탄수화물'), JSON_OBJECT('id', 'C', 'text', '복합 비타민'), JSON_OBJECT('id', 'D', 'text', '완전 단백질')), '필수 아미노산을 골고루 갖춘 단백질을 완전 단백질이라고 부르며 달걀과 우유 등이 해당합니다.', 'nutrients', 'medium', 'D'),
       ('multiple_choice', '윗몸 일으키기에서 허리를 지나치게 꺾으면 어떤 위험이 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 사라진다'), JSON_OBJECT('id', 'B', 'text', '허리에 부담이 갈 수 있다'), JSON_OBJECT('id', 'C', 'text', '키가 줄어든다'), JSON_OBJECT('id', 'D', 'text', '체온이 떨어진다')), '허리를 과하게 젖히거나 반동으로 움직이면 척추에 불필요한 부담이 커질 수 있습니다.', 'form', 'easy', 'B'),
       ('multiple_choice', '정적 스트레칭 한 자세를 유지하는 일반적인 시간은 어느 정도일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '1초'), JSON_OBJECT('id', 'B', 'text', '10분'), JSON_OBJECT('id', 'C', 'text', '1시간'), JSON_OBJECT('id', 'D', 'text', '15~30초')), '대부분의 지침은 한 자세를 약 15~30초 유지하도록 안내합니다.', 'warmup', 'medium', 'D'),
       ('multiple_choice', '식품의 열량을 줄이려 할 때 확인해야 할 정보로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '포장 색'), JSON_OBJECT('id', 'B', 'text', '1회 제공량과 열량, 당류·지방 함량'), JSON_OBJECT('id', 'C', 'text', '제품 이름'), JSON_OBJECT('id', 'D', 'text', '제조사 이름')), '같은 제공량에서 열량과 당류·지방을 비교하면 더 가벼운 선택을 할 수 있습니다.', 'label', 'medium', 'B'),
       ('multiple_choice', '근육통이 있을 때 같은 부위 대신 다른 부위를 운동하는 방법을 무엇이라고 부를까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 중단'), JSON_OBJECT('id', 'B', 'text', '무리한 운동'), JSON_OBJECT('id', 'C', 'text', '회복 불가'), JSON_OBJECT('id', 'D', 'text', '분할 운동으로 회복 시간을 확보하는 방법')), '부위별로 운동을 나누면 같은 근육에 회복할 시간을 줄 수 있습니다.', 'recovery', 'medium', 'D'),
       ('multiple_choice', '식사 전 물 한 컵을 마시는 습관에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '포만감을 느끼는 데 도움이 될 수 있다'), JSON_OBJECT('id', 'B', 'text', '식사가 항상 불가능해진다'), JSON_OBJECT('id', 'C', 'text', '열량이 크게 늘어난다'), JSON_OBJECT('id', 'D', 'text', '소화가 항상 안 된다')), '식전 물 섭취는 포만감에 도움이 될 수 있다는 연구가 있습니다.', 'habit', 'easy', 'A'),
       ('multiple_choice', '걷기 운동의 장점으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '반드시 헬스장이 필요하다'), JSON_OBJECT('id', 'B', 'text', '특별한 장비 없이 쉽게 시작할 수 있다'), JSON_OBJECT('id', 'C', 'text', '비싼 기구가 있어야 한다'), JSON_OBJECT('id', 'D', 'text', '하루 세 시간 이상 해야만 효과가 있다')), '걷기는 장소와 장비의 제약이 적어 누구나 쉽게 시작할 수 있는 대표적인 유산소 운동입니다.', 'basics', 'easy', 'B'),
       ('multiple_choice', '준비운동이 부상을 줄인다는 연구 결과를 해석할 때 알맞은 태도는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '종목과 방식에 따라 근거 수준이 다르므로 과장 없이 권장 정도로 이해하기'), JSON_OBJECT('id', 'B', 'text', '준비운동이 모든 부상을 100% 막는다고 믿기'), JSON_OBJECT('id', 'C', 'text', '준비운동은 완전히 무의미하다고 믿기'), JSON_OBJECT('id', 'D', 'text', '준비운동은 개인차가 없다고 믿기')), '준비운동은 일반적으로 권장되지만 모든 부상을 막는다고 단정할 수는 없고 종목·방식에 따라 근거 수준이 다릅니다.', 'warmup', 'hard', 'A'),
       ('multiple_choice', '팔굽혀펴기를 할 때 몇 번 반복할지에 대한 알맞은 기준은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '자세가 무너져도 계속하기'), JSON_OBJECT('id', 'B', 'text', '무조건 100회'), JSON_OBJECT('id', 'C', 'text', '무조건 1회'), JSON_OBJECT('id', 'D', 'text', '자세가 무너지기 전까지 가능한 횟수')), '정확한 자세를 유지할 수 있는 범위에서 횟수를 정하는 것이 안전하고 효과적입니다.', 'form', 'easy', 'D'),
       ('multiple_choice', '유기농 표시가 있는 식품에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '열량이 없다'), JSON_OBJECT('id', 'B', 'text', '재배 방식 기준을 인증받았다는 의미이며 영양소가 항상 더 많다는 뜻은 아니다'), JSON_OBJECT('id', 'C', 'text', '항상 영양소가 더 많다'), JSON_OBJECT('id', 'D', 'text', '항상 가격이 싸다')), '유기농은 재배와 생산 방식에 대한 인증이며 영양 성분이 반드시 높다는 뜻은 아닙니다.', 'label', 'medium', 'B'),
       ('multiple_choice', '혈당이 급격히 오르는 것을 줄이려는 식사 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '당 음료를 먼저 마시기'), JSON_OBJECT('id', 'B', 'text', '채소와 단백질을 먼저 먹고 탄수화물을 나중에 먹기'), JSON_OBJECT('id', 'C', 'text', '탄수화물만 먹기'), JSON_OBJECT('id', 'D', 'text', '식사를 거르기')), '식이섬유와 단백질을 먼저 먹으면 식후 혈당 상승을 완만하게 하는 데 도움이 될 수 있다는 연구가 있습니다.', 'balance', 'medium', 'B'),
       ('multiple_choice', '운동 직후 격렬한 스트레칭이 권장되지 않는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 효과가 사라져서'), JSON_OBJECT('id', 'B', 'text', '체온이 오르지 않아서'), JSON_OBJECT('id', 'C', 'text', '근육이 피로한 상태에서 과하게 늘리면 손상 위험이 있어서'), JSON_OBJECT('id', 'D', 'text', '호흡이 막혀서')), '피로한 근육은 부드럽게 다루는 것이 안전하므로 가볍게 천천히 늘리는 것이 좋습니다.', 'recovery', 'medium', 'C'),
       ('multiple_choice', '식품을 비교할 때 나트륨과 포화지방, 당류를 함께 보는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '맛이 같아서'), JSON_OBJECT('id', 'B', 'text', '가격이 같아서'), JSON_OBJECT('id', 'C', 'text', '건강에 영향을 줄 수 있는 대표 성분이어서'), JSON_OBJECT('id', 'D', 'text', '색이 같아서')), '나트륨, 포화지방, 당류는 과다 섭취 시 건강에 부담이 될 수 있는 성분으로 비교 기준이 됩니다.', 'label', 'medium', 'C'),
       ('multiple_choice', '나트륨을 많이 섭취하면 어떤 점에 주의해야 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '키가 크게 자란다'), JSON_OBJECT('id', 'B', 'text', '시력이 좋아진다'), JSON_OBJECT('id', 'C', 'text', '피부가 항상 좋아진다'), JSON_OBJECT('id', 'D', 'text', '혈압 등 건강에 영향을 줄 수 있다')), '나트륨을 많이 먹으면 혈압 등에 영향을 줄 수 있어 적정량을 지키는 것이 좋습니다.', 'nutrients', 'easy', 'D'),
       ('multiple_choice', '운동 전 가볍게 걷거나 제자리에서 걷는 것은 어떤 효과를 줄까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '혈압을 위험하게 높인다'), JSON_OBJECT('id', 'B', 'text', '심박수와 체온을 서서히 높인다'), JSON_OBJECT('id', 'C', 'text', '근육을 약하게 만든다'), JSON_OBJECT('id', 'D', 'text', '관절을 굳게 만든다')), '가벼운 걷기는 부담 없이 심박과 체온을 올리는 쉬운 준비운동입니다.', 'warmup', 'easy', 'B'),
       ('multiple_choice', '식이섬유가 풍부한 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '설탕'), JSON_OBJECT('id', 'B', 'text', '식용유'), JSON_OBJECT('id', 'C', 'text', '채소와 통곡물'), JSON_OBJECT('id', 'D', 'text', '탄산음료')), '채소, 과일, 통곡물, 콩류에 식이섬유가 풍부합니다.', 'nutrients', 'easy', 'C'),
       ('multiple_choice', '정서적 스트레스를 줄이는 활동이 운동 회복에 도움이 될 수 있는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육을 줄여서'), JSON_OBJECT('id', 'B', 'text', '체온을 낮춰서'), JSON_OBJECT('id', 'C', 'text', '호흡을 멈춰서'), JSON_OBJECT('id', 'D', 'text', '수면과 회복 능력을 개선할 수 있어서')), '스트레스를 줄이면 수면의 질이 좋아지고 회복에 유리한 상태를 만들 수 있습니다.', 'recovery', 'hard', 'D'),
       ('multiple_choice', '스쿼트로 앉을 때 엉덩이는 어느 방향으로 움직이는 느낌이 좋을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '앞쪽과 위쪽'), JSON_OBJECT('id', 'B', 'text', '옆쪽만'), JSON_OBJECT('id', 'C', 'text', '뒤쪽과 아래쪽'), JSON_OBJECT('id', 'D', 'text', '움직이지 않는다')), '의자에 앉듯 엉덩이를 뒤로 보내며 내려가면 무릎에 쏠리는 부담을 줄이고 균형을 잡기 쉽습니다.', 'form', 'easy', 'C'),
       ('multiple_choice', '운동 기구의 상태를 점검하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '확인 없이 바로 사용하기'), JSON_OBJECT('id', 'B', 'text', '고장 난 기구도 사용하기'), JSON_OBJECT('id', 'C', 'text', '사용 전 고정 부품과 손상 여부를 확인하기'), JSON_OBJECT('id', 'D', 'text', '무게만 확인하기')), '기구가 파손되었거나 고정이 느슨하면 사고로 이어질 수 있어 사용 전에 점검해야 합니다.', 'safety', 'medium', 'C'),
       ('multiple_choice', '식습관 개선에서 "자기 효능감"이 중요한 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사량을 늘리게 해서'), JSON_OBJECT('id', 'B', 'text', '식사를 건너뛰게 해서'), JSON_OBJECT('id', 'C', 'text', '할 수 있다는 믿음이 행동을 지속하는 데 도움이 되어서'), JSON_OBJECT('id', 'D', 'text', '체중을 늘려서')), '작은 성공 경험을 쌓으면 자신감이 생겨 습관을 오래 유지하기 쉽습니다.', 'habit', 'hard', 'C'),
       ('multiple_choice', '점진적 과부하를 적용하는 방법으로 알맞지 않은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '반복 횟수를 조금 늘리기'), JSON_OBJECT('id', 'B', 'text', '세트 수를 조금 늘리기'), JSON_OBJECT('id', 'C', 'text', '무게를 소폭 올리기'), JSON_OBJECT('id', 'D', 'text', '한 번에 무게를 두 배로 올리기')), '급격한 증가는 부상 위험을 키우므로 작은 단위로 조절하는 것이 일반적입니다.', 'intensity', 'hard', 'D'),
       ('multiple_choice', '운동 중 심박수 구간(존) 개념의 활용 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 구간을 무시한다'), JSON_OBJECT('id', 'B', 'text', '항상 최대 구간에서만 한다'), JSON_OBJECT('id', 'C', 'text', '쉬는 시간에만 본다'), JSON_OBJECT('id', 'D', 'text', '목표에 맞는 강도 범위에서 운동하도록 가이드로 쓴다')), '심박수 구간은 운동 목적에 맞는 강도로 조절하는 가이드로 활용할 수 있습니다.', 'intensity', 'hard', 'D'),
       ('multiple_choice', '하루 중 물을 마시는 습관을 만드는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사 때와 활동 후, 물병을 곁에 두고 조금씩 마시기'), JSON_OBJECT('id', 'B', 'text', '한 번에 몰아 마시기'), JSON_OBJECT('id', 'C', 'text', '갈증이 심할 때만 마시기'), JSON_OBJECT('id', 'D', 'text', '음료만 마시기')), '물병을 가까이 두고 틈틈이 마시면 하루 수분 섭취를 늘리기 쉽습니다.', 'habit', 'easy', 'A'),
       ('multiple_choice', '카프 레이즈(발뒤꿈치 들기)는 주로 어느 부위를 쓸까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '어깨'), JSON_OBJECT('id', 'B', 'text', '복부'), JSON_OBJECT('id', 'C', 'text', '손목'), JSON_OBJECT('id', 'D', 'text', '종아리')), '발뒤꿈치를 들어 올리는 동작은 종아리 근육을 주로 사용합니다.', 'form', 'easy', 'D'),
       ('multiple_choice', '운동 전 준비 운동을 하는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체온과 심박수를 서서히 올려 부상 위험을 줄이려고'), JSON_OBJECT('id', 'B', 'text', '운동을 건너뛰려고'), JSON_OBJECT('id', 'C', 'text', '근육을 식히려고'), JSON_OBJECT('id', 'D', 'text', '호흡을 멈추려고')), '준비 운동은 몸을 서서히 데워 관절과 근육이 운동에 대비하도록 돕습니다.', 'safety', 'easy', 'A'),
       ('multiple_choice', '숄더 프레스에서 허리를 과하게 젖히면 어떤 문제가 생길 수 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '허리에 부담이 가고 어깨 자극이 줄 수 있다'), JSON_OBJECT('id', 'B', 'text', '운동 효과가 두 배가 된다'), JSON_OBJECT('id', 'C', 'text', '체온이 낮아진다'), JSON_OBJECT('id', 'D', 'text', '호흡이 필요 없어진다')), '허리를 꺾어 올리면 허리가 힘들어지고 어깨 근육에 가야 할 자극이 분산됩니다.', 'form', 'medium', 'A'),
       ('multiple_choice', '비슷한 가공식품 두 가지를 비교할 때 유용한 순서는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '포장 디자인 → 가격 → 이름'), JSON_OBJECT('id', 'B', 'text', '색상 → 모양 → 크기'), JSON_OBJECT('id', 'C', 'text', '광고 문구만'), JSON_OBJECT('id', 'D', 'text', '제공량 확인 → 열량 → 나트륨·당류·포화지방 → 원재료명')), '같은 기준량으로 맞춘 뒤 주요 성분과 원재료를 차례로 보는 방법이 체계적입니다.', 'label', 'medium', 'D'),
       ('multiple_choice', '철분 흡수를 방해할 수 있는 요소로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사와 함께 마시는 차나 커피의 탄닌 등'), JSON_OBJECT('id', 'B', 'text', '비타민 C'), JSON_OBJECT('id', 'C', 'text', '고기 단백질'), JSON_OBJECT('id', 'D', 'text', '수분')), '탄닌 등 일부 성분은 비헴철의 흡수를 줄일 수 있다고 알려져 있습니다.', 'nutrients', 'medium', 'A'),
       ('multiple_choice', '근육통이 운동 후 24~72시간 사이에 가장 심해지는 현상을 무엇이라고 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '급성 골절'), JSON_OBJECT('id', 'B', 'text', '지연성 근육통'), JSON_OBJECT('id', 'C', 'text', '탈수증'), JSON_OBJECT('id', 'D', 'text', '빈혈')), '낯선 운동 후 하루~이틀 뒤 나타나는 근육통을 지연성 근육통(DOMS)이라고 합니다.', 'recovery', 'medium', 'B'),
       ('multiple_choice', '우유·유제품군에 해당하는 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '두부'), JSON_OBJECT('id', 'B', 'text', '우유, 치즈, 요거트'), JSON_OBJECT('id', 'C', 'text', '쌀'), JSON_OBJECT('id', 'D', 'text', '사과')), '우유와 치즈, 요거트는 칼슘이 풍부한 유제품군에 속합니다.', 'balance', 'easy', 'B'),
       ('multiple_choice', '식사 습관을 점검할 때 "식사 간격"을 확인하는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사 간격은 의미가 없어서'), JSON_OBJECT('id', 'B', 'text', '식사 간격이 짧을수록 항상 좋아서'), JSON_OBJECT('id', 'C', 'text', '식사를 줄이기 위해서'), JSON_OBJECT('id', 'D', 'text', '너무 긴 간격이나 너무 잦은 섭취가 폭식·과식과 연결될 수 있어서')), '식사 간격은 허기 조절과 식사량에 영향을 줍니다.', 'habit', 'medium', 'D'),
       ('multiple_choice', '풀업에서 데드행(매달리기)을 훈련하는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '악력과 어깨 안정성을 키워 풀업을 준비하기 위해'), JSON_OBJECT('id', 'B', 'text', '근육을 줄이기 위해'), JSON_OBJECT('id', 'C', 'text', '호흡을 멈추기 위해'), JSON_OBJECT('id', 'D', 'text', '발을 쉬게 하기 위해')), '매달리기는 악력과 견갑 안정성을 길러 풀업을 준비하는 데 도움이 됩니다.', 'form', 'hard', 'A'),
       ('multiple_choice', '식사 후 간식 욕구를 줄이는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사를 줄이기'), JSON_OBJECT('id', 'B', 'text', '당 음료를 마시기'), JSON_OBJECT('id', 'C', 'text', '식사에서 단백질과 식이섬유를 충분히 먹기'), JSON_OBJECT('id', 'D', 'text', '식사를 빨리 끝내기')), '단백질과 식이섬유는 포만감을 오래 유지하는 데 도움이 됩니다.', 'habit', 'medium', 'C'),
       ('multiple_choice', '회복을 위해 쉬는 날에도 완전히 움직이지 않는 것이 항상 최선은 아닌 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '가벼운 활동이 혈액순환과 회복을 도울 수 있어서'), JSON_OBJECT('id', 'B', 'text', '쉬는 날에는 근육이 사라져서'), JSON_OBJECT('id', 'C', 'text', '움직임은 항상 해로워서'), JSON_OBJECT('id', 'D', 'text', '가벼운 활동은 없어서')), '가벼운 활동은 혈액순환을 도와 회복을 돕고 활동적인 생활 습관을 유지하게 합니다.', 'recovery', 'hard', 'A'),
       ('true_false', '지방 1g의 열량은 탄수화물 1g보다 낮다.', NULL, '지방은 1g당 약 9kcal로 탄수화물(약 4kcal)보다 높습니다.', '영양', 'easy', 'X'),
       ('multiple_choice', '걷기, 가볍게 달리기, 자전거 타기처럼 호흡과 심박이 오래 올라가는 운동을 무엇이라고 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무산소 근력 운동'), JSON_OBJECT('id', 'B', 'text', '유산소 운동'), JSON_OBJECT('id', 'C', 'text', '유연성 운동'), JSON_OBJECT('id', 'D', 'text', '균형 운동')), '유산소 운동은 큰 근육을 리듬감 있게 오래 움직여 심장과 폐를 단련하는 운동입니다. 걷기, 수영, 자전거 타기가 대표적입니다.', 'basics', 'easy', 'B'),
       ('multiple_choice', '풀업과 친업(손바닥이 얼굴 쪽)의 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '두 동작은 완전히 같다'), JSON_OBJECT('id', 'B', 'text', '친업은 이두근 개입이 상대적으로 커진다'), JSON_OBJECT('id', 'C', 'text', '친업은 다리 운동이다'), JSON_OBJECT('id', 'D', 'text', '풀업은 팔을 쓰지 않는다')), '손바닥이 얼굴 쪽을 향하면 이두근이 더 많이 쓰이는 경향이 있습니다.', 'form', 'hard', 'B'),
       ('multiple_choice', '회복을 위한 영양 섭취에서 수분과 함께 고려할 전해질로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '납'), JSON_OBJECT('id', 'B', 'text', '나트륨·칼륨 등'), JSON_OBJECT('id', 'C', 'text', '수은'), JSON_OBJECT('id', 'D', 'text', '비소')), '땀으로 나트륨 등이 빠지므로 장시간 운동에는 전해질 보충을 고려할 수 있습니다.', 'recovery', 'medium', 'B'),
       ('multiple_choice', '힘줄과 근육이 만나는 부위에서 부담이 반복되면 생기는 대표적인 문제는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '골다공증'), JSON_OBJECT('id', 'B', 'text', '고혈압'), JSON_OBJECT('id', 'C', 'text', '건염(힘줄염)'), JSON_OBJECT('id', 'D', 'text', '빈혈')), '반복적인 과부하로 힘줄에 염증과 통증이 생기는 상태를 건염이라고 합니다.', 'body', 'hard', 'C'),
       ('multiple_choice', '식품의 영양성분 표시에서 "알레르기 표시"와 "영양성분표"의 역할 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '알레르기 표시는 안전을, 영양성분표는 영양 정보를 알리는 역할을 한다'), JSON_OBJECT('id', 'B', 'text', '둘은 같은 정보다'), JSON_OBJECT('id', 'C', 'text', '알레르기 표시는 맛을 알린다'), JSON_OBJECT('id', 'D', 'text', '영양성분표는 가격을 알린다')), '알레르기 표시는 알레르기 유발 원료를, 영양성분표는 열량과 영양소 함량을 알려 줍니다.', 'label', 'hard', 'A'),
       ('multiple_choice', '일상의 비운동성 활동 열량 소비를 가리키는 말로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '일상 활동 에너지 소비'), JSON_OBJECT('id', 'B', 'text', '운동 후 초과 산소 소비만'), JSON_OBJECT('id', 'C', 'text', '기초대사량만'), JSON_OBJECT('id', 'D', 'text', '수면 중 호흡')), '운동 외의 걷기, 서 있기, 집안일 같은 일상 활동도 에너지를 소비하며 하루 소비량에 큰 몫을 차지합니다.', 'basics', 'medium', 'A'),
       ('multiple_choice', '코어 근육으로 흔히 포함되는 복횡근의 역할은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '팔을 올린다'), JSON_OBJECT('id', 'B', 'text', '무릎을 편다'), JSON_OBJECT('id', 'C', 'text', '발목을 돌린다'), JSON_OBJECT('id', 'D', 'text', '복부를 안쪽으로 감싸 몸통을 안정시킨다')), '복횡근은 복부 깊은 곳에서 배를 감싸며 몸통의 안정에 기여합니다.', 'body', 'medium', 'D'),
       ('multiple_choice', '정리운동 시 가볍게 움직이는 것이 혈액 순환에 도움이 된다고 보는 이유와 가까운 설명은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 심장을 대신해 뛰기 때문'), JSON_OBJECT('id', 'B', 'text', '혈관이 사라지기 때문'), JSON_OBJECT('id', 'C', 'text', '근육 수축이 혈액을 심장 쪽으로 돌려보내는 데 도움을 준다'), JSON_OBJECT('id', 'D', 'text', '호흡이 필요 없어지기 때문')), '다리 근육의 수축은 정맥혈이 심장으로 돌아오는 것을 도와 운동 직후 갑작스러운 멈춤으로 인한 어지러움을 줄이는 데 기여합니다.', 'warmup', 'hard', 'C'),
       ('multiple_choice', '건강한 식습관을 위해 집에 두면 좋은 간식은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '과자와 사탕'), JSON_OBJECT('id', 'B', 'text', '탄산음료'), JSON_OBJECT('id', 'C', 'text', '튀김 과자'), JSON_OBJECT('id', 'D', 'text', '과일, 견과류, 무가당 요거트')), '건강한 간식을 가까이 두면 선택하기 쉬워집니다.', 'habit', 'easy', 'D'),
       ('multiple_choice', '"DASH 식단"의 목적으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체온을 높이는 식단'), JSON_OBJECT('id', 'B', 'text', '탄수화물만 먹는 식단'), JSON_OBJECT('id', 'C', 'text', '혈압 관리를 위한 식단'), JSON_OBJECT('id', 'D', 'text', '단식 식단')), 'DASH 식단은 채소, 과일, 저지방 유제품을 늘리고 나트륨을 줄여 혈압 관리에 초점을 둔 식사 패턴입니다.', 'balance', 'hard', 'C'),
       ('multiple_choice', '덤벨 벤치 프레스가 바벨 벤치 프레스보다 가지는 특징으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '양팔이 따로 움직여 좌우 균형과 가동 범위를 더 쓰기 쉽다'), JSON_OBJECT('id', 'B', 'text', '항상 더 무거운 무게를 쓸 수 있다'), JSON_OBJECT('id', 'C', 'text', '안정성이 필요 없다'), JSON_OBJECT('id', 'D', 'text', '어깨를 전혀 쓰지 않는다')), '덤벨은 각 팔이 독립적으로 움직여 좌우 균형을 드러내고 가동 범위를 넓게 쓸 수 있습니다.', 'form', 'medium', 'A'),
       ('multiple_choice', '턱걸이를 못하는 사람이 점진적으로 연습하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '처음부터 한 번에 10회 시도하기'), JSON_OBJECT('id', 'B', 'text', '아프더라도 반동으로 올라가기'), JSON_OBJECT('id', 'C', 'text', '밴드 보조나 낮은 바에서 하는 인버티드 로우로 시작하기'), JSON_OBJECT('id', 'D', 'text', '턱걸이는 연습할 수 없다고 생각하기')), '밴드 보조나 몸을 비스듬히 하는 로우 운동은 당기는 힘을 단계적으로 키우는 방법입니다.', 'form', 'medium', 'C'),
       ('multiple_choice', '운동의 주요 변수 중 하나인 "볼륨"은 무엇을 뜻할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 장소의 크기'), JSON_OBJECT('id', 'B', 'text', '운동할 때의 소리'), JSON_OBJECT('id', 'C', 'text', '총 운동량(세트×반복×무게 등)'), JSON_OBJECT('id', 'D', 'text', '운동복의 양')), '볼륨은 세트, 반복, 무게 등을 종합한 총운동량을 가리키는 표현입니다.', 'intensity', 'hard', 'C'),
       ('multiple_choice', '등척성 수축의 예로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '덤벨을 올리는 동작'), JSON_OBJECT('id', 'B', 'text', '점프하는 동작'), JSON_OBJECT('id', 'C', 'text', '플랭크처럼 길이 변화 없이 버티는 동작'), JSON_OBJECT('id', 'D', 'text', '달리는 동작')), '등척성 수축은 관절 움직임 없이 근육이 힘을 유지하는 수축으로 플랭크가 대표적입니다.', 'body', 'medium', 'C'),
       ('multiple_choice', '열량(칼로리)이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '음식의 맛 정도'), JSON_OBJECT('id', 'B', 'text', '음식의 무게'), JSON_OBJECT('id', 'C', 'text', '음식이 몸에서 낼 수 있는 에너지의 양'), JSON_OBJECT('id', 'D', 'text', '음식의 가격')), '열량은 음식이 우리 몸에서 에너지로 쓰일 수 있는 양을 나타냅니다.', 'nutrients', 'easy', 'C'),
       ('true_false', 'WHO는 성인의 나트륨 섭취를 하루 2,000mg 미만으로 권고한다.', NULL, 'WHO는 성인 나트륨 섭취를 하루 2g(2,000mg) 미만으로 권고합니다.', '식단', 'medium', 'O'),
       ('multiple_choice', '정적 스트레칭이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '뛰면서 하는 스트레칭'), JSON_OBJECT('id', 'B', 'text', '공중에서 하는 스트레칭'), JSON_OBJECT('id', 'C', 'text', '자세를 일정 시간 유지하며 근육을 늘리는 스트레칭'), JSON_OBJECT('id', 'D', 'text', '물속에서만 하는 스트레칭')), '근육을 천천히 늘려 15~30초쯤 자세를 유지하는 스트레칭이 정적 스트레칭입니다.', 'warmup', 'easy', 'C'),
       ('multiple_choice', '냉장고 정리를 통해 식단을 개선하는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '간식을 앞에 두기'), JSON_OBJECT('id', 'B', 'text', '정리하지 않기'), JSON_OBJECT('id', 'C', 'text', '식품을 오래 방치하기'), JSON_OBJECT('id', 'D', 'text', '건강한 식품을 앞쪽에 두고 유통기한을 확인하기')), '건강한 식품이 잘 보이게 두면 선택하기 쉽습니다.', 'practice', 'easy', 'D'),
