       ('multiple_choice', '간식으로 비교적 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '탄산음료와 사탕'), JSON_OBJECT('id', 'B', 'text', '과일이나 견과류, 요거트'), JSON_OBJECT('id', 'C', 'text', '초콜릿 과자만'), JSON_OBJECT('id', 'D', 'text', '튀긴 과자')), '과일, 견과류, 무가당 요거트는 영양소를 함께 얻기 좋은 간식입니다.', 'balance', 'easy', 'B'),
       ('multiple_choice', '운동 일정에서 몸이 아프거나 열이 있을 때 알맞은 선택은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '평소보다 더 강하게 운동하기'), JSON_OBJECT('id', 'B', 'text', '운동을 쉬고 회복에 집중하기'), JSON_OBJECT('id', 'C', 'text', '땀을 빼면 낫는다고 생각하기'), JSON_OBJECT('id', 'D', 'text', '수분 섭취 줄이기')), '열이 있거나 몸이 아플 때는 쉬는 것이 안전하며 회복 후 천천히 복귀해야 합니다.', 'safety', 'hard', 'B'),
       ('multiple_choice', '식사 습관 개선을 방해하는 환경 요인으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '눈에 잘 띄는 고열량 간식과 쉬운 접근성'), JSON_OBJECT('id', 'B', 'text', '물병을 곁에 두는 것'), JSON_OBJECT('id', 'C', 'text', '채소를 쉽게 먹을 수 있는 환경'), JSON_OBJECT('id', 'D', 'text', '식사 계획표')), '고열량 간식이 쉽게 눈에 띄고 접근하기 쉬우면 충동적으로 먹기 쉽습니다.', 'habit', 'hard', 'A'),
       ('multiple_choice', '건강한 식습관을 가족이 함께 만들어 가는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 사람만 지키게 하기'), JSON_OBJECT('id', 'B', 'text', '식사 규칙을 정하고 함께 요리하고 먹기'), JSON_OBJECT('id', 'C', 'text', '식사를 따로 하기'), JSON_OBJECT('id', 'D', 'text', '규칙 없이 먹기')), '가족이 함께 식사 규칙과 식단을 정하면 건강한 습관을 이어가기 쉽습니다.', 'habit', 'medium', 'B'),
       ('multiple_choice', '다음 중 철이 풍부한 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '사탕'), JSON_OBJECT('id', 'B', 'text', '탄산수'), JSON_OBJECT('id', 'C', 'text', '식용유'), JSON_OBJECT('id', 'D', 'text', '소고기와 시금치')), '붉은 살코기, 간, 시금치, 콩류 등에 철이 들어 있습니다.', 'nutrients', 'easy', 'D'),
