       ('multiple_choice', '발 간격과 발 방향이 사람마다 다를 수 있는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모두의 골격이 똑같아서'), JSON_OBJECT('id', 'B', 'text', '발 방향은 중요하지 않아서'), JSON_OBJECT('id', 'C', 'text', '고관절 구조와 유연성 등이 개인마다 달라서'), JSON_OBJECT('id', 'D', 'text', '의학 규정으로 정해져 있어서')), '고관절의 모양과 가동성이 다르므로 같은 스쿼트라도 편안한 발 간격과 방향이 사람마다 다릅니다.', 'form', 'hard', 'C'),
       ('multiple_choice', '운동 후 두통이나 구토가 지속될 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동을 계속하기'), JSON_OBJECT('id', 'B', 'text', '운동을 중단하고 쉬며 증상이 계속되면 진료받기'), JSON_OBJECT('id', 'C', 'text', '더 세게 운동하기'), JSON_OBJECT('id', 'D', 'text', '물 마시지 않기')), '지속적인 두통이나 구토는 탈수나 다른 원인일 수 있어 쉬고 필요하면 진료를 받아야 합니다.', 'safety', 'medium', 'B'),
