       ('multiple_choice', '동적 스트레칭이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 자세로 가만히 있는 스트레칭'), JSON_OBJECT('id', 'B', 'text', '몸을 움직이면서 하는 스트레칭'), JSON_OBJECT('id', 'C', 'text', '잠자며 하는 스트레칭'), JSON_OBJECT('id', 'D', 'text', '숨을 참고 하는 스트레칭')), '다리 흔들기, 팔 돌리기처럼 움직이며 근육을 늘리는 방식이 동적 스트레칭입니다.', 'warmup', 'easy', 'B'),
       ('multiple_choice', '가공식품의 "전성분 표시"를 읽는 습관이 필요한 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '맛을 알기 위해서'), JSON_OBJECT('id', 'B', 'text', '가격을 알기 위해서'), JSON_OBJECT('id', 'C', 'text', '원재료와 첨가물을 알고 알레르기와 영양 선택에 활용하기 위해서'), JSON_OBJECT('id', 'D', 'text', '디자인을 알기 위해서')), '전성분을 확인하면 알레르기 유발 원료와 첨가물, 당 사용 여부를 알 수 있습니다.', 'label', 'hard', 'C'),
       ('multiple_choice', '영양표시의 "영양소 함량 강조 표시"에서 "저(low)"와 "무(free)" 표시의 의미 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 같은 의미다'), JSON_OBJECT('id', 'B', 'text', '"무"는 반드시 0이다'), JSON_OBJECT('id', 'C', 'text', '"무"는 일정 기준 이하의 아주 적은 양이어도 사용할 수 있고 "저"는 기준보다 낮은 정도를 뜻한다'), JSON_OBJECT('id', 'D', 'text', '"저"는 반드시 0이다')), '강조 표시마다 법적 기준이 있어 "무"도 일정 기준 이하의 아주 적은 양을 의미하는 경우가 있습니다.', 'label', 'hard', 'C'),
       ('multiple_choice', '노로바이러스 식중독 예방 수칙으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손 씻기와 굴 등 어패류를 충분히 익혀 먹기'), JSON_OBJECT('id', 'B', 'text', '날것으로 많이 먹기'), JSON_OBJECT('id', 'C', 'text', '손을 씻지 않기'), JSON_OBJECT('id', 'D', 'text', '물을 마시지 않기')), '노로바이러스는 손과 오염된 식품을 통해 퍼지며 익혀 먹고 손을 씻는 것이 중요합니다.', 'hygiene', 'hard', 'A'),
       ('multiple_choice', '계단 오르기는 어떤 종류의 운동에 가까울까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '상체 스트레칭 운동'), JSON_OBJECT('id', 'B', 'text', '유산소와 하체 근력을 함께 쓰는 운동'), JSON_OBJECT('id', 'C', 'text', '호흡만 하는 운동'), JSON_OBJECT('id', 'D', 'text', '휴식에 해당하는 활동')), '계단을 오르면 심박이 올라가고 허벅지와 엉덩이 근육도 쓰이므로 유산소와 하체 근력 효과를 함께 얻을 수 있습니다.', 'basics', 'easy', 'B'),
       ('multiple_choice', '체력 요소 중 순발력이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '오랜 시간 천천히 걷는 능력'), JSON_OBJECT('id', 'B', 'text', '관절이 부드럽게 휘는 정도'), JSON_OBJECT('id', 'C', 'text', '숨을 오래 참는 능력'), JSON_OBJECT('id', 'D', 'text', '짧은 시간에 큰 힘을 빠르게 내는 능력')), '순발력은 힘과 속도를 결합해 짧은 순간에 폭발적으로 힘을 내는 능력으로 점프나 스프린트에서 중요합니다.', 'basics', 'medium', 'D'),
       ('multiple_choice', '지방이 소화·흡수에서 맡는 역할로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '단백질을 파괴한다'), JSON_OBJECT('id', 'B', 'text', '수분을 없앤다'), JSON_OBJECT('id', 'C', 'text', '무기질을 만든다'), JSON_OBJECT('id', 'D', 'text', '지용성 비타민의 흡수를 돕는다')), '지방은 지용성 비타민(A, D, E, K)의 흡수를 돕는 역할을 합니다.', 'nutrients', 'medium', 'D'),
       ('multiple_choice', '가벼운 줄넘기나 제자리 뛰기는 준비운동으로 어떻게 활용될 수 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '낮은 강도로 짧게 하며 심박을 올릴 수 있다'), JSON_OBJECT('id', 'B', 'text', '전력으로만 해야 한다'), JSON_OBJECT('id', 'C', 'text', '준비운동에 쓰면 안 된다'), JSON_OBJECT('id', 'D', 'text', '정리운동 후에만 쓴다')), '낮은 강도로 짧게 하면 심박과 체온을 올리는 준비운동으로 활용할 수 있습니다.', 'warmup', 'easy', 'A'),
       ('multiple_choice', '운동 전 휴대전화나 소지품을 정리하는 습관이 안전에 도움이 되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 효과가 두 배가 된다'), JSON_OBJECT('id', 'B', 'text', '체중이 즉시 줄어든다'), JSON_OBJECT('id', 'C', 'text', '운동 중 걸리거나 떨어뜨리는 사고를 줄일 수 있다'), JSON_OBJECT('id', 'D', 'text', '호흡이 필요 없어진다')), '주머니의 물건이나 줄은 운동 중 방해가 되거나 떨어져 다칠 수 있어 미리 정리하는 것이 좋습니다.', 'basics', 'easy', 'C'),
       ('multiple_choice', '"1회 섭취 참고량"과 "1회 제공량"의 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 같다'), JSON_OBJECT('id', 'B', 'text', '참고량은 가격이다'), JSON_OBJECT('id', 'C', 'text', '참고량은 식품군별 일반 섭취 기준이고 제공량은 제품에 표시된 한 번 먹는 양이다'), JSON_OBJECT('id', 'D', 'text', '제공량은 무게가 아니다')), '식품 유형별 참고량과 제품의 제공량은 다를 수 있어 표시를 확인해야 합니다.', 'label', 'medium', 'C'),
       ('multiple_choice', '가정에서 식품 안전을 지키는 "5대 핵심 요령"에 포함되는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '맛 내기, 양념하기, 데우기, 식히기, 버리기'), JSON_OBJECT('id', 'B', 'text', '냉동하기, 해동하기, 재냉동하기, 씻기, 닦기'), JSON_OBJECT('id', 'C', 'text', '굽기, 튀기기, 볶기, 삶기, 찌기'), JSON_OBJECT('id', 'D', 'text', '청결 유지, 생식품과 익힌 식품 분리, 완전히 익히기, 안전한 온도 유지, 안전한 물과 재료 사용')), 'WHO가 제시한 식품 안전 5대 요령은 청결, 분리, 가열, 온도 유지, 안전한 재료 사용입니다.', 'hygiene', 'hard', 'D'),
       ('multiple_choice', '아침에 소변량이 줄고 색이 진해질 수 있는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동을 많이 해서'), JSON_OBJECT('id', 'B', 'text', '밤사이 수분을 마시지 못해서'), JSON_OBJECT('id', 'C', 'text', '식사를 많이 해서'), JSON_OBJECT('id', 'D', 'text', '비타민을 먹어서')), '수면 중에 수분 섭취가 없어 소변이 농축될 수 있습니다.', 'water', 'medium', 'B'),
       ('multiple_choice', '3대 영양소에 해당하는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '비타민, 무기질, 물'), JSON_OBJECT('id', 'B', 'text', '탄수화물, 단백질, 지방'), JSON_OBJECT('id', 'C', 'text', '나트륨, 칼륨, 칼슘'), JSON_OBJECT('id', 'D', 'text', '섬유질, 색소, 향')), '에너지를 내는 3대 영양소는 탄수화물, 단백질, 지방입니다.', 'nutrients', 'easy', 'B'),
       ('multiple_choice', '요가나 스트레칭 수업 중 한계까지 억지로 밀어붙이는 것은 왜 위험할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '유연성이 영구히 사라진다'), JSON_OBJECT('id', 'B', 'text', '체온이 낮아진다'), JSON_OBJECT('id', 'C', 'text', '근육과 관절 조직이 손상될 수 있다'), JSON_OBJECT('id', 'D', 'text', '심박이 정지한다')), '통증을 참고 한계 너머로 밀어붙이면 근육·힘줄·관절에 손상이 생길 수 있습니다.', 'warmup', 'medium', 'C'),
       ('multiple_choice', '"마음챙김 식사"란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '빠르게 먹는 방법'), JSON_OBJECT('id', 'B', 'text', '음식의 맛, 향, 식감과 몸의 포만감에 집중하며 먹는 방법'), JSON_OBJECT('id', 'C', 'text', '음식을 보지 않고 먹는 방법'), JSON_OBJECT('id', 'D', 'text', '한 번에 많이 먹는 방법')), '마음챙김 식사는 식사에 주의를 기울여 포만감을 알아차리고 천천히 즐기는 방법입니다.', 'habit', 'medium', 'B'),
       ('multiple_choice', '다음 중 칼슘이 풍부한 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '설탕'), JSON_OBJECT('id', 'B', 'text', '사이다'), JSON_OBJECT('id', 'C', 'text', '우유와 멸치'), JSON_OBJECT('id', 'D', 'text', '식용유')), '우유, 요거트, 멸치, 두부 등은 칼슘이 풍부한 식품입니다.', 'nutrients', 'easy', 'C'),
       ('multiple_choice', '운동 동작에서 가동 범위(ROM)란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동하는 장소의 넓이'), JSON_OBJECT('id', 'B', 'text', '운동 시간'), JSON_OBJECT('id', 'C', 'text', '운동 횟수'), JSON_OBJECT('id', 'D', 'text', '관절이 움직이는 범위')), '가동 범위는 관절이 움직일 수 있는 각도나 거리를 뜻합니다.', 'form', 'medium', 'D'),
       ('multiple_choice', '운동 후 몸이 약간 뻐근한 근육통이 이틀 정도 이어지는 현상은 흔히 무엇이라 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '심장 이상 신호'), JSON_OBJECT('id', 'B', 'text', '뼈 골절'), JSON_OBJECT('id', 'C', 'text', '지연성 근육통'), JSON_OBJECT('id', 'D', 'text', '탈수 증상')), '익숙하지 않은 운동 뒤 하루 이틀 후에 나타나는 근육통을 지연성 근육통이라 합니다. 보통 며칠 안에 좋아집니다.', 'basics', 'easy', 'C'),
       ('multiple_choice', '당류와 전분의 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 완전히 같은 물질이다'), JSON_OBJECT('id', 'B', 'text', '전분은 단백질이다'), JSON_OBJECT('id', 'C', 'text', '당류는 지방이다'), JSON_OBJECT('id', 'D', 'text', '당류는 단순한 구조이고 전분은 여러 당이 길게 연결된 구조다')), '당류는 포도당, 과당 등 작은 분자이고 전분은 포도당이 길게 연결된 복합 탄수화물입니다.', 'nutrients', 'medium', 'D'),
       ('multiple_choice', '식품 포장지의 "총 내용량"이 의미하는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 번에 먹는 양'), JSON_OBJECT('id', 'B', 'text', '포장 전체에 들어 있는 양'), JSON_OBJECT('id', 'C', 'text', '권장 하루 섭취량'), JSON_OBJECT('id', 'D', 'text', '제품의 가격')), '총 내용량은 포장 안의 전체 양이며 1회 제공량과 다를 수 있습니다.', 'label', 'easy', 'B'),
       ('multiple_choice', '런지 중 균형이 잡히지 않을 때 알맞은 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '더 세게 점프하기'), JSON_OBJECT('id', 'B', 'text', '눈을 감고 하기'), JSON_OBJECT('id', 'C', 'text', '발 간격과 보폭을 조정하거나 벽을 가볍게 짚기'), JSON_OBJECT('id', 'D', 'text', '숨을 참고 하기')), '발 간격을 넓혀 안정감을 확보하거나 지지물을 가볍게 짚으면 동작을 익히기 쉽습니다.', 'form', 'easy', 'C'),
       ('multiple_choice', '근육 불균형의 예로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한쪽 근력이 다른 쪽보다 크게 약하거나 앞뒤 근육 힘의 차이가 큰 것'), JSON_OBJECT('id', 'B', 'text', '양쪽이 정확히 같은 근력'), JSON_OBJECT('id', 'C', 'text', '운동을 하지 않아 근육이 없는 것'), JSON_OBJECT('id', 'D', 'text', '키가 큰 것')), '좌우나 길항근 간 힘의 차이가 커지면 움직임의 균형이 깨지고 부상 위험이 커질 수 있습니다.', 'body', 'hard', 'A'),
       ('multiple_choice', '추운 날 야외 운동 후 땀이 식으면 어떻게 하는 것이 좋을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '젖은 옷으로 계속 서 있기'), JSON_OBJECT('id', 'B', 'text', '찬 바람 속에서 더 오래 있기'), JSON_OBJECT('id', 'C', 'text', '옷을 벗고 서 있기'), JSON_OBJECT('id', 'D', 'text', '바로 따뜻한 옷으로 갈아입기')), '땀이 식으면 체온이 빠르게 떨어질 수 있어 바로 마른 옷으로 갈아입고 보온하는 것이 좋습니다.', 'warmup', 'easy', 'D'),
       ('multiple_choice', '랫 풀다운에서 바를 당길 때 알맞은 방향은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '가슴 위쪽 방향으로 당기기'), JSON_OBJECT('id', 'B', 'text', '목 뒤로 힘껏 당기기'), JSON_OBJECT('id', 'C', 'text', '허리까지 당기기'), JSON_OBJECT('id', 'D', 'text', '머리 위로 밀기')), '바를 가슴 앞으로 당기면 어깨와 목에 무리 없이 등 근육을 쓸 수 있습니다.', 'form', 'medium', 'A'),
       ('multiple_choice', '배달 음식을 먹을 때 균형을 맞추는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '튀김을 추가하기'), JSON_OBJECT('id', 'B', 'text', '채소를 직접 곁들이고 국물과 소스는 줄이기'), JSON_OBJECT('id', 'C', 'text', '탄산음료를 추가하기'), JSON_OBJECT('id', 'D', 'text', '소스를 더 넣기')), '배달 음식에 채소를 추가하고 국물이나 소스를 줄이면 영양 균형에 도움이 됩니다.', 'balance', 'medium', 'B'),
       ('multiple_choice', '런지에서 앞발 무릎의 알맞은 위치는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '발목 위쪽 근처이며 발끝을 크게 넘지 않기'), JSON_OBJECT('id', 'B', 'text', '발끝보다 훨씬 앞으로 나가기'), JSON_OBJECT('id', 'C', 'text', '안쪽으로 크게 무너지기'), JSON_OBJECT('id', 'D', 'text', '뒤쪽으로 빠지기')), '앞무릎이 발목 위에 있으면 무릎 관절의 부담이 적고 균형을 잡기 쉽습니다.', 'form', 'easy', 'A'),
       ('multiple_choice', '추운 날 야외 운동에서 알맞은 준비는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '얇은 옷 한 장'), JSON_OBJECT('id', 'B', 'text', '준비 운동 없이 바로 달리기'), JSON_OBJECT('id', 'C', 'text', '겹쳐 입어 체온을 조절하고 충분히 몸 풀기'), JSON_OBJECT('id', 'D', 'text', '젖은 옷 입기')), '추위에서는 근육이 굳기 쉬워 겹쳐 입고 준비 운동을 길게 하는 것이 안전합니다.', 'safety', 'medium', 'C'),
       ('multiple_choice', '운동 직후 갑자기 멈추면 일어날 수 있는 일은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 즉시 커진다'), JSON_OBJECT('id', 'B', 'text', '어지러움이 생길 수 있다'), JSON_OBJECT('id', 'C', 'text', '체중이 즉시 줄어든다'), JSON_OBJECT('id', 'D', 'text', '피로가 완전히 사라진다')), '달리기 직후 갑자기 멈추면 혈액이 다리에 몰려 어지러울 수 있어 천천히 속도를 줄이는 것이 좋습니다.', 'warmup', 'easy', 'B'),
       ('multiple_choice', '점진적 과부하란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 없이 쉬는 것'), JSON_OBJECT('id', 'B', 'text', '운동 자극을 조금씩 늘려 가는 원리'), JSON_OBJECT('id', 'C', 'text', '무게를 갑자기 두 배로 올리는 것'), JSON_OBJECT('id', 'D', 'text', '운동 종류를 매일 바꾸는 것')), '횟수·무게·세트 등을 서서히 늘려 몸이 계속 적응하도록 하는 원리입니다.', 'intensity', 'medium', 'B'),
       ('multiple_choice', '장을 볼 때 도움이 되는 습관은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '장보기 목록을 미리 작성하기'), JSON_OBJECT('id', 'B', 'text', '배고플 때 장보기'), JSON_OBJECT('id', 'C', 'text', '충동구매하기'), JSON_OBJECT('id', 'D', 'text', '목록 없이 많이 사기')), '목록을 쓰면 불필요한 가공식품 구입을 줄이고 계획적으로 장을 볼 수 있습니다.', 'practice', 'easy', 'A'),
       ('multiple_choice', '근력 운동 중 세트 사이에 가볍게 걷거나 흔들어 주는 것은 어떤 의도일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동을 포기하려고'), JSON_OBJECT('id', 'B', 'text', '근육을 줄이려고'), JSON_OBJECT('id', 'C', 'text', '체온을 낮추려고'), JSON_OBJECT('id', 'D', 'text', '혈액 순환을 유지하고 다음 세트를 준비')), '세트 사이의 가벼운 움직임은 순환을 돕고 긴장을 풀어 다음 세트 준비에 도움이 됩니다.', 'warmup', 'medium', 'D'),
       ('true_false', '공복 유산소 운동을 하면 체지방이 무조건 더 많이 빠진다.', NULL, '공복 운동이 무조건 더 효과적이라는 근거는 부족하며, 하루 전체 섭취와 소비가 더 중요합니다.', '운동', 'medium', 'X'),
       ('multiple_choice', '식품의 가공 정도를 판단하는 단서로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '원재료 수와 첨가물 종류'), JSON_OBJECT('id', 'B', 'text', '포장지 크기'), JSON_OBJECT('id', 'C', 'text', '제품 이름 길이'), JSON_OBJECT('id', 'D', 'text', '진열 위치')), '원재료 목록이 길고 첨가물이 많을수록 가공 정도가 높은 경향이 있습니다.', 'label', 'medium', 'A'),
       ('true_false', '플랭크는 복부와 허리 등 코어 근육을 강화하는 운동이다.', NULL, '플랭크는 몸통을 버티며 코어 근육을 단련하는 대표적인 운동입니다.', '운동', 'easy', 'O'),
       ('multiple_choice', '근육은 무엇에 의해 움직일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '뼈가 스스로 늘어나서'), JSON_OBJECT('id', 'B', 'text', '근육이 수축하여 뼈를 당겨서'), JSON_OBJECT('id', 'C', 'text', '피부가 당겨서'), JSON_OBJECT('id', 'D', 'text', '혈액이 얼어서')), '근육은 수축하며 힘줄을 통해 뼈를 당겨 관절을 움직입니다.', 'body', 'easy', 'B'),
       ('multiple_choice', '자세가 구부정할 때 짧아지거나 긴장하기 쉬운 근육은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '종아리 뒤쪽'), JSON_OBJECT('id', 'B', 'text', '손가락 근육'), JSON_OBJECT('id', 'C', 'text', '가슴 앞쪽 근육'), JSON_OBJECT('id', 'D', 'text', '귀 주변 근육')), '구부정한 자세가 길어지면 가슴 앞쪽 근육이 짧아지고 등 위쪽이 늘어지기 쉽습니다.', 'body', 'medium', 'C'),
       ('multiple_choice', '스텝업 운동의 올바른 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '뒷발로 밀어 올리기'), JSON_OBJECT('id', 'B', 'text', '발끝만 올려 점프하기'), JSON_OBJECT('id', 'C', 'text', '무릎을 안쪽으로 꺾기'), JSON_OBJECT('id', 'D', 'text', '발 전체를 박스에 올리고 앞다리 힘으로 일어서기')), '앞다리의 힘으로 올라서면 대퇴사두근과 엉덩이가 일하고 균형을 기르는 데 좋습니다.', 'form', 'medium', 'D'),
       ('multiple_choice', '운동 일지를 쓰면 좋은 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 효과가 사라진다'), JSON_OBJECT('id', 'B', 'text', '진행 상황을 확인하고 강도를 조절하기 쉽다'), JSON_OBJECT('id', 'C', 'text', '기록은 필요 없다'), JSON_OBJECT('id', 'D', 'text', '운동을 못 하게 된다')), '횟수와 무게, 느낌을 기록하면 점진적 과부하와 컨디션 관리에 도움이 됩니다.', 'intensity', 'medium', 'B'),
       ('multiple_choice', '시티드 로우에서 허리를 과도하게 뒤로 젖히며 당기면 어떻게 될까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '등 자극이 두 배가 된다'), JSON_OBJECT('id', 'B', 'text', '등 대신 허리 반동이 개입되어 부담이 커진다'), JSON_OBJECT('id', 'C', 'text', '호흡이 안정된다'), JSON_OBJECT('id', 'D', 'text', '관절이 강해진다')), '반동을 쓰면 목표 근육의 자극이 줄고 허리에 불필요한 부담이 생깁니다.', 'form', 'medium', 'B'),
       ('multiple_choice', '음료를 고를 때 가장 알맞은 기본 선택은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '물이나 무가당 차'), JSON_OBJECT('id', 'B', 'text', '탄산음료'), JSON_OBJECT('id', 'C', 'text', '에너지 음료'), JSON_OBJECT('id', 'D', 'text', '가당 커피')), '물과 무가당 차는 열량과 당이 거의 없어 기본 음료로 알맞습니다.', 'practice', 'easy', 'A'),
       ('multiple_choice', '식사를 계획하는 습관(밀프렙)의 장점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '충동적인 선택을 줄이고 균형 있게 먹기 쉽다'), JSON_OBJECT('id', 'B', 'text', '식재료를 낭비하게 된다'), JSON_OBJECT('id', 'C', 'text', '식사가 항상 불규칙해진다'), JSON_OBJECT('id', 'D', 'text', '식사 시간이 늘어난다')), '미리 계획하면 건강한 재료를 준비하고 외식·배달 의존을 줄이는 데 도움이 됩니다.', 'habit', 'medium', 'A'),
       ('multiple_choice', '근육량이 많은 사람의 기초대사량이 상대적으로 높은 경향이 있는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 열량을 전혀 쓰지 않기 때문'), JSON_OBJECT('id', 'B', 'text', '근육은 수분이 없기 때문'), JSON_OBJECT('id', 'C', 'text', '근육이 안정 시에도 에너지를 쓰기 때문'), JSON_OBJECT('id', 'D', 'text', '근육은 호흡을 멈추게 하기 때문')), '근육 조직은 안정 시에도 에너지를 소비하므로 근육량이 많을수록 기초대사량이 높은 경향이 있습니다.', 'basics', 'medium', 'C'),
       ('multiple_choice', '근육의 이름 중 "이두근"이라는 이름이 붙은 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '두 개의 뼈 위에 있어서'), JSON_OBJECT('id', 'B', 'text', '이 근육이 두 번 수축해서'), JSON_OBJECT('id', 'C', 'text', '두 사람이 쓰는 근육이어서'), JSON_OBJECT('id', 'D', 'text', '근육의 머리 부분이 두 갈래이기 때문')), '이두근은 윗부분이 장두와 단두 두 갈래로 나뉘어 이두라는 이름이 붙었습니다.', 'body', 'hard', 'D'),
       ('multiple_choice', '"나트륨은 줄이고 칼륨은 챙기는" 식단의 실천 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '채소와 과일을 늘리고 가공식품·국물을 줄이기'), JSON_OBJECT('id', 'B', 'text', '가공식품을 늘리기'), JSON_OBJECT('id', 'C', 'text', '채소를 줄이기'), JSON_OBJECT('id', 'D', 'text', '소금을 더 넣기')), '채소·과일은 칼륨이 풍부하고 가공식품과 국물은 나트륨이 많습니다.', 'balance', 'medium', 'A'),
       ('multiple_choice', '식사 중 "음식에 대한 죄책감"이 식습관에 미치는 영향으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식습관이 항상 좋아진다'), JSON_OBJECT('id', 'B', 'text', '식사량이 줄어든다'), JSON_OBJECT('id', 'C', 'text', '폭식과 절식의 악순환을 부를 수 있다'), JSON_OBJECT('id', 'D', 'text', '영향이 없다')), '음식에 대한 과도한 죄책감은 폭식과 절식을 반복하게 해 건강한 식습관을 해칠 수 있습니다.', 'habit', 'hard', 'C'),
       ('multiple_choice', '비타민 A가 풍부한 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '설탕'), JSON_OBJECT('id', 'B', 'text', '식용유'), JSON_OBJECT('id', 'C', 'text', '당근과 간'), JSON_OBJECT('id', 'D', 'text', '사이다')), '당근과 호박, 달걀노른자, 간 등에 비타민 A 또는 그 전구체가 들어 있습니다.', 'nutrients', 'easy', 'C'),
       ('multiple_choice', '냉장고를 효율적으로 사용하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '가득 채워 두기'), JSON_OBJECT('id', 'B', 'text', '날짜를 확인하지 않기'), JSON_OBJECT('id', 'C', 'text', '문을 자주 오래 열기'), JSON_OBJECT('id', 'D', 'text', '70% 정도만 채우고 날짜순으로 정리하기')), '냉기가 잘 순환되도록 너무 꽉 채우지 않고 유통기한을 확인하며 정리해야 합니다.', 'hygiene', 'medium', 'D'),
       ('multiple_choice', '"무첨가" 표시가 항상 건강하다는 뜻이 아닌 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무첨가는 열량이 없다는 뜻이어서'), JSON_OBJECT('id', 'B', 'text', '특정 첨가물만 없다는 뜻일 뿐 열량, 당류, 나트륨은 따로 확인해야 해서'), JSON_OBJECT('id', 'C', 'text', '무첨가는 비타민이 많다는 뜻이어서'), JSON_OBJECT('id', 'D', 'text', '무첨가는 먹어도 된다는 뜻이어서')), '일부 성분이 없다는 의미일 뿐 다른 영양 성분은 별도로 확인해야 합니다.', 'label', 'medium', 'B'),
       ('multiple_choice', '운동 후 맥박이 정상으로 돌아오는 속도를 확인하는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체중을 알기 위해서'), JSON_OBJECT('id', 'B', 'text', '심폐 체력과 회복 상태를 가늠하는 지표가 될 수 있어서'), JSON_OBJECT('id', 'C', 'text', '키를 재기 위해서'), JSON_OBJECT('id', 'D', 'text', '운동복 상태를 보기 위해서')), '운동 후 심박수가 빨리 안정될수록 일반적으로 회복 능력이 좋다고 해석합니다.', 'recovery', 'hard', 'B'),
       ('multiple_choice', '하이 니는 어떤 동작일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '제자리에서 무릎을 높이 들며 달리듯 움직이는 동작'), JSON_OBJECT('id', 'B', 'text', '앉아서 무릎을 안는 동작'), JSON_OBJECT('id', 'C', 'text', '누워서 다리를 드는 동작'), JSON_OBJECT('id', 'D', 'text', '벽에 기대는 동작')), '제자리에서 무릎을 번갈아 높이 들며 달리는 맨몸 유산소 운동입니다.', 'form', 'easy', 'A'),
       ('multiple_choice', '준비 없이 갑자기 무거운 물건을 들 때 높아지는 위험은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '허리와 근육 부상'), JSON_OBJECT('id', 'B', 'text', '시력 향상'), JSON_OBJECT('id', 'C', 'text', '수분 증가'), JSON_OBJECT('id', 'D', 'text', '소화 촉진')), '준비 없이 갑자기 큰 힘을 쓰면 근육과 허리에 무리가 가기 쉽습니다.', 'basics', 'easy', 'A'),
       ('multiple_choice', '정리운동에서 저강도 유산소를 몇 분 하는 것과 즉시 멈추는 것의 차이를 가장 정확하게 설명한 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '저강도 유산소는 심박과 혈압의 급격한 변동을 줄이는 데 도움이 된다'), JSON_OBJECT('id', 'B', 'text', '즉시 멈추는 편이 항상 안전하다'), JSON_OBJECT('id', 'C', 'text', '저강도 유산소는 근육을 영구히 지치게 한다'), JSON_OBJECT('id', 'D', 'text', '둘은 생리적으로 완전히 같다')), '운동 직후 서서히 강도를 낮추면 혈류와 심박이 완만히 변해 어지러움 같은 급격한 변화를 줄이는 데 도움이 됩니다.', 'warmup', 'hard', 'A'),
       ('multiple_choice', '식품 포장지에서 영양소 함량을 확인할 수 있는 표시는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '바코드'), JSON_OBJECT('id', 'B', 'text', '제조사 로고'), JSON_OBJECT('id', 'C', 'text', '포장 디자인'), JSON_OBJECT('id', 'D', 'text', '영양성분표')), '영양성분표에는 열량과 나트륨, 탄수화물, 당류, 지방, 단백질 등의 함량이 표시됩니다.', 'label', 'easy', 'D'),
       ('multiple_choice', '온찜질(온열 요법)이 도움이 될 수 있는 상황은 어떤 경우일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '급성 삔 직후 부기가 심할 때'), JSON_OBJECT('id', 'B', 'text', '열이 매우 높을 때'), JSON_OBJECT('id', 'C', 'text', '상처가 열려 있을 때'), JSON_OBJECT('id', 'D', 'text', '만성적으로 뻐근한 근육을 풀 때')), '온열은 혈액순환을 도와 만성적인 근육 긴장을 풀 때 도움이 될 수 있습니다.', 'recovery', 'medium', 'D'),
       ('multiple_choice', '식품을 가열할 때 중심 온도 기준으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '겉만 익으면 충분하다'), JSON_OBJECT('id', 'B', 'text', '미지근하면 충분하다'), JSON_OBJECT('id', 'C', 'text', '식품 종류에 따라 정해진 중심 온도까지 가열하기'), JSON_OBJECT('id', 'D', 'text', '온도는 상관없다')), '고기 등은 속까지 충분한 중심 온도에 도달해야 세균을 줄일 수 있어 온도계로 확인하면 좋습니다.', 'hygiene', 'hard', 'C'),
       ('multiple_choice', '엉덩이 근육 중 가장 바깥쪽에서 둔부의 모양을 만드는 큰 근육은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '대둔근'), JSON_OBJECT('id', 'B', 'text', '소둔근'), JSON_OBJECT('id', 'C', 'text', '이상근'), JSON_OBJECT('id', 'D', 'text', '장요근')), '대둔근은 둔부에서 가장 크고 표면에 있는 근육입니다.', 'body', 'hard', 'A'),
       ('multiple_choice', '생고기와 채소를 함께 손질할 때 알맞은 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '같은 도마를 씻지 않고 계속 쓰기'), JSON_OBJECT('id', 'B', 'text', '도마와 칼을 구분해 사용하거나 사용 후 깨끗이 씻기'), JSON_OBJECT('id', 'C', 'text', '손만 씻고 도마는 그대로 쓰기'), JSON_OBJECT('id', 'D', 'text', '칼을 닦지 않기')), '교차 오염을 막기 위해 생고기와 채소의 도구를 구분하거나 충분히 씻어 써야 합니다.', 'hygiene', 'easy', 'B'),
       ('multiple_choice', '먹고 싶은 음식이 있을 때 조절하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무조건 참기'), JSON_OBJECT('id', 'B', 'text', '적당량을 정해 즐기며 먹기'), JSON_OBJECT('id', 'C', 'text', '한꺼번에 폭식하기'), JSON_OBJECT('id', 'D', 'text', '식사를 거르기')), '완전히 참기보다 적당량을 정해 즐기면 폭식을 예방하는 데 도움이 됩니다.', 'habit', 'easy', 'B'),
       ('multiple_choice', '준비운동의 구성으로 알맞은 순서는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '가벼운 유산소 → 동적 움직임 → 본 운동과 비슷한 동작'), JSON_OBJECT('id', 'B', 'text', '본 운동 → 준비운동 → 휴식'), JSON_OBJECT('id', 'C', 'text', '정적 스트레칭 → 전력 질주'), JSON_OBJECT('id', 'D', 'text', '휴식 → 최대 무게')), '일반적 준비운동은 가벼운 유산소로 체온을 올리고 동적 움직임과 본 운동 동작을 약하게 연습하는 순서입니다.', 'warmup', 'medium', 'A'),
       ('multiple_choice', '운동 초보자가 처음 운동량을 정하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '처음부터 최대로 하기'), JSON_OBJECT('id', 'B', 'text', '매일 한계까지 하기'), JSON_OBJECT('id', 'C', 'text', '가볍게 시작해 조금씩 늘리기'), JSON_OBJECT('id', 'D', 'text', '다른 사람과 똑같이 하기')), '몸이 적응할 시간을 주며 서서히 늘리면 부상 위험을 줄이고 꾸준히 이어가기 쉽습니다.', 'intensity', 'easy', 'C'),
       ('multiple_choice', '자각도(RPE)와 "여유 반복 수(RIR)"의 관계를 설명한 것으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', 'RIR은 쉬는 시간을 뜻한다'), JSON_OBJECT('id', 'B', 'text', 'RIR은 세트를 끝낸 뒤 남은 반복 가능 횟수로 강도를 가늠하는 방법이다'), JSON_OBJECT('id', 'C', 'text', 'RIR은 심박수를 뜻한다'), JSON_OBJECT('id', 'D', 'text', 'RIR은 체중을 뜻한다')), '"2회 더 할 수 있었다"처럼 남은 반복 수로 세트의 힘든 정도를 판단하는 방법입니다.', 'intensity', 'hard', 'B'),
       ('multiple_choice', '식단에서 "빵과 잼" 같은 정제 탄수화물 위주 아침 식사를 보완하는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '달걀이나 요거트, 과일 등을 곁들여 단백질과 식이섬유를 더하기'), JSON_OBJECT('id', 'B', 'text', '잼을 더 바르기'), JSON_OBJECT('id', 'C', 'text', '음료로만 먹기'), JSON_OBJECT('id', 'D', 'text', '아침 식사를 줄이기')), '단백질과 식이섬유를 더하면 혈당 반응이 완만해지고 포만감이 오래갈 수 있습니다.', 'balance', 'hard', 'A'),
       ('multiple_choice', '운동 후 회복에서 탄수화물 섭취가 중요한 경우는 언제일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동을 하지 않았을 때만'), JSON_OBJECT('id', 'B', 'text', '항상 아무 때나 동일'), JSON_OBJECT('id', 'C', 'text', '다음 운동까지 시간이 짧거나 장시간·고강도 운동을 했을 때'), JSON_OBJECT('id', 'D', 'text', '무관하다')), '근글리코겐 보충이 필요한 상황에서는 탄수화물 섭취가 회복에 중요해집니다.', 'recovery', 'hard', 'C'),
       ('multiple_choice', '건강 목적의 신체활동 지침에서 노인에게 추가로 강조하는 운동은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무거운 점프 운동만'), JSON_OBJECT('id', 'B', 'text', '균형 운동'), JSON_OBJECT('id', 'C', 'text', '운동 금지'), JSON_OBJECT('id', 'D', 'text', '앉아서 쉬기')), '노인은 낙상 예방을 위해 균형 능력을 기르는 운동을 함께 하도록 권장됩니다.', 'basics', 'hard', 'B'),
       ('multiple_choice', '당알코올(소르비톨, 자일리톨 등)에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '설탕보다 열량이 낮은 경우가 많으나 많이 먹으면 소화 불편이 생길 수 있다'), JSON_OBJECT('id', 'B', 'text', '열량이 가장 높은 영양소다'), JSON_OBJECT('id', 'C', 'text', '단백질의 일종이다'), JSON_OBJECT('id', 'D', 'text', '비타민의 일종이다')), '당알코올은 열량이 낮은 편이지만 과다 섭취 시 복부 불편이나 설사를 일으킬 수 있습니다.', 'nutrients', 'hard', 'A'),
       ('multiple_choice', '플랭크처럼 관절 움직임 없이 힘을 유지하는 수축 형태를 무엇이라 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '단축성 수축'), JSON_OBJECT('id', 'B', 'text', '신장성 수축'), JSON_OBJECT('id', 'C', 'text', '탄성 수축'), JSON_OBJECT('id', 'D', 'text', '등척성 수축')), '등척성 수축은 근육 길이와 관절 각도가 거의 변하지 않은 채 힘을 유지하는 형태입니다.', 'basics', 'hard', 'D'),
       ('multiple_choice', '허리 부위 준비운동으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '골반 돌리기와 가벼운 몸통 회전'), JSON_OBJECT('id', 'B', 'text', '허리를 세게 비틀기'), JSON_OBJECT('id', 'C', 'text', '무거운 물건 들기'), JSON_OBJECT('id', 'D', 'text', '허리를 과도하게 꺾기')), '허리는 무리하지 않는 범위에서 부드럽게 움직이며 풀어 주는 것이 안전합니다.', 'warmup', 'medium', 'A'),
       ('multiple_choice', '사이드 런지의 특징으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '앞으로만 뛰는 운동'), JSON_OBJECT('id', 'B', 'text', '옆으로 한 발을 내딛고 엉덩이를 뒤로 보내며 앉는 운동'), JSON_OBJECT('id', 'C', 'text', '누워서 하는 운동'), JSON_OBJECT('id', 'D', 'text', '팔만 쓰는 운동')), '옆으로 내딛는 움직임으로 허벅지 안쪽과 엉덩이를 포함해 좌우 방향의 하체 근력을 키웁니다.', 'form', 'medium', 'B'),
       ('multiple_choice', '식품 위생 관리의 HACCP 개념이 가정에서 적용되는 예로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '맛을 바꾸는 습관'), JSON_OBJECT('id', 'B', 'text', '온도와 시간 등 핵심 관리 지점을 정해 확인하는 습관'), JSON_OBJECT('id', 'C', 'text', '식품을 방치하는 습관'), JSON_OBJECT('id', 'D', 'text', '식재료를 섞는 습관')), '냉장 온도 확인, 중심 온도 가열 같은 핵심 지점을 점검하면 가정에서도 위해 요소를 줄일 수 있습니다.', 'hygiene', 'hard', 'B'),
       ('multiple_choice', '운동 후 땀을 많이 흘렸다면 보충해야 할 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 시간'), JSON_OBJECT('id', 'B', 'text', '수면 시간 단축'), JSON_OBJECT('id', 'C', 'text', '수분'), JSON_OBJECT('id', 'D', 'text', '무거운 짐')), '땀과 함께 수분이 빠졌으므로 물을 마셔 보충하는 것이 좋습니다.', 'basics', 'easy', 'C'),
       ('multiple_choice', '엎드려 팔다리 들기(슈퍼맨) 운동은 주로 어느 부위를 쓸까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '이마'), JSON_OBJECT('id', 'B', 'text', '등과 엉덩이'), JSON_OBJECT('id', 'C', 'text', '손톱'), JSON_OBJECT('id', 'D', 'text', '발톱')), '엎드린 자세에서 팔다리를 드는 동작은 척추 기립근과 둔근을 쓰는 운동입니다.', 'form', 'medium', 'B'),
       ('multiple_choice', '코어 운동에서 복부를 "집어넣는" 방식과 "단단히 하는" 방식 중 일반적으로 더 권장되는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '복부를 단단히 하는 브레이싱'), JSON_OBJECT('id', 'B', 'text', '배를 최대로 집어넣는 것만'), JSON_OBJECT('id', 'C', 'text', '숨을 완전히 참는 것'), JSON_OBJECT('id', 'D', 'text', '복부를 전혀 쓰지 않는 것')), '복부 전체를 단단히 하는 브레이싱이 몸통 안정에 더 널리 권장됩니다.', 'form', 'hard', 'A'),
       ('multiple_choice', '일일 권장 열량을 계산할 때 활동 대사량을 고려하는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '활동은 열량과 무관해서'), JSON_OBJECT('id', 'B', 'text', '활동 정도에 따라 소비하는 에너지가 달라서'), JSON_OBJECT('id', 'C', 'text', '열량을 줄이기 위해서'), JSON_OBJECT('id', 'D', 'text', '체중을 늘리기 위해서')), '같은 체격이라도 활동량이 많으면 에너지 소비가 커져 필요 열량이 늘어납니다.', 'balance', 'hard', 'B'),
       ('multiple_choice', '채소 반찬으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '사탕'), JSON_OBJECT('id', 'B', 'text', '탄산음료'), JSON_OBJECT('id', 'C', 'text', '식용유'), JSON_OBJECT('id', 'D', 'text', '시금치나물, 브로콜리 무침')), '시금치와 브로콜리는 비타민과 무기질이 풍부한 채소입니다.', 'balance', 'easy', 'D'),
       ('multiple_choice', '식사량 조절에 도움이 되는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '큰 그릇에 가득 담기'), JSON_OBJECT('id', 'B', 'text', '포장째 먹기'), JSON_OBJECT('id', 'C', 'text', '1회 제공량을 덜어 먹고 천천히 먹기'), JSON_OBJECT('id', 'D', 'text', '빨리 먹기')), '덜어 먹고 천천히 먹으면 먹는 양을 알아차리고 과식을 줄일 수 있습니다.', 'practice', 'medium', 'C'),
       ('multiple_choice', '폼롤러를 운동에 활용할 때 흔한 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '뼈 위에서 세게 굴리기'), JSON_OBJECT('id', 'B', 'text', '빠르게 반동으로 굴리기'), JSON_OBJECT('id', 'C', 'text', '근육 위에서 천천히 굴리며 뻐근한 부위를 풀어 주기'), JSON_OBJECT('id', 'D', 'text', '숨을 참고 오래 누르기')), '근육이 있는 부위에서 천천히 굴리며 뻐근함을 줄이되 뼈나 관절 위는 피하는 것이 좋습니다.', 'form', 'medium', 'C'),
       ('multiple_choice', '다이어트 중 식단에서 지켜야 할 원칙으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 가지 음식만 먹기'), JSON_OBJECT('id', 'B', 'text', '식사를 완전히 끊기'), JSON_OBJECT('id', 'C', 'text', '필요한 영양소를 유지하며 열량을 적절히 조절하기'), JSON_OBJECT('id', 'D', 'text', '물만 마시기')), '극단적인 제한 대신 균형을 유지하면서 열량을 조절하는 것이 안전합니다.', 'balance', 'medium', 'C'),
       ('multiple_choice', '대퇴사두근이 위치한 곳은 어디일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '종아리 뒤쪽'), JSON_OBJECT('id', 'B', 'text', '허벅지 앞쪽'), JSON_OBJECT('id', 'C', 'text', '어깨 위'), JSON_OBJECT('id', 'D', 'text', '손바닥')), '대퇴사두근은 허벅지 앞쪽의 큰 근육군으로 무릎을 펴는 힘을 냅니다.', 'warmup', 'medium', 'B'),
       ('multiple_choice', '과일과 채소를 먹기 전에 해야 할 일은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '씻지 않고 먹기'), JSON_OBJECT('id', 'B', 'text', '비누로 씻기'), JSON_OBJECT('id', 'C', 'text', '흐르는 물에 깨끗이 씻기'), JSON_OBJECT('id', 'D', 'text', '뜨거운 물에 담그기')), '흐르는 물에 씻으면 표면의 흙과 오염 물질을 줄일 수 있습니다.', 'hygiene', 'easy', 'C'),
       ('multiple_choice', '운동 강도란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동이 얼마나 힘든지의 정도'), JSON_OBJECT('id', 'B', 'text', '운동하는 장소의 크기'), JSON_OBJECT('id', 'C', 'text', '운동 시간의 길이만'), JSON_OBJECT('id', 'D', 'text', '운동 복장의 종류')), '강도는 운동이 몸에 주는 부담의 크기이며 속도, 무게, 심박수 등으로 나타냅니다.', 'intensity', 'easy', 'A'),
       ('multiple_choice', '운동 후 땀에 젖은 옷을 오래 입고 있으면 어떨 수 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체온이 떨어져 불편하거나 감기에 걸리기 쉬울 수 있다'), JSON_OBJECT('id', 'B', 'text', '체력이 좋아진다'), JSON_OBJECT('id', 'C', 'text', '피부가 건강해진다'), JSON_OBJECT('id', 'D', 'text', '아무 영향이 없다')), '땀에 젖은 채 오래 있으면 몸이 식어 불편하고 컨디션이 떨어질 수 있습니다.', 'recovery', 'easy', 'A'),
       ('multiple_choice', '운동 계획에서 "시간(Time)" 요소를 조절하는 예로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 횟수를 줄이기'), JSON_OBJECT('id', 'B', 'text', '운동 종류를 바꾸기'), JSON_OBJECT('id', 'C', 'text', '1회 운동 시간을 20분에서 25분으로 조금 늘리기'), JSON_OBJECT('id', 'D', 'text', '운동 장소를 옮기기')), '운동 시간은 1회에 하는 운동의 길이를 뜻하며 조금씩 늘리면 체력에 맞게 부담을 높일 수 있습니다.', 'intensity', 'medium', 'C'),
       ('multiple_choice', '식사 후 졸음이 쏟아질 때 도움이 되는 식사 습관은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '과식을 피하고 정제 탄수화물을 줄이며 채소와 단백질을 곁들이기'), JSON_OBJECT('id', 'B', 'text', '과식하기'), JSON_OBJECT('id', 'C', 'text', '당 음료 마시기'), JSON_OBJECT('id', 'D', 'text', '식사를 매우 빨리 하기')), '과식과 정제 탄수화물 위주 식사는 식후 졸음이나 피로감과 관련될 수 있어 균형 있게 먹는 것이 좋습니다.', 'balance', 'medium', 'A'),
       ('multiple_choice', '물 섭취가 체온 조절에 필요한 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '물이 열을 만들기 때문'), JSON_OBJECT('id', 'B', 'text', '땀이 필요 없어서'), JSON_OBJECT('id', 'C', 'text', '땀이 증발하며 열을 식히는 데 수분이 쓰이기 때문'), JSON_OBJECT('id', 'D', 'text', '물이 단백질이라서')), '땀이 증발하면서 열을 빼앗아 체온을 낮추는데 이를 위해 수분이 필요합니다.', 'water', 'hard', 'C'),
       ('multiple_choice', '식단과 운동을 함께 관리할 때 유의할 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동량에 맞춰 에너지와 단백질을 충분히 섭취하기'), JSON_OBJECT('id', 'B', 'text', '운동하면 식사를 줄이기'), JSON_OBJECT('id', 'C', 'text', '운동 후 식사를 거르기'), JSON_OBJECT('id', 'D', 'text', '단백질을 끊기')), '운동량에 맞는 영양 섭취가 회복과 수행에 필요합니다.', 'practice', 'hard', 'A'),
       ('multiple_choice', '운동 강도를 설명할 때 METs(메츠)란 무엇을 나타낼까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 시간'), JSON_OBJECT('id', 'B', 'text', '운동 장소'), JSON_OBJECT('id', 'C', 'text', '체중'), JSON_OBJECT('id', 'D', 'text', '안정 시 대비 운동 중 에너지 소비량의 비율')), 'MET는 앉아서 쉴 때를 1로 놓고 활동이 그 몇 배의 에너지를 쓰는지 나타내는 단위입니다.', 'intensity', 'hard', 'D'),
       ('multiple_choice', '심박수 회복이란 무엇을 말할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 전 심박수의 최대값'), JSON_OBJECT('id', 'B', 'text', '운동 중 호흡 횟수'), JSON_OBJECT('id', 'C', 'text', '혈압을 재는 방법'), JSON_OBJECT('id', 'D', 'text', '운동 후 심박수가 안정 수준으로 돌아오는 정도')), '운동을 멈춘 뒤 심박수가 얼마나 빨리 내려오는지는 심폐 체력의 한 지표로 쓰입니다.', 'basics', 'medium', 'D'),
       ('multiple_choice', '운동 후 근육이 뻐근할 때 같은 근육을 곧바로 강하게 반복해서 눌러 풀어 주면 어떨 수 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '항상 회복이 두 배 빨라진다'), JSON_OBJECT('id', 'B', 'text', '피로한 근육에 부담이 되어 불편이 커질 수 있다'), JSON_OBJECT('id', 'C', 'text', '근육이 즉시 커진다'), JSON_OBJECT('id', 'D', 'text', '아무 영향이 없다')), '피로한 근육을 지나치게 세게 자극하면 오히려 통증과 부담이 커질 수 있어 부드럽게 푸는 것이 좋습니다.', 'recovery', 'medium', 'B'),
       ('multiple_choice', '운동 후 근육 합성에 관여하는 요인으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동복 색'), JSON_OBJECT('id', 'B', 'text', '단백질 섭취와 근력 운동 자극'), JSON_OBJECT('id', 'C', 'text', '운동 시간대 이름'), JSON_OBJECT('id', 'D', 'text', '신발 무게')), '근력 운동 자극과 충분한 단백질 섭취가 근단백질 합성을 촉진합니다.', 'recovery', 'hard', 'B'),
       ('multiple_choice', '운동 중 호흡 연동에서 발살바 호흡이 위험할 수 있는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체온이 낮아져서'), JSON_OBJECT('id', 'B', 'text', '산소가 늘어나서'), JSON_OBJECT('id', 'C', 'text', '근육이 사라져서'), JSON_OBJECT('id', 'D', 'text', '숨을 참아 일시적으로 혈압이 크게 오를 수 있어서')), '숨을 참고 힘을 쓰면 흉강 압력이 높아져 혈압이 일시적으로 크게 오를 수 있어 건강 상태에 따라 주의가 필요합니다.', 'form', 'hard', 'D'),
       ('multiple_choice', '운동 중 심박수가 같은 강도에서 평소보다 지속적으로 높게 나타날 때 가능한 해석은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체력이 갑자기 좋아졌다'), JSON_OBJECT('id', 'B', 'text', '운동 효과가 두 배가 되었다'), JSON_OBJECT('id', 'C', 'text', '아무 의미 없다'), JSON_OBJECT('id', 'D', 'text', '피로, 수면 부족, 탈수 등으로 회복이 덜 되었을 수 있다')), '같은 강도에서 심박수가 높다면 피로나 수면, 수분 상태 등 회복 부족을 의심해 볼 수 있습니다.', 'intensity', 'hard', 'D'),
       ('multiple_choice', '식사 후 가볍게 걷는 습관의 장점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '소화를 막는다'), JSON_OBJECT('id', 'B', 'text', '체력이 떨어진다'), JSON_OBJECT('id', 'C', 'text', '식사량이 늘어난다'), JSON_OBJECT('id', 'D', 'text', '소화를 돕고 활동량을 늘리는 데 도움이 된다')), '식후 가벼운 걷기는 소화와 혈당 관리에 도움이 될 수 있습니다.', 'habit', 'easy', 'D'),
       ('multiple_choice', '운동 부하가 갑자기 크게 늘어나는 것이 위험한 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 사라져서'), JSON_OBJECT('id', 'B', 'text', '조직이 적응할 시간이 부족해 부상 위험이 커질 수 있어서'), JSON_OBJECT('id', 'C', 'text', '체온이 낮아져서'), JSON_OBJECT('id', 'D', 'text', '호흡이 필요 없어져서')), '근육·힘줄·뼈가 새로운 부하에 적응하려면 시간이 필요하므로 점진적 증가가 안전합니다.', 'intensity', 'hard', 'B'),
       ('multiple_choice', '운동 후 근육 회복 속도에 영향을 주는 요인으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동복 색'), JSON_OBJECT('id', 'B', 'text', '운동 장소의 이름'), JSON_OBJECT('id', 'C', 'text', '운동화 브랜드'), JSON_OBJECT('id', 'D', 'text', '수면, 영양, 스트레스, 운동 강도')), '회복은 수면·영양·스트레스·운동 강도 등 여러 요인에 따라 달라집니다.', 'recovery', 'hard', 'D'),
       ('multiple_choice', '음식물을 보관할 때 밀폐 용기를 쓰는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '맛을 없애기 위해서'), JSON_OBJECT('id', 'B', 'text', '무게를 늘리기 위해서'), JSON_OBJECT('id', 'C', 'text', '오염과 냄새, 건조를 줄이기 위해서'), JSON_OBJECT('id', 'D', 'text', '색을 바꾸기 위해서')), '밀폐 용기는 다른 식품과의 교차 오염과 수분 손실을 줄이는 데 도움이 됩니다.', 'hygiene', 'easy', 'C'),
       ('multiple_choice', '성인에게 권장되는 하루 물 섭취량에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 사람이 정확히 2L이다'), JSON_OBJECT('id', 'B', 'text', '모든 사람이 500mL이다'), JSON_OBJECT('id', 'C', 'text', '식사에서 얻는 수분을 포함해 개인의 체격·활동·환경에 따라 달라진다'), JSON_OBJECT('id', 'D', 'text', '물은 마시지 않아도 된다')), '수분 필요량은 체격, 활동량, 기온에 따라 달라 하나의 정해진 값으로 단정할 수 없습니다.', 'water', 'medium', 'C'),
       ('multiple_choice', '수면 부족이 식습관에 미치는 영향으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식욕이 항상 줄어든다'), JSON_OBJECT('id', 'B', 'text', '식습관과 무관하다'), JSON_OBJECT('id', 'C', 'text', '체중이 항상 감소한다'), JSON_OBJECT('id', 'D', 'text', '식욕 호르몬이 변해 단 음식이나 고열량 음식을 더 찾게 될 수 있다')), '수면이 부족하면 식욕 관련 호르몬이 변해 열량 섭취가 늘 수 있다고 알려져 있습니다.', 'habit', 'hard', 'D'),
       ('multiple_choice', '식사 후 달콤한 디저트를 먹고 싶을 때 대안으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '큰 케이크 한 판'), JSON_OBJECT('id', 'B', 'text', '탄산음료 2L'), JSON_OBJECT('id', 'C', 'text', '사탕 한 봉지'), JSON_OBJECT('id', 'D', 'text', '과일이나 요거트 같은 가벼운 선택')), '과일이나 무가당 요거트는 단맛을 채우면서 영양소도 함께 얻을 수 있습니다.', 'habit', 'medium', 'D'),
