       ('multiple_choice', '운동 후 회복에 도움이 되는 일반적인 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '밤샘과 탈수'), JSON_OBJECT('id', 'B', 'text', '운동 직후 바로 최대 강도 운동'), JSON_OBJECT('id', 'C', 'text', '충분한 수면, 수분과 영양 섭취, 가벼운 활동'), JSON_OBJECT('id', 'D', 'text', '식사 거르기')), '수면과 영양, 수분은 회복의 기본이며 가벼운 걷기도 도움이 됩니다.', 'intensity', 'medium', 'C'),
       ('multiple_choice', '데드리프트에서 바를 몸에서 멀리 두면 어떤 점이 달라질까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '허리에 걸리는 부담이 커진다'), JSON_OBJECT('id', 'B', 'text', '허리 부담이 사라진다'), JSON_OBJECT('id', 'C', 'text', '무게가 줄어든다'), JSON_OBJECT('id', 'D', 'text', '호흡이 필요 없어진다')), '바가 몸에서 멀수록 지렛대 길이가 늘어 허리 부담이 커지므로 바를 몸에 가깝게 유지합니다.', 'form', 'hard', 'A'),
       ('multiple_choice', '운동 후 스트레칭 중에 호흡은 어떻게 하는 것이 좋을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '숨을 꾹 참기'), JSON_OBJECT('id', 'B', 'text', '아주 빠르게 숨 쉬기'), JSON_OBJECT('id', 'C', 'text', '숨을 멈추고 반동 주기'), JSON_OBJECT('id', 'D', 'text', '자세를 유지하며 편안하게 숨 쉬기')), '숨을 쉬면서 천천히 늘리면 근육이 이완되어 더 편안하게 스트레칭할 수 있습니다.', 'recovery', 'easy', 'D'),
       ('multiple_choice', '배달 음식을 건강하게 먹는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '튀김을 추가하기'), JSON_OBJECT('id', 'B', 'text', '채소 반찬을 따로 추가하고 소스와 국물은 적게 먹기'), JSON_OBJECT('id', 'C', 'text', '탄산음료를 추가하기'), JSON_OBJECT('id', 'D', 'text', '소스를 더 넣기')), '배달 음식은 채소를 보충하고 나트륨을 줄이는 방식으로 개선할 수 있습니다.', 'practice', 'medium', 'B'),
       ('multiple_choice', '식단에서 "영양소 보충제"보다 "식품 섭취"를 우선하는 일반적 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '보충제는 비싸서만'), JSON_OBJECT('id', 'B', 'text', '식품은 여러 영양소와 식이섬유, 식물영양소를 함께 제공하기 때문'), JSON_OBJECT('id', 'C', 'text', '식품은 영양이 없어서'), JSON_OBJECT('id', 'D', 'text', '보충제는 항상 해로워서')), '식품은 단일 영양소 외에도 다양한 성분을 함께 제공해 균형 잡힌 섭취에 유리합니다.', 'balance', 'hard', 'B'),
       ('multiple_choice', '스트레스와 회복의 관계에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '만성 스트레스는 회복과 수면에 부정적 영향을 줄 수 있다'), JSON_OBJECT('id', 'B', 'text', '스트레스는 회복에 항상 도움이 된다'), JSON_OBJECT('id', 'C', 'text', '스트레스와 회복은 무관하다'), JSON_OBJECT('id', 'D', 'text', '스트레스는 근육을 키운다')), '지속적인 스트레스는 수면과 회복을 방해할 수 있어 운동량 조절에도 반영해야 합니다.', 'recovery', 'hard', 'A'),
       ('multiple_choice', '운동 중 물을 마시는 간격으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '1시간마다 한 번에 많이'), JSON_OBJECT('id', 'B', 'text', '운동 후에만 마시기'), JSON_OBJECT('id', 'C', 'text', '마시지 않기'), JSON_OBJECT('id', 'D', 'text', '15~20분마다 조금씩 마시기')), '운동 중에는 짧은 간격으로 조금씩 마시는 방법이 흔히 권장됩니다.', 'water', 'medium', 'D'),
       ('multiple_choice', '중둔근의 역할로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '골반을 안정시키고 다리를 옆으로 벌린다'), JSON_OBJECT('id', 'B', 'text', '팔을 올린다'), JSON_OBJECT('id', 'C', 'text', '손목을 굽힌다'), JSON_OBJECT('id', 'D', 'text', '턱을 당긴다')), '중둔근은 엉덩이 옆쪽에서 한 발로 설 때 골반이 무너지지 않도록 안정시킵니다.', 'body', 'medium', 'A'),
