       ('multiple_choice', '운동 후 휴식 시간에 스마트폰 화면을 오래 보는 것이 수면에 미치는 영향으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '밝은 빛이 수면 호르몬 분비를 방해할 수 있다'), JSON_OBJECT('id', 'B', 'text', '수면이 항상 좋아진다'), JSON_OBJECT('id', 'C', 'text', '운동 효과가 두 배가 된다'), JSON_OBJECT('id', 'D', 'text', '체온이 낮아진다')), '취침 전 강한 빛은 멜라토닌 분비에 영향을 주어 잠들기 어렵게 할 수 있습니다.', 'recovery', 'hard', 'A'),
       ('multiple_choice', '다음 중 단백질이 풍부한 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '달걀'), JSON_OBJECT('id', 'B', 'text', '사탕'), JSON_OBJECT('id', 'C', 'text', '식용유'), JSON_OBJECT('id', 'D', 'text', '탄산음료')), '달걀은 양질의 단백질을 함유한 대표 식품입니다.', 'nutrients', 'easy', 'A'),
       ('multiple_choice', '견갑골 안정화 운동이 필요한 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손톱이 자라도록'), JSON_OBJECT('id', 'B', 'text', '어깨 관절이 안정적으로 움직이도록 돕기 때문'), JSON_OBJECT('id', 'C', 'text', '키가 커지도록'), JSON_OBJECT('id', 'D', 'text', '시력이 좋아지도록')), '견갑골이 안정되면 어깨의 움직임이 부드럽고 부담이 줄어듭니다.', 'body', 'medium', 'B'),
       ('multiple_choice', '운동 중 "말은 할 수 있지만 노래는 힘든" 정도의 강도는 어떤 느낌에 가까울까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '아주 가벼운 강도'), JSON_OBJECT('id', 'B', 'text', '최대 강도'), JSON_OBJECT('id', 'C', 'text', '운동이 아닌 상태'), JSON_OBJECT('id', 'D', 'text', '중간 정도의 강도')), '대화는 가능하지만 노래는 어렵다면 일반적으로 중강도 운동으로 봅니다.', 'intensity', 'easy', 'D'),
       ('multiple_choice', '"식사 일기"에 포함하면 좋은 항목으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '시간, 음식, 양, 배고픔 정도, 기분'), JSON_OBJECT('id', 'B', 'text', '날씨만'), JSON_OBJECT('id', 'C', 'text', '옷 색깔'), JSON_OBJECT('id', 'D', 'text', '신발 종류')), '시간과 양, 배고픔, 기분을 함께 기록하면 식사와 감정의 관계를 파악하기 좋습니다.', 'habit', 'hard', 'A'),
       ('multiple_choice', '식사에서 단백질을 한 끼에 몰아 먹는 것과 나누어 먹는 것에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 끼에 몰아 먹는 것이 항상 더 좋다'), JSON_OBJECT('id', 'B', 'text', '나누어 먹는 것은 해롭다'), JSON_OBJECT('id', 'C', 'text', '하루 총량이 더 중요하며 나누어 먹으면 섭취 균형에 도움이 될 수 있다'), JSON_OBJECT('id', 'D', 'text', '단백질은 섭취와 무관하다')), '하루 총 단백질 섭취량이 중요하며 여러 끼에 나누면 균형을 맞추기 쉬울 수 있습니다.', 'nutrients', 'medium', 'C'),
       ('multiple_choice', '스쿼트로 주로 단련되는 부위는 어디일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손목'), JSON_OBJECT('id', 'B', 'text', '엉덩이와 허벅지'), JSON_OBJECT('id', 'C', 'text', '이마'), JSON_OBJECT('id', 'D', 'text', '귓불')), '스쿼트는 엉덩이와 허벅지 근육을 중심으로 하체를 단련하는 대표 운동입니다.', 'body', 'easy', 'B'),
       ('multiple_choice', '식사 후 "만족감"을 높이는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '빨리 먹기'), JSON_OBJECT('id', 'B', 'text', '천천히 먹으며 맛과 식감에 집중하기'), JSON_OBJECT('id', 'C', 'text', '다른 일 하며 먹기'), JSON_OBJECT('id', 'D', 'text', '식사량만 늘리기')), '맛과 식감에 집중하면 같은 양으로도 만족감이 높아질 수 있습니다.', 'habit', 'medium', 'B'),
       ('multiple_choice', '홈 트레이닝 중 소음과 층간 영향을 줄이면서 안전한 운동으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '충격이 큰 점프를 계속하기'), JSON_OBJECT('id', 'B', 'text', '매트를 깔고 충격이 적은 동작 선택'), JSON_OBJECT('id', 'C', 'text', '맨바닥에서 미끄러운 양말로 하기'), JSON_OBJECT('id', 'D', 'text', '불을 끄고 하기')), '매트와 저충격 동작은 관절 부담과 소음을 함께 줄입니다.', 'safety', 'medium', 'B'),
       ('multiple_choice', '운동 중 부상 후 복귀할 때 알맞은 방식은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '바로 이전 최대 강도로 복귀'), JSON_OBJECT('id', 'B', 'text', '통증 없는 범위에서 단계적으로 강도를 올리기'), JSON_OBJECT('id', 'C', 'text', '통증이 있어도 계속하기'), JSON_OBJECT('id', 'D', 'text', '운동을 영구 중단')), '충분히 회복된 후 낮은 강도에서 단계적으로 복귀하면 재부상 위험을 줄입니다.', 'safety', 'hard', 'B'),
       ('multiple_choice', '먹는 속도를 늦추는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '더 큰 숟가락으로 먹기'), JSON_OBJECT('id', 'B', 'text', '음식을 한꺼번에 입에 넣기'), JSON_OBJECT('id', 'C', 'text', '물 없이 삼키기'), JSON_OBJECT('id', 'D', 'text', '한 입 먹고 수저를 내려놓기')), '한 입씩 내려놓고 씹으면 식사 속도를 늦추는 데 도움이 됩니다.', 'habit', 'easy', 'D'),
       ('multiple_choice', '유연성이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무거운 것을 드는 힘'), JSON_OBJECT('id', 'B', 'text', '관절이 움직일 수 있는 범위의 정도'), JSON_OBJECT('id', 'C', 'text', '오래 달리는 능력'), JSON_OBJECT('id', 'D', 'text', '키의 크기')), '유연성은 관절과 근육이 얼마나 넓은 범위로 움직일 수 있는지를 말합니다.', 'body', 'easy', 'B'),
       ('multiple_choice', '운동은 하루의 어느 정도 시간으로 시작해도 좋을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '반드시 3시간'), JSON_OBJECT('id', 'B', 'text', '반드시 5시간'), JSON_OBJECT('id', 'C', 'text', '하루 종일'), JSON_OBJECT('id', 'D', 'text', '10~20분의 짧은 시간')), '짧게 시작해도 괜찮습니다. 처음에는 부담 없는 시간으로 시작해 습관이 되면 늘려 갑니다.', 'basics', 'easy', 'D'),
       ('multiple_choice', '탈수 상태에서 운동 능력이 떨어지는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 커져서'), JSON_OBJECT('id', 'B', 'text', '체중이 늘어서'), JSON_OBJECT('id', 'C', 'text', '혈액량과 체온 조절 능력이 떨어지기 때문'), JSON_OBJECT('id', 'D', 'text', '호흡이 필요 없어서')), '탈수는 심혈관 부담과 체온 상승을 높여 운동 수행을 떨어뜨릴 수 있습니다.', 'water', 'hard', 'C'),
       ('multiple_choice', '운동 후 식사를 거르면 생길 수 있는 문제는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체력이 즉시 좋아진다'), JSON_OBJECT('id', 'B', 'text', '근육이 빨리 커진다'), JSON_OBJECT('id', 'C', 'text', '에너지와 영양 부족으로 회복이 더딜 수 있다'), JSON_OBJECT('id', 'D', 'text', '피로가 사라진다')), '운동 후에는 에너지와 영양소를 보충해야 회복이 원활합니다.', 'recovery', 'easy', 'C'),
       ('multiple_choice', '열사병과 열탈진의 초기 신호로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체온 저하와 졸음'), JSON_OBJECT('id', 'B', 'text', '식욕 증가'), JSON_OBJECT('id', 'C', 'text', '심한 갈증, 어지러움, 메스꺼움, 과도한 땀'), JSON_OBJECT('id', 'D', 'text', '키가 커지는 느낌')), '더위 속 운동 중 어지러움과 메스꺼움, 심한 땀은 열 관련 질환의 초기 신호일 수 있어 즉시 쉬어야 합니다.', 'safety', 'medium', 'C'),
       ('multiple_choice', '운동 일정을 세울 때 가장 현실적인 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '일과에 맞춰 지킬 수 있는 요일과 시간을 정하기'), JSON_OBJECT('id', 'B', 'text', '매일 다른 시간에 즉흥적으로 하기'), JSON_OBJECT('id', 'C', 'text', '일정이 없으면 쉬는 것이 낫다고 생각하기'), JSON_OBJECT('id', 'D', 'text', '남의 일정을 그대로 따라 하기')), '일과에 맞는 요일과 시간을 미리 정해 두면 습관이 되기 쉽고 중단할 확률이 줄어듭니다.', 'basics', 'easy', 'A'),
       ('multiple_choice', '단 음료를 물로 바꾸는 습관의 영양적 장점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '열량이 늘어난다'), JSON_OBJECT('id', 'B', 'text', '당과 열량 섭취를 줄일 수 있다'), JSON_OBJECT('id', 'C', 'text', '당이 늘어난다'), JSON_OBJECT('id', 'D', 'text', '단백질이 늘어난다')), '당 음료를 물로 바꾸면 불필요한 열량과 당 섭취를 줄일 수 있습니다.', 'water', 'medium', 'B'),
       ('multiple_choice', '식품을 고를 때 "나트륨 함량"을 확인하는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '색을 확인하기 위해서'), JSON_OBJECT('id', 'B', 'text', '나트륨 섭취를 조절하기 위해서'), JSON_OBJECT('id', 'C', 'text', '맛을 확인하기 위해서'), JSON_OBJECT('id', 'D', 'text', '가격을 확인하기 위해서')), '나트륨을 과다 섭취하면 건강에 좋지 않아 함량을 확인해 조절할 수 있습니다.', 'label', 'easy', 'B'),
       ('multiple_choice', '주관적 운동 자각도(RPE)란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '심박수를 측정한 값'), JSON_OBJECT('id', 'B', 'text', '운동한 칼로리'), JSON_OBJECT('id', 'C', 'text', '운동이 얼마나 힘들게 느껴지는지 숫자로 나타낸 것'), JSON_OBJECT('id', 'D', 'text', '체중 변화')), 'RPE는 스스로 느끼는 힘든 정도를 점수로 표현해 강도를 가늠하는 방법입니다.', 'intensity', 'medium', 'C'),
       ('multiple_choice', '민첩성이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '오래 걷는 능력'), JSON_OBJECT('id', 'B', 'text', '방향을 빠르게 바꾸는 능력'), JSON_OBJECT('id', 'C', 'text', '앉아 있는 능력'), JSON_OBJECT('id', 'D', 'text', '체온을 유지하는 능력')), '민첩성은 몸의 방향이나 위치를 빠르게 바꾸고 제어하는 능력으로 구기 종목에서 특히 중요합니다.', 'basics', 'medium', 'B'),
       ('multiple_choice', '운동 전 건강 상태를 점검하는 자가 검사 질문지로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', 'SNS 설문'), JSON_OBJECT('id', 'B', 'text', '신발 사이즈 표'), JSON_OBJECT('id', 'C', 'text', 'PAR-Q(신체활동 준비 설문)'), JSON_OBJECT('id', 'D', 'text', '음식 취향 조사')), 'PAR-Q는 운동 시작 전 위험 신호를 확인하는 간단한 설문으로 알려져 있습니다.', 'safety', 'medium', 'C'),
       ('multiple_choice', '식사에서 영양 균형을 평가하는 "식사 균형 지수" 개념의 목적은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사 가격을 비교하는 것'), JSON_OBJECT('id', 'B', 'text', '식사 시간을 재는 것'), JSON_OBJECT('id', 'C', 'text', '식당을 평가하는 것'), JSON_OBJECT('id', 'D', 'text', '식품군별 섭취 균형을 점수로 점검하는 것')), '식사의 질을 식품군별로 평가해 부족하거나 치우친 부분을 확인하는 도구입니다.', 'balance', 'hard', 'D'),
