       ('multiple_choice', '임신·수유기 영양에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '영양소 필요가 변하지 않는다'), JSON_OBJECT('id', 'B', 'text', '식사를 줄여야 한다'), JSON_OBJECT('id', 'C', 'text', '인터넷 정보만 따르면 된다'), JSON_OBJECT('id', 'D', 'text', '엽산, 철 등 특정 영양소 필요가 늘어날 수 있어 전문가 상담이 권장된다')), '임신 시기에는 엽산과 철 등 필요량이 늘어나므로 의료진과 상의하는 것이 안전합니다.', 'nutrients', 'medium', 'D'),
       ('multiple_choice', '몸의 주된 에너지원으로 가장 먼저 쓰이는 영양소는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '비타민'), JSON_OBJECT('id', 'B', 'text', '무기질'), JSON_OBJECT('id', 'C', 'text', '식이섬유'), JSON_OBJECT('id', 'D', 'text', '탄수화물')), '탄수화물은 몸과 뇌가 쓰는 주요 에너지원입니다.', 'nutrients', 'easy', 'D'),
       ('multiple_choice', '식사량을 줄이려는 사람에게 작은 그릇이 도움이 될 수 있는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '영양이 줄어들어서'), JSON_OBJECT('id', 'B', 'text', '열량이 사라져서'), JSON_OBJECT('id', 'C', 'text', '음식이 사라져서'), JSON_OBJECT('id', 'D', 'text', '같은 양이어도 더 충분해 보여 심리적 만족을 줄 수 있어서')), '작은 그릇은 적은 양도 충분해 보이게 해 과식을 줄이는 데 도움이 될 수 있습니다.', 'habit', 'medium', 'D'),
       ('multiple_choice', '정리운동에 포함하면 좋은 호흡 활동의 효과로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '심박수를 즉시 두 배로 올린다'), JSON_OBJECT('id', 'B', 'text', '근육량을 줄인다'), JSON_OBJECT('id', 'C', 'text', '체온을 올려 땀을 더 흘리게 한다'), JSON_OBJECT('id', 'D', 'text', '긴장을 풀고 심박수를 낮추는 데 도움이 된다')), '천천히 깊게 숨 쉬면 부교감신경이 활성화되어 긴장이 풀리고 심박이 안정되는 데 도움이 됩니다.', 'warmup', 'medium', 'D'),
       ('multiple_choice', '시장에서 생선을 고를 때 신선한 생선의 특징으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '눈이 흐리고 살이 흐물한 것'), JSON_OBJECT('id', 'B', 'text', '냄새가 심하게 나는 것'), JSON_OBJECT('id', 'C', 'text', '색이 변한 것'), JSON_OBJECT('id', 'D', 'text', '눈이 맑고 살이 탄력 있으며 비린내가 심하지 않은 것')), '신선한 생선은 눈이 맑고 살에 탄력이 있으며 냄새가 심하지 않습니다.', 'label', 'easy', 'D'),
       ('multiple_choice', '운동 직후 갑자기 샤워 온도를 극단적으로 바꾸면 안 되는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 영구히 사라져서'), JSON_OBJECT('id', 'B', 'text', '체중이 두 배가 되어서'), JSON_OBJECT('id', 'C', 'text', '체온과 심박이 아직 높아 급격한 온도 변화가 부담이 될 수 있어서'), JSON_OBJECT('id', 'D', 'text', '샤워는 운동 효과를 없애서')), '운동 직후에는 체온과 심박이 높아 극단적인 온도 변화는 몸에 부담을 줄 수 있어 미지근하게 시작하는 편이 안전합니다.', 'warmup', 'medium', 'C'),
       ('multiple_choice', '식습관 개선이 단기 다이어트보다 효과적인 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '지속 가능한 습관이 장기적인 건강 관리에 유리해서'), JSON_OBJECT('id', 'B', 'text', '효과가 짧아서'), JSON_OBJECT('id', 'C', 'text', '체중이 항상 늘어서'), JSON_OBJECT('id', 'D', 'text', '식사를 줄이기 때문')), '일시적인 제한보다 오래 지킬 수 있는 습관이 장기적 건강에 중요합니다.', 'habit', 'hard', 'A'),
       ('multiple_choice', '유산소 운동 강도를 가늠하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '대화 가능 여부와 심박수 확인'), JSON_OBJECT('id', 'B', 'text', '날씨 확인'), JSON_OBJECT('id', 'C', 'text', '신발 크기'), JSON_OBJECT('id', 'D', 'text', '운동복 색')), '말하기 테스트나 심박수는 간단히 강도를 가늠하는 방법입니다.', 'intensity', 'medium', 'A'),
       ('multiple_choice', '어깨 돌리기는 어느 부위의 준비운동일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '어깨 관절'), JSON_OBJECT('id', 'B', 'text', '발목 관절'), JSON_OBJECT('id', 'C', 'text', '무릎 관절'), JSON_OBJECT('id', 'D', 'text', '손가락 관절')), '어깨를 앞뒤로 천천히 돌리면 어깨 관절 주변이 풀립니다.', 'warmup', 'easy', 'A'),
       ('multiple_choice', '사이드 플랭크에서 몸의 알맞은 모양은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '엉덩이가 아래로 처진 모양'), JSON_OBJECT('id', 'B', 'text', '허리가 크게 굽은 모양'), JSON_OBJECT('id', 'C', 'text', '다리가 위로 들린 모양'), JSON_OBJECT('id', 'D', 'text', '옆에서 봤을 때 머리부터 발까지 일직선')), '옆으로 선 자세에서도 몸을 일직선으로 유지해야 옆구리와 코어가 효과적으로 일합니다.', 'form', 'medium', 'D'),
       ('multiple_choice', '운동 중 숨이 차서 한 단어도 말하기 어렵다면 강도는 어떨까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '매우 높은 강도'), JSON_OBJECT('id', 'B', 'text', '아주 낮은 강도'), JSON_OBJECT('id', 'C', 'text', '쉬는 상태'), JSON_OBJECT('id', 'D', 'text', '알 수 없다')), '말하기 힘들 만큼 숨이 찬다면 고강도에 해당하며, 몸 상태에 맞게 강도를 조절해야 합니다.', 'intensity', 'easy', 'A'),
       ('multiple_choice', '식품의 열효과(식이성 발열 효과)란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '음식을 소화·흡수·대사하는 데 쓰이는 에너지'), JSON_OBJECT('id', 'B', 'text', '운동으로 쓰는 에너지'), JSON_OBJECT('id', 'C', 'text', '체온을 올리는 음식'), JSON_OBJECT('id', 'D', 'text', '열을 내는 요리 방법')), '음식을 먹고 소화·대사하는 과정에서 에너지가 일부 소비되며 영양소별로 정도가 다릅니다.', 'nutrients', 'hard', 'A'),
       ('multiple_choice', '운동 후 근육이 따뜻할 때 스트레칭하는 것이 유연성 향상에 유리하다고 보는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육의 신축성이 높아져 더 편하게 늘어나기 때문'), JSON_OBJECT('id', 'B', 'text', '근육이 완전히 굳기 때문'), JSON_OBJECT('id', 'C', 'text', '근육이 사라지기 때문'), JSON_OBJECT('id', 'D', 'text', '뼈가 늘어나기 때문')), '운동으로 근육 온도가 올라가 있으면 조직이 더 잘 늘어나 스트레칭이 편하고 안전합니다.', 'warmup', 'medium', 'A'),
       ('multiple_choice', '"적정 에너지 필요량(EER)"에 영향을 주는 요소로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '신발 크기'), JSON_OBJECT('id', 'B', 'text', '나이, 성별, 체격, 활동량'), JSON_OBJECT('id', 'C', 'text', '머리카락 색'), JSON_OBJECT('id', 'D', 'text', '핸드폰 기종')), '개인의 나이와 성별, 체격, 신체활동량에 따라 필요한 에너지량이 달라집니다.', 'nutrients', 'hard', 'B'),
       ('multiple_choice', '운동 시작 전 목표 심박수 범위를 알기 위해 활용할 수 있는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '날씨 앱'), JSON_OBJECT('id', 'B', 'text', '시계의 알람'), JSON_OBJECT('id', 'C', 'text', '달력'), JSON_OBJECT('id', 'D', 'text', '스마트워치나 운동 앱의 심박수 표시')), '심박 측정 기능이 있는 기기로 운동 중 강도를 간단히 확인할 수 있습니다.', 'intensity', 'easy', 'D'),
