       ('multiple_choice', '운동 시간대에 대한 설명으로 가장 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '새벽에만 해야 효과가 있다'), JSON_OBJECT('id', 'B', 'text', '밤에 하면 반드시 해롭다'), JSON_OBJECT('id', 'C', 'text', '식사 직후가 가장 좋다'), JSON_OBJECT('id', 'D', 'text', '본인이 꾸준히 지킬 수 있는 시간이 좋다')), '개인의 생활 리듬에 맞춰 꾸준히 할 수 있는 시간대를 고르는 것이 가장 중요합니다.', 'basics', 'easy', 'D'),
       ('multiple_choice', '운동 중 근육이 "경련"을 일으킬 때 일반적인 대처로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '더 세게 운동하기'), JSON_OBJECT('id', 'B', 'text', '근육을 세게 때리기'), JSON_OBJECT('id', 'C', 'text', '찬물을 마시지 않기'), JSON_OBJECT('id', 'D', 'text', '운동을 멈추고 해당 근육을 천천히 늘리며 수분 보충하기')), '근육 경련이 오면 멈추고 천천히 스트레칭하며 수분 상태를 점검하는 것이 일반적인 대처입니다.', 'body', 'hard', 'D'),
       ('multiple_choice', '운동 장소의 응급 대비로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '아무것도 확인하지 않기'), JSON_OBJECT('id', 'B', 'text', '조명만 확인하기'), JSON_OBJECT('id', 'C', 'text', '음악 목록 확인하기'), JSON_OBJECT('id', 'D', 'text', '응급 연락처와 AED 위치, 구급 상자 확인하기')), '응급 상황에 대비해 연락처와 AED 위치, 구급 상자를 미리 확인해 두면 대응이 빨라집니다.', 'safety', 'hard', 'D'),
       ('multiple_choice', '나트륨이 많이 들어 있는 식품으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '라면 국물과 젓갈'), JSON_OBJECT('id', 'B', 'text', '생수'), JSON_OBJECT('id', 'C', 'text', '오이'), JSON_OBJECT('id', 'D', 'text', '사과')), '라면 국물, 젓갈, 장아찌, 가공식품은 나트륨 함량이 높은 편입니다.', 'nutrients', 'easy', 'A'),
       ('multiple_choice', '어깨를 덮고 있는 둥근 근육은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '대퇴사두근'), JSON_OBJECT('id', 'B', 'text', '비복근'), JSON_OBJECT('id', 'C', 'text', '복횡근'), JSON_OBJECT('id', 'D', 'text', '삼각근')), '삼각근은 팔을 앞, 옆, 뒤로 들어 올릴 때 쓰이는 어깨 근육입니다.', 'body', 'easy', 'D'),
       ('multiple_choice', '운동 복장으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '움직이기 편하고 땀이 잘 마르는 옷'), JSON_OBJECT('id', 'B', 'text', '몸에 꽉 끼어 숨쉬기 힘든 옷'), JSON_OBJECT('id', 'C', 'text', '아주 두꺼운 겉옷'), JSON_OBJECT('id', 'D', 'text', '길어서 밟기 쉬운 바지')), '활동하기 편하고 통기성이 좋은 옷이 안전하고 쾌적합니다.', 'safety', 'easy', 'A'),
       ('multiple_choice', '외식 메뉴를 고를 때 균형을 맞추는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '튀김만 주문하기'), JSON_OBJECT('id', 'B', 'text', '탄산음료를 추가하기'), JSON_OBJECT('id', 'C', 'text', '밥만 주문하기'), JSON_OBJECT('id', 'D', 'text', '채소 반찬이 있는 메뉴나 곁들임 샐러드 선택하기')), '채소가 포함된 메뉴를 고르면 외식에서도 영양 균형을 맞추기 쉽습니다.', 'balance', 'medium', 'D'),
       ('multiple_choice', '신체활동 중 앉아서 하는 시간을 대체하면 좋은 행동은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '가볍게 서서 움직이거나 걷기'), JSON_OBJECT('id', 'B', 'text', '더 오래 눕기'), JSON_OBJECT('id', 'C', 'text', '화면만 계속 보기'), JSON_OBJECT('id', 'D', 'text', '식사 후 바로 눕기')), '앉아 있는 시간을 서서 움직이거나 걷는 시간으로 바꾸면 하루 에너지 소비가 늘어납니다.', 'basics', 'medium', 'A'),
