       ('multiple_choice', '수용성 식이섬유의 특징으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '물에 전혀 반응하지 않는다'), JSON_OBJECT('id', 'B', 'text', '물에 녹아 겔처럼 되어 포만감과 혈당 조절에 도움을 줄 수 있다'), JSON_OBJECT('id', 'C', 'text', '열량이 매우 높다'), JSON_OBJECT('id', 'D', 'text', '단백질로 바뀐다')), '귀리, 과일, 해조류 등에 있는 수용성 식이섬유는 소화 속도를 늦추는 데 도움을 줄 수 있습니다.', 'nutrients', 'medium', 'B'),
       ('multiple_choice', '즉석식품(도시락, 간편식)의 영양 균형을 확인하는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '포장 색만 보기'), JSON_OBJECT('id', 'B', 'text', '가격만 보기'), JSON_OBJECT('id', 'C', 'text', '영양성분표의 열량·나트륨·단백질과 채소 포함 여부를 함께 보기'), JSON_OBJECT('id', 'D', 'text', '이름만 보기')), '즉석식품은 나트륨과 열량이 높을 수 있어 영양성분과 구성을 함께 확인하고 채소 등을 곁들여 보완합니다.', 'label', 'hard', 'C'),
       ('multiple_choice', '근육의 길이와 힘의 관계에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육은 길수록 항상 강하다'), JSON_OBJECT('id', 'B', 'text', '근육 길이는 힘과 무관하다'), JSON_OBJECT('id', 'C', 'text', '근육은 적절한 길이에서 가장 큰 힘을 낼 수 있다'), JSON_OBJECT('id', 'D', 'text', '짧을수록 항상 강하다')), '근육은 적정 길이 범위에서 가장 효율적으로 힘을 낼 수 있습니다.', 'body', 'medium', 'C'),
       ('multiple_choice', '운동 후 땀 냄새가 날 때 가장 알맞은 위생 습관은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '젖은 옷을 계속 입기'), JSON_OBJECT('id', 'B', 'text', '샤워하고 마른 옷으로 갈아입기'), JSON_OBJECT('id', 'C', 'text', '샤워하지 않기'), JSON_OBJECT('id', 'D', 'text', '땀을 닦지 않기')), '운동 후 땀을 씻고 마른 옷으로 갈아입으면 피부를 청결히 하고 체온 유지에도 좋습니다.', 'basics', 'easy', 'B'),
       ('multiple_choice', '정리운동을 하는 동안 호흡은 어떻게 하는 것이 좋을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '숨을 참기'), JSON_OBJECT('id', 'B', 'text', '빠르게 헐떡이기'), JSON_OBJECT('id', 'C', 'text', '입을 막기'), JSON_OBJECT('id', 'D', 'text', '깊고 천천히 호흡하기')), '천천히 깊게 숨 쉬면 심박수를 낮추고 몸을 안정시키는 데 도움이 됩니다.', 'warmup', 'medium', 'D'),
       ('multiple_choice', '랙 풀(하프 데드)에서 바를 올리는 목적은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '가동 범위를 줄여 특정 구간을 연습하기'), JSON_OBJECT('id', 'B', 'text', '운동을 쉽게 포기하기'), JSON_OBJECT('id', 'C', 'text', '무게를 줄이는 것만'), JSON_OBJECT('id', 'D', 'text', '바닥을 닦는 것')), '바를 높여 시작하면 움직이는 범위를 줄여 특정 구간의 힘을 연습할 수 있습니다.', 'form', 'medium', 'A'),
       ('multiple_choice', '밸런스 운동에서 한 발 서기 훈련이 도움이 되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '시력을 높이기 때문'), JSON_OBJECT('id', 'B', 'text', '체온을 낮추기 때문'), JSON_OBJECT('id', 'C', 'text', '고유수용감각과 안정근을 단련하기 때문'), JSON_OBJECT('id', 'D', 'text', '호흡을 멈추기 때문')), '한 발로 서면 발목과 고관절 주변 안정근이 일하고 몸의 위치 감각이 길러집니다.', 'form', 'medium', 'C'),
