       ('multiple_choice', '신체활동 지침에서 유산소와 근력 운동의 관계로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '하나만 하면 다른 하나는 해로워진다'), JSON_OBJECT('id', 'B', 'text', '두 가지는 같은 날 절대 해서는 안 된다'), JSON_OBJECT('id', 'C', 'text', '서로 보완하므로 함께 하는 것이 좋다'), JSON_OBJECT('id', 'D', 'text', '근력 운동은 유산소 운동을 대체한다')), '유산소 운동은 심폐 건강에, 근력 운동은 근골격 건강에 도움이 되어 두 가지를 함께 하는 것이 권장됩니다.', 'basics', 'medium', 'C'),
       ('multiple_choice', '"먹는 것을 보상으로 쓰는 습관"의 문제점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식습관이 항상 좋아진다'), JSON_OBJECT('id', 'B', 'text', '식사량이 줄어든다'), JSON_OBJECT('id', 'C', 'text', '배고픔과 상관없는 섭취를 늘려 정서적 섭식을 강화할 수 있다'), JSON_OBJECT('id', 'D', 'text', '문제가 없다')), '음식을 보상으로 삼으면 감정이나 보상과 음식이 연결되어 정서적 섭식으로 이어질 수 있습니다.', 'habit', 'medium', 'C'),
       ('multiple_choice', '균형 잡힌 한 끼 식사의 기본 구성으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '밥만 먹기'), JSON_OBJECT('id', 'B', 'text', '단백질 반찬만 먹기'), JSON_OBJECT('id', 'C', 'text', '곡류, 단백질 반찬, 채소를 함께 먹기'), JSON_OBJECT('id', 'D', 'text', '과자만 먹기')), '곡류와 단백질, 채소를 함께 먹으면 여러 영양소를 고르게 섭취할 수 있습니다.', 'balance', 'easy', 'C'),
       ('multiple_choice', '날 음식(회, 육회 등)을 먹을 때 주의할 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '오래 두어도 안전하다'), JSON_OBJECT('id', 'B', 'text', '항상 안전하다'), JSON_OBJECT('id', 'C', 'text', '신선도와 보관 상태를 확인하고 취약한 사람은 피하기'), JSON_OBJECT('id', 'D', 'text', '손을 씻지 않아도 된다')), '날 음식은 가열하지 않아 식중독 위험이 높아 신선도와 위생을 확인하고 임산부·노약자는 주의해야 합니다.', 'hygiene', 'medium', 'C'),
       ('multiple_choice', '식사할 때 꼭꼭 씹어 먹으면 좋은 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '소화를 돕고 포만감을 느끼기 쉽다'), JSON_OBJECT('id', 'B', 'text', '소화가 안 된다'), JSON_OBJECT('id', 'C', 'text', '배가 더 고파진다'), JSON_OBJECT('id', 'D', 'text', '식사 시간이 줄어든다')), '충분히 씹으면 소화가 쉬워지고 포만감을 느끼는 데 도움이 됩니다.', 'habit', 'easy', 'A'),
       ('multiple_choice', '"고단백" 표시를 볼 때 확인하면 좋은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '글자의 크기'), JSON_OBJECT('id', 'B', 'text', '포장 색'), JSON_OBJECT('id', 'C', 'text', '1회 제공량당 단백질 함량과 다른 영양소(당류·나트륨·지방)'), JSON_OBJECT('id', 'D', 'text', '제품 이름 길이')), '고단백 표시가 있어도 당류나 나트륨, 포화지방이 많을 수 있어 전체 영양 성분을 확인해야 합니다.', 'label', 'medium', 'C'),
       ('multiple_choice', '운동 중 어지러움이 느껴질 때 알맞은 행동은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '더 빨리 달리기'), JSON_OBJECT('id', 'B', 'text', '무거운 것을 들기'), JSON_OBJECT('id', 'C', 'text', '운동을 멈추고 앉아서 쉬기'), JSON_OBJECT('id', 'D', 'text', '숨을 참기')), '어지러우면 쓰러질 위험이 있어 즉시 멈추고 안전한 자세로 쉬어야 합니다.', 'safety', 'easy', 'C'),
       ('multiple_choice', '운동 후 체온이 오른 상태에서 바로 찬 곳에 오래 머무르면 어떨까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체력이 좋아진다'), JSON_OBJECT('id', 'B', 'text', '몸이 갑자기 식어 불편할 수 있다'), JSON_OBJECT('id', 'C', 'text', '근육이 커진다'), JSON_OBJECT('id', 'D', 'text', '아무 영향이 없다')), '운동 후 급격한 체온 변화는 컨디션에 부담이 될 수 있어 정리 운동으로 서서히 낮추는 것이 좋습니다.', 'recovery', 'easy', 'B'),
       ('multiple_choice', '푸시업으로 주로 단련되는 부위가 아닌 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '종아리'), JSON_OBJECT('id', 'B', 'text', '가슴'), JSON_OBJECT('id', 'C', 'text', '어깨'), JSON_OBJECT('id', 'D', 'text', '위팔 뒤쪽')), '푸시업은 가슴, 어깨, 삼두근과 몸통 코어가 주로 쓰이며 종아리의 비중은 작습니다.', 'body', 'easy', 'A'),
       ('multiple_choice', '허리가 불편한 날 데드리프트를 해도 되는지에 대한 안전한 판단은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '무조건 최대 중량으로 하기'), JSON_OBJECT('id', 'B', 'text', '통증은 무시하기'), JSON_OBJECT('id', 'C', 'text', '허리를 더 굽히기'), JSON_OBJECT('id', 'D', 'text', '통증이 있으면 쉬거나 강도를 크게 낮추고 필요하면 상담하기')), '허리 통증은 신체의 경고 신호일 수 있어 무리하지 않고 필요하면 전문가 상담을 받아야 합니다.', 'safety', 'medium', 'D'),
       ('multiple_choice', '탄수화물이 몸에서 에너지로 쓰이지 않고 남을 때 저장되는 형태로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '아미노산'), JSON_OBJECT('id', 'B', 'text', '비타민'), JSON_OBJECT('id', 'C', 'text', '글리코겐(간과 근육에 저장)과 일부는 지방'), JSON_OBJECT('id', 'D', 'text', '무기질')), '남는 포도당은 간과 근육에 글리코겐으로 저장되고 그 이상은 지방으로 전환될 수 있습니다.', 'nutrients', 'hard', 'C'),
       ('multiple_choice', '식품에서 "나트륨 환산식(소금 환산)"이 필요한 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '나트륨 표시를 소금량으로 바꿔 이해하기 쉽게 하기 위해서'), JSON_OBJECT('id', 'B', 'text', '맛을 높이기 위해서'), JSON_OBJECT('id', 'C', 'text', '가격을 계산하기 위해서'), JSON_OBJECT('id', 'D', 'text', '색을 구분하기 위해서')), '나트륨 mg을 2.5배 정도 하면 소금(염화나트륨) 양이 되어 섭취 기준과 비교하기 쉽습니다.', 'label', 'hard', 'A'),
       ('multiple_choice', '운동 전 스트레칭 중 숨이 가빠지면 어떻게 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '숨을 더 참기'), JSON_OBJECT('id', 'B', 'text', '자세를 풀고 호흡을 고른 뒤 다시 하기'), JSON_OBJECT('id', 'C', 'text', '더 세게 늘리기'), JSON_OBJECT('id', 'D', 'text', '무시하고 계속하기')), '스트레칭은 편안한 호흡이 기본이므로 숨이 가쁘면 자세를 풀고 호흡을 가다듬는 것이 좋습니다.', 'warmup', 'easy', 'B'),
       ('multiple_choice', '채소를 싫어하는 사람이 섭취를 늘리는 쉬운 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '채소를 아예 먹지 않기'), JSON_OBJECT('id', 'B', 'text', '채소 주스만 마시기'), JSON_OBJECT('id', 'C', 'text', '좋아하는 요리에 잘게 썰어 넣거나 조리법을 바꿔 보기'), JSON_OBJECT('id', 'D', 'text', '채소를 버리기')), '조리법이나 요리에 섞는 방법으로 거부감을 줄이면 섭취를 늘리기 쉽습니다.', 'balance', 'easy', 'C'),
       ('multiple_choice', '근지구력이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 번에 낼 수 있는 가장 큰 힘만'), JSON_OBJECT('id', 'B', 'text', '관절이 휘어지는 정도'), JSON_OBJECT('id', 'C', 'text', '숨을 오래 참는 능력'), JSON_OBJECT('id', 'D', 'text', '근육이 힘을 반복해서 오래 낼 수 있는 능력')), '근지구력은 같은 근육이 일정한 힘을 여러 번 또는 오래 낼 수 있는 능력입니다.', 'basics', 'medium', 'D'),
       ('multiple_choice', '더운 날 야외에서 활동할 때 알맞은 수분 섭취 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '활동 전후와 중간에 물을 자주 마시기'), JSON_OBJECT('id', 'B', 'text', '활동이 끝난 뒤에만 마시기'), JSON_OBJECT('id', 'C', 'text', '물을 마시지 않기'), JSON_OBJECT('id', 'D', 'text', '술을 마시기')), '더운 날에는 땀 손실이 커서 미리, 중간에, 이후에 나누어 마시는 것이 좋습니다.', 'water', 'easy', 'A'),
       ('multiple_choice', '운동 습관 형성에서 실행 의도(구체적인 때와 장소 정하기)가 도움이 되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '의지를 완전히 없애기 때문'), JSON_OBJECT('id', 'B', 'text', '운동 효과를 두 배로 만들기 때문'), JSON_OBJECT('id', 'C', 'text', '언제 어디서 할지 미리 정해 결정 부담을 줄이기 때문'), JSON_OBJECT('id', 'D', 'text', '체력을 즉시 올리기 때문')), '"퇴근 후 집 앞 공원에서 20분 걷기"처럼 때와 장소를 정하면 매번 고민하지 않아 실행 확률이 높아집니다.', 'basics', 'hard', 'C'),
       ('multiple_choice', '운동 안전 수칙을 지키는 가장 근본적인 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 시간을 늘리기 위해서'), JSON_OBJECT('id', 'B', 'text', '기구를 아끼기 위해서'), JSON_OBJECT('id', 'C', 'text', '오래 건강하게 운동을 이어가기 위해서'), JSON_OBJECT('id', 'D', 'text', '남에게 보여 주기 위해서')), '안전을 지키면 부상 없이 꾸준히 운동할 수 있어 장기적인 건강에 도움이 됩니다.', 'safety', 'hard', 'C'),
       ('multiple_choice', '준비운동으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '곧바로 전력 질주'), JSON_OBJECT('id', 'B', 'text', '가장 무거운 무게 들기'), JSON_OBJECT('id', 'C', 'text', '아무것도 하지 않고 앉기'), JSON_OBJECT('id', 'D', 'text', '제자리 걷기와 가벼운 관절 돌리기')), '가벼운 움직임으로 시작해 서서히 강도를 높이는 것이 준비운동의 기본입니다.', 'warmup', 'easy', 'D'),
       ('multiple_choice', '칼슘의 흡수율에 영향을 줄 수 있는 요인으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '신발 크기'), JSON_OBJECT('id', 'B', 'text', '운동복 색상'), JSON_OBJECT('id', 'C', 'text', '조명 밝기'), JSON_OBJECT('id', 'D', 'text', '비타민 D 상태와 식이 구성')), '비타민 D와 함께 식이 성분에 따라 칼슘 흡수율이 달라질 수 있습니다.', 'nutrients', 'hard', 'D'),
       ('multiple_choice', '간식을 선택할 때 "포만감"을 고려하는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사량을 늘리기 위해서'), JSON_OBJECT('id', 'B', 'text', '식사를 대신하기 위해서'), JSON_OBJECT('id', 'C', 'text', '다음 식사까지 허기를 조절하고 과식을 줄이기 위해서'), JSON_OBJECT('id', 'D', 'text', '체중을 늘리기 위해서')), '단백질과 식이섬유가 있는 간식은 포만감을 오래 유지하는 데 도움이 됩니다.', 'practice', 'medium', 'C'),
       ('multiple_choice', '근육이 충분히 데워지지 않은 상태에서 강한 스트레칭을 하면 어떨 수 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육과 힘줄에 무리가 갈 수 있다'), JSON_OBJECT('id', 'B', 'text', '항상 더 부드러워진다'), JSON_OBJECT('id', 'C', 'text', '체온이 낮아진다'), JSON_OBJECT('id', 'D', 'text', '효과가 두 배가 된다')), '차가운 근육을 갑자기 강하게 늘리면 손상 위험이 커지므로 먼저 가볍게 몸을 데우는 것이 좋습니다.', 'warmup', 'medium', 'A'),
       ('multiple_choice', '체력 향상의 특이성 원리를 가장 잘 설명한 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '훈련한 방식에 가까운 능력이 주로 향상된다'), JSON_OBJECT('id', 'B', 'text', '어떤 운동을 해도 모든 능력이 똑같이 향상된다'), JSON_OBJECT('id', 'C', 'text', '훈련과 결과는 무관하다'), JSON_OBJECT('id', 'D', 'text', '한 가지 운동만 해도 모든 종목에 최고가 된다')), '달리기를 하면 달리기 능력이, 근력 운동을 하면 근력이 주로 향상됩니다. 목표에 맞는 운동을 고르는 이유입니다.', 'basics', 'medium', 'A'),
       ('multiple_choice', '푸시업에서 손의 위치로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '머리 위 멀리'), JSON_OBJECT('id', 'B', 'text', '허리 옆 뒤쪽'), JSON_OBJECT('id', 'C', 'text', '어깨 아래 또는 조금 넓은 위치'), JSON_OBJECT('id', 'D', 'text', '발 옆')), '손을 어깨 아래쯤에 두면 어깨와 팔꿈치에 알맞게 힘이 실립니다.', 'form', 'easy', 'C'),
       ('multiple_choice', '수영 전 준비운동에서 특히 신경 써야 할 부위는 어디일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손톱'), JSON_OBJECT('id', 'B', 'text', '어깨와 목, 발목 관절'), JSON_OBJECT('id', 'C', 'text', '머리카락'), JSON_OBJECT('id', 'D', 'text', '이마')), '수영은 어깨와 목, 발목을 많이 쓰므로 이 부위를 가볍게 풀어 주는 것이 좋습니다.', 'warmup', 'medium', 'B'),
       ('multiple_choice', '뼈와 치아를 튼튼하게 하는 대표적인 무기질은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '나트륨'), JSON_OBJECT('id', 'B', 'text', '철'), JSON_OBJECT('id', 'C', 'text', '요오드'), JSON_OBJECT('id', 'D', 'text', '칼슘')), '칼슘은 뼈와 치아의 주요 구성 성분입니다.', 'nutrients', 'easy', 'D'),
       ('multiple_choice', '운동 종목이 바뀔 때 준비운동을 조정해야 하는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '준비운동은 종목과 무관하기 때문'), JSON_OBJECT('id', 'B', 'text', '종목마다 쓰는 근육과 관절이 다르기 때문'), JSON_OBJECT('id', 'C', 'text', '준비운동은 항상 똑같아야 하기 때문'), JSON_OBJECT('id', 'D', 'text', '종목이 바뀌면 준비운동을 하면 안 되기 때문')), '수영은 어깨, 달리기는 다리, 상체 근력 운동은 어깨와 팔을 많이 쓰므로 해당 부위를 중심으로 준비하는 것이 좋습니다.', 'warmup', 'hard', 'B'),
