       ('multiple_choice', '운동 후 가벼운 요가나 필라테스 동작이 회복에 줄 수 있는 이점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육 파괴'), JSON_OBJECT('id', 'B', 'text', '체온 급상승'), JSON_OBJECT('id', 'C', 'text', '호흡 곤란'), JSON_OBJECT('id', 'D', 'text', '유연성 향상과 긴장 완화')), '부드러운 동작과 호흡은 긴장 완화와 유연성 유지에 도움이 될 수 있습니다.', 'recovery', 'medium', 'D'),
       ('multiple_choice', '탄수화물 1g이 내는 열량은 약 얼마일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '약 9kcal'), JSON_OBJECT('id', 'B', 'text', '약 0kcal'), JSON_OBJECT('id', 'C', 'text', '약 4kcal'), JSON_OBJECT('id', 'D', 'text', '약 20kcal')), '탄수화물과 단백질은 1g당 약 4kcal, 지방은 약 9kcal의 열량을 냅니다.', 'nutrients', 'easy', 'C'),
       ('multiple_choice', '운동 시간이 너무 부족할 때 알맞은 생각은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '30분 미만은 의미가 전혀 없다'), JSON_OBJECT('id', 'B', 'text', '짧은 운동도 하지 않는 것보다 낫다'), JSON_OBJECT('id', 'C', 'text', '1시간 이상만 가치가 있다'), JSON_OBJECT('id', 'D', 'text', '운동은 포기하는 것이 낫다')), '짧은 시간의 운동도 쌓이면 도움이 됩니다. 시간이 없다고 아예 건너뛰기보다 작게라도 움직이는 것이 좋습니다.', 'basics', 'easy', 'B'),
       ('multiple_choice', '심한 설사나 구토 후 수분 보충 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '조금씩 자주 마시고 필요하면 경구 수액을 활용하기'), JSON_OBJECT('id', 'B', 'text', '한 번에 많이 마시기'), JSON_OBJECT('id', 'C', 'text', '전혀 마시지 않기'), JSON_OBJECT('id', 'D', 'text', '커피만 마시기')), '탈수 위험이 높아 소량씩 자주 수분을 보충하고 증상이 심하면 진료를 받아야 합니다.', 'water', 'medium', 'A'),
       ('multiple_choice', '운동선수의 식단에서 수분과 전해질이 중요한 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '땀이 나지 않아서'), JSON_OBJECT('id', 'B', 'text', '전해질은 해로워서'), JSON_OBJECT('id', 'C', 'text', '수분은 필요 없어서'), JSON_OBJECT('id', 'D', 'text', '땀으로 수분과 전해질이 손실되어 보충이 필요해서')), '운동량이 많으면 땀으로 손실되는 수분과 전해질을 보충해야 수행과 회복에 유리합니다.', 'balance', 'hard', 'D'),
       ('multiple_choice', '스쿼트에서 알맞은 시작 자세는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '발을 모으고 허리를 구부리고 서기'), JSON_OBJECT('id', 'B', 'text', '발을 어깨너비 정도로 벌리고 가슴을 펴고 서기'), JSON_OBJECT('id', 'C', 'text', '발끝을 안쪽으로 모으고 서기'), JSON_OBJECT('id', 'D', 'text', '한 발만 들고 서기')), '어깨너비 정도의 발 간격과 곧게 편 가슴은 균형과 하체 힘 발휘에 도움이 되는 기본 자세입니다.', 'form', 'easy', 'B'),
       ('multiple_choice', '유제품을 먹기 어려운 사람이 칼슘을 얻을 수 있는 대안은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '설탕'), JSON_OBJECT('id', 'B', 'text', '탄산음료'), JSON_OBJECT('id', 'C', 'text', '식용유'), JSON_OBJECT('id', 'D', 'text', '두부, 멸치, 녹색 채소 등')), '유제품 외에도 두부, 뼈째 먹는 생선, 일부 녹색 채소에서 칼슘을 얻을 수 있습니다.', 'balance', 'medium', 'D'),
       ('multiple_choice', '식사 후 가볍게 움직이는 습관이 도움이 되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '소화를 막아서'), JSON_OBJECT('id', 'B', 'text', '식욕을 늘려서'), JSON_OBJECT('id', 'C', 'text', '소화를 돕고 활동량을 늘리는 데 도움이 되어서'), JSON_OBJECT('id', 'D', 'text', '체력이 떨어져서')), '식후 가벼운 걷기는 소화와 혈당 관리에 도움이 될 수 있습니다.', 'practice', 'easy', 'C'),
       ('multiple_choice', '식사 기록 앱을 쓸 때 정확성을 높이는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '일주일 뒤 몰아서 기록하기'), JSON_OBJECT('id', 'B', 'text', '대충 기억나는 대로 쓰기'), JSON_OBJECT('id', 'C', 'text', '먹은 직후 기록하고 양과 조리법까지 입력하기'), JSON_OBJECT('id', 'D', 'text', '기록하지 않기')), '먹은 직후 기록하면 누락과 오차를 줄일 수 있습니다.', 'habit', 'hard', 'C'),
       ('multiple_choice', '운동 중 호흡에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '항상 숨을 참고 운동하기'), JSON_OBJECT('id', 'B', 'text', '입을 꼭 다물고 숨 쉬지 않기'), JSON_OBJECT('id', 'C', 'text', '숨을 참지 말고 자연스럽게 쉬기'), JSON_OBJECT('id', 'D', 'text', '한 번에 숨을 크게 한 번만 쉬기')), '숨을 오래 참으면 혈압이 크게 오를 수 있어 자연스럽게 호흡하며 운동하는 것이 안전합니다.', 'basics', 'easy', 'C'),
       ('multiple_choice', '식품 포장지의 "알레르기 유발 물질" 표시를 확인해야 하는 사람은 누구일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동하는 사람'), JSON_OBJECT('id', 'B', 'text', '식품 알레르기가 있는 사람'), JSON_OBJECT('id', 'C', 'text', '키가 큰 사람'), JSON_OBJECT('id', 'D', 'text', '채식하는 사람만')), '알레르기가 있는 사람은 원재료와 알레르기 표시를 반드시 확인해야 합니다.', 'label', 'easy', 'B'),
       ('multiple_choice', '근력 운동 권고에서 흔히 제시되는 빈도는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '월 1일'), JSON_OBJECT('id', 'B', 'text', '주 2일 이상, 주요 근육군을 포함'), JSON_OBJECT('id', 'C', 'text', '매일 최대 강도'), JSON_OBJECT('id', 'D', 'text', '하지 않아도 된다')), '성인에게는 주 2일 이상 주요 근육군을 다루는 근력 운동이 권장됩니다.', 'intensity', 'medium', 'B'),
       ('multiple_choice', '운동 동작에서 템포(속도 조절) 훈련의 장점으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 시간이 항상 줄어든다'), JSON_OBJECT('id', 'B', 'text', '근육이 쉬게 된다'), JSON_OBJECT('id', 'C', 'text', '반동을 줄이고 근육이 일하는 시간을 늘릴 수 있다'), JSON_OBJECT('id', 'D', 'text', '호흡이 필요 없다')), '내리는 속도를 천천히 하는 등 템포를 정하면 반동을 줄이고 근육에 걸리는 시간을 늘릴 수 있습니다.', 'form', 'hard', 'C'),
       ('multiple_choice', '런지를 할 때 상체 자세로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '크게 앞으로 숙이기'), JSON_OBJECT('id', 'B', 'text', '곧게 세우고 시선은 앞'), JSON_OBJECT('id', 'C', 'text', '뒤로 크게 젖히기'), JSON_OBJECT('id', 'D', 'text', '옆으로 기울이기')), '상체를 곧게 유지하면 균형이 잘 잡히고 허리에 무리가 적습니다.', 'form', 'easy', 'B'),
       ('multiple_choice', '수면 부족이 식욕 조절에 미치는 영향으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식욕이 항상 완벽히 조절된다'), JSON_OBJECT('id', 'B', 'text', '식욕 관련 호르몬 균형에 영향을 줄 수 있다'), JSON_OBJECT('id', 'C', 'text', '식욕과 무관하다'), JSON_OBJECT('id', 'D', 'text', '식욕이 사라진다')), '수면 부족은 식욕을 높이는 호르몬과 낮추는 호르몬의 균형에 영향을 줄 수 있다고 알려져 있습니다.', 'recovery', 'hard', 'B'),
       ('multiple_choice', '식단에서 비타민 D를 식품으로 얻기 어려운 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 식품에 매우 많아서'), JSON_OBJECT('id', 'B', 'text', '비타민 D는 몸에 필요 없어서'), JSON_OBJECT('id', 'C', 'text', '풍부하게 함유한 식품이 제한적이라서'), JSON_OBJECT('id', 'D', 'text', '햇빛과 관련이 없어서')), '비타민 D는 일부 생선, 달걀노른자, 버섯 등에 있으나 양이 제한적이어서 햇빛 노출과 함께 고려합니다.', 'balance', 'hard', 'C'),
       ('multiple_choice', '염분을 줄이기 위한 쉬운 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '국물을 모두 마시기'), JSON_OBJECT('id', 'B', 'text', '소금을 더 넣기'), JSON_OBJECT('id', 'C', 'text', '국물과 찌개의 건더기 위주로 먹기'), JSON_OBJECT('id', 'D', 'text', '젓갈을 더 먹기')), '국물에 나트륨이 많아 건더기 위주로 먹으면 섭취를 줄일 수 있습니다.', 'practice', 'easy', 'C'),
       ('multiple_choice', '포만감 신호가 뇌에 전달되는 데 걸리는 시간은 어느 정도로 알려져 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '1초'), JSON_OBJECT('id', 'B', 'text', '5시간'), JSON_OBJECT('id', 'C', 'text', '하루'), JSON_OBJECT('id', 'D', 'text', '식사를 시작하고 약 20분 정도')), '포만감 호르몬이 신호를 보내는 데 시간이 걸려 천천히 먹으면 과식을 줄이는 데 도움이 된다고 알려져 있습니다.', 'habit', 'medium', 'D'),
       ('multiple_choice', '고강도 운동 후 충분히 회복하지 못한 채 반복하면 생길 수 있는 문제는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '체력이 무한히 좋아진다'), JSON_OBJECT('id', 'B', 'text', '피로가 전혀 쌓이지 않는다'), JSON_OBJECT('id', 'C', 'text', '과훈련으로 수행 능력 저하와 부상 위험 증가'), JSON_OBJECT('id', 'D', 'text', '수면이 개선된다')), '회복 없이 고강도를 이어가면 피로가 누적되어 수행 능력이 떨어지고 부상 위험이 커질 수 있습니다.', 'intensity', 'hard', 'C'),
       ('multiple_choice', '휴식일에 해도 좋은 가벼운 활동으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '천천히 걷기'), JSON_OBJECT('id', 'B', 'text', '최대 중량 데드리프트'), JSON_OBJECT('id', 'C', 'text', '전력 질주'), JSON_OBJECT('id', 'D', 'text', '장시간 고강도 인터벌')), '가벼운 걷기는 부담이 적어 쉬는 날의 활동으로 알맞습니다.', 'recovery', 'easy', 'A'),
       ('multiple_choice', '"수면 부채"란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '잠을 너무 많이 자는 것'), JSON_OBJECT('id', 'B', 'text', '잠을 자지 않는 방법'), JSON_OBJECT('id', 'C', 'text', '꿈을 꾸는 현상'), JSON_OBJECT('id', 'D', 'text', '필요한 수면보다 부족하게 잔 시간이 누적되는 것')), '수면이 계속 부족하면 부채가 쌓이듯 피로와 집중력 저하가 누적될 수 있습니다.', 'recovery', 'medium', 'D'),
       ('multiple_choice', '근력 운동을 하는 사람이 식단에서 신경 써야 할 점으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '단백질을 완전히 끊기'), JSON_OBJECT('id', 'B', 'text', '충분한 에너지와 단백질을 함께 섭취하기'), JSON_OBJECT('id', 'C', 'text', '식사를 줄이기'), JSON_OBJECT('id', 'D', 'text', '당 음료만 마시기')), '근력 운동에서는 에너지와 단백질이 충분해야 회복과 근육 유지에 유리합니다.', 'balance', 'medium', 'B'),
       ('multiple_choice', '칼슘 흡수를 돕는 비타민은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '비타민 C'), JSON_OBJECT('id', 'B', 'text', '비타민 B12'), JSON_OBJECT('id', 'C', 'text', '비타민 D'), JSON_OBJECT('id', 'D', 'text', '비타민 A')), '비타민 D는 장에서 칼슘 흡수를 돕는 데 관여합니다.', 'nutrients', 'medium', 'C'),
       ('multiple_choice', '식기와 도마를 소독하는 방법으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '찬물에 담가 두기'), JSON_OBJECT('id', 'B', 'text', '끓는 물에 소독하거나 햇빛에 건조하기'), JSON_OBJECT('id', 'C', 'text', '닦지 않기'), JSON_OBJECT('id', 'D', 'text', '젖은 채로 두기')), '열탕 소독과 충분한 건조는 세균을 줄이는 데 도움이 됩니다.', 'hygiene', 'medium', 'B'),
       ('multiple_choice', '식사 습관과 수면의 관계에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식사와 수면은 완전히 무관하다'), JSON_OBJECT('id', 'B', 'text', '늦은 식사나 과식은 수면의 질에 영향을 줄 수 있다'), JSON_OBJECT('id', 'C', 'text', '과식하면 항상 잘 잔다'), JSON_OBJECT('id', 'D', 'text', '야식은 수면을 항상 돕는다')), '취침 직전의 과식이나 늦은 식사는 소화 부담으로 수면의 질을 떨어뜨릴 수 있습니다.', 'habit', 'hard', 'B'),
       ('multiple_choice', '최대 심박수를 간단히 추정하는 일반 공식으로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '나이에 2를 곱한 값'), JSON_OBJECT('id', 'B', 'text', '100에서 나이를 뺀 값'), JSON_OBJECT('id', 'C', 'text', '체중을 2로 나눈 값'), JSON_OBJECT('id', 'D', 'text', '220에서 나이를 뺀 값')), '"220 - 나이"는 널리 쓰이는 대략적인 추정식이며 개인차가 크므로 참고용으로 봅니다.', 'intensity', 'medium', 'D'),
       ('multiple_choice', '기립근(척추 기립근)의 역할은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '척추를 곧게 세우고 지탱한다'), JSON_OBJECT('id', 'B', 'text', '손가락을 움직인다'), JSON_OBJECT('id', 'C', 'text', '눈을 감게 한다'), JSON_OBJECT('id', 'D', 'text', '발가락을 모은다')), '척추 기립근은 척추를 따라 있으며 자세를 유지하고 상체를 펴는 역할을 합니다.', 'body', 'medium', 'A'),
       ('multiple_choice', '나트륨 섭취 기준을 설명한 것으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '많이 먹을수록 좋다'), JSON_OBJECT('id', 'B', 'text', '기준이 없다'), JSON_OBJECT('id', 'C', 'text', '모든 사람에게 0이어야 한다'), JSON_OBJECT('id', 'D', 'text', '건강을 위해 과다 섭취하지 않도록 권고량이 있다')), '보건 기관은 나트륨을 지나치게 섭취하지 않도록 하루 섭취 기준을 제시합니다.', 'nutrients', 'medium', 'D'),
       ('multiple_choice', '"식사의 다양성"이 영양에 중요한 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 식품이 같은 영양소를 가져서'), JSON_OBJECT('id', 'B', 'text', '다양성은 영양과 무관해서'), JSON_OBJECT('id', 'C', 'text', '어떤 식품도 모든 영양소를 충분히 갖추지 못해서'), JSON_OBJECT('id', 'D', 'text', '식비를 줄일 수 있어서')), '식품마다 영양 성분이 달라 다양하게 먹어야 필요한 영양소를 두루 얻을 수 있습니다.', 'balance', 'hard', 'C'),
       ('multiple_choice', '폭식 후 극단적으로 굶는 행동이 문제가 되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '항상 건강해지기 때문'), JSON_OBJECT('id', 'B', 'text', '체력이 좋아지기 때문'), JSON_OBJECT('id', 'C', 'text', '폭식과 절식의 악순환을 만들 수 있어서'), JSON_OBJECT('id', 'D', 'text', '아무 문제가 없기 때문')), '극단적인 절식은 다시 폭식으로 이어질 수 있어 균형 있는 식사가 필요합니다.', 'habit', 'medium', 'C'),
       ('multiple_choice', '운동 후 근육통이 크게 남아 일상 움직임이 힘들 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '강도를 낮추고 회복에 시간을 두기'), JSON_OBJECT('id', 'B', 'text', '같은 부위를 더 세게 운동하기'), JSON_OBJECT('id', 'C', 'text', '스트레칭 없이 쉬지 않기'), JSON_OBJECT('id', 'D', 'text', '수분 섭취 중단하기')), '심한 근육통은 과한 운동의 신호일 수 있어 회복 시간을 두고 강도를 낮춰야 합니다.', 'intensity', 'medium', 'A'),
       ('multiple_choice', '수면 시간으로 흔히 권장되는 성인의 평균 범위는 대략 어떻게 될까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '1~2시간'), JSON_OBJECT('id', 'B', 'text', '12~14시간'), JSON_OBJECT('id', 'C', 'text', '수면은 필요 없다'), JSON_OBJECT('id', 'D', 'text', '약 7~9시간')), '많은 보건 기관이 성인에게 하루 7시간 이상, 대략 7~9시간의 수면을 권장합니다.', 'recovery', 'easy', 'D'),
       ('multiple_choice', '단체 급식이나 학교 급식에서 균형 잡힌 식사를 위한 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '좋아하는 반찬만 먹기'), JSON_OBJECT('id', 'B', 'text', '채소를 남기기'), JSON_OBJECT('id', 'C', 'text', '반찬을 골고루 선택하고 편식하지 않기'), JSON_OBJECT('id', 'D', 'text', '밥만 먹기')), '다양한 반찬을 골고루 먹으면 급식에서도 영양 균형을 맞출 수 있습니다.', 'balance', 'medium', 'C'),
