       ('multiple_choice', '운동 강도를 올릴 때 한 번에 한 가지 변수만 바꾸는 것이 권장되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동이 더 지루해지도록'), JSON_OBJECT('id', 'B', 'text', '어떤 변화가 효과나 불편을 만들었는지 파악하기 쉬워서'), JSON_OBJECT('id', 'C', 'text', '변수가 없어서'), JSON_OBJECT('id', 'D', 'text', '다른 변수는 해로워서')), '무게, 횟수, 세트 중 하나만 조절하면 몸의 반응을 구분해 판단하고 부상 위험도 줄일 수 있습니다.', 'intensity', 'hard', 'B'),
       ('multiple_choice', '등의 넓은 부분을 이루는 근육은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '대흉근'), JSON_OBJECT('id', 'B', 'text', '이두근'), JSON_OBJECT('id', 'C', 'text', '광배근'), JSON_OBJECT('id', 'D', 'text', '비복근')), '광배근은 등 옆쪽에 넓게 퍼진 근육으로 당기는 동작에서 주로 쓰입니다.', 'body', 'easy', 'C'),
       ('multiple_choice', '식사와 함께 수분 섭취량을 계산할 때 고려할 점으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '물만 계산하기'), JSON_OBJECT('id', 'B', 'text', '음료만 계산하기'), JSON_OBJECT('id', 'C', 'text', '음식과 음료에서 들어오는 수분을 함께 고려하기'), JSON_OBJECT('id', 'D', 'text', '고려하지 않기')), '하루 총 수분 섭취는 음료뿐 아니라 음식에서 얻는 수분도 포함됩니다.', 'water', 'hard', 'C'),
       ('multiple_choice', '체중 대비 단백질 섭취 권장량이 활동량이 많은 사람에게 더 높게 제시되는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육의 손상과 회복에 단백질이 더 필요할 수 있어서'), JSON_OBJECT('id', 'B', 'text', '활동하면 단백질이 사라져서'), JSON_OBJECT('id', 'C', 'text', '단백질이 필요 없어져서'), JSON_OBJECT('id', 'D', 'text', '열량이 줄어서')), '운동량이 많으면 근육 회복과 유지에 단백질 필요량이 늘어날 수 있습니다.', 'nutrients', 'medium', 'A'),
       ('multiple_choice', '수면 중 성장 호르몬 분비에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '깊은 수면 단계에서 분비가 활발해 회복에 관여한다'), JSON_OBJECT('id', 'B', 'text', '수면 중에는 전혀 분비되지 않는다'), JSON_OBJECT('id', 'C', 'text', '운동과는 무관하다'), JSON_OBJECT('id', 'D', 'text', '낮에만 분비된다')), '깊은 수면 단계에서 성장 호르몬이 많이 분비되어 조직의 회복과 재생에 관여합니다.', 'recovery', 'hard', 'A'),
       ('multiple_choice', '단백질 1g이 내는 열량은 약 얼마일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '약 9kcal'), JSON_OBJECT('id', 'B', 'text', '약 4kcal'), JSON_OBJECT('id', 'C', 'text', '약 7kcal'), JSON_OBJECT('id', 'D', 'text', '약 0kcal')), '단백질은 탄수화물과 같이 1g당 약 4kcal의 열량을 냅니다.', 'nutrients', 'easy', 'B'),
       ('multiple_choice', '식사 습관에 대한 "자기 점검" 주기로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 번만 점검하고 끝내기'), JSON_OBJECT('id', 'B', 'text', '점검하지 않기'), JSON_OBJECT('id', 'C', 'text', '정기적으로 점검하고 필요하면 목표를 조정하기'), JSON_OBJECT('id', 'D', 'text', '매시간 지나치게 점검하기')), '정기적으로 점검하고 목표를 조정하면 지속 가능한 개선에 도움이 됩니다.', 'habit', 'hard', 'C'),
       ('multiple_choice', '해조류에 풍부한 무기질로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '비타민 C'), JSON_OBJECT('id', 'B', 'text', '설탕'), JSON_OBJECT('id', 'C', 'text', '카페인'), JSON_OBJECT('id', 'D', 'text', '요오드')), '미역과 김 같은 해조류에는 요오드가 비교적 풍부합니다.', 'nutrients', 'easy', 'D'),
       ('multiple_choice', '주 1회 식재료를 한꺼번에 손질해 두는 밀프렙의 장점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '식재료가 항상 낭비된다'), JSON_OBJECT('id', 'B', 'text', '식사를 못하게 된다'), JSON_OBJECT('id', 'C', 'text', '식비가 늘어난다'), JSON_OBJECT('id', 'D', 'text', '평일 조리 시간을 줄이고 건강한 식사를 쉽게 준비할 수 있다')), '미리 준비하면 바쁜 날에도 가공식품 대신 집밥을 먹기 쉽습니다.', 'practice', 'medium', 'D'),
       ('multiple_choice', '아이의 편식을 줄이는 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '억지로 먹이기'), JSON_OBJECT('id', 'B', 'text', '다양한 식재료를 반복해서 접하게 하고 강요하지 않기'), JSON_OBJECT('id', 'C', 'text', '좋아하는 음식만 주기'), JSON_OBJECT('id', 'D', 'text', '식사를 거르게 하기')), '반복 노출과 긍정적 식사 환경이 편식 개선에 도움이 됩니다.', 'balance', 'medium', 'B'),
       ('multiple_choice', '운동을 마칠 때 가볍게 움직이는 정리 운동의 목적은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 기록을 지우려고'), JSON_OBJECT('id', 'B', 'text', '심박수와 호흡을 서서히 안정시키려고'), JSON_OBJECT('id', 'C', 'text', '근육을 더 세게 쓰려고'), JSON_OBJECT('id', 'D', 'text', '체온을 급격히 올리려고')), '정리 운동은 올라간 심박수와 체온을 천천히 낮추어 몸이 안정되도록 돕습니다.', 'recovery', 'easy', 'B'),
       ('multiple_choice', '"어린이 기호식품 품질인증"의 의미로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '영양 기준과 안전 기준을 충족한 어린이용 식품에 부여되는 인증'), JSON_OBJECT('id', 'B', 'text', '맛이 가장 좋다는 의미'), JSON_OBJECT('id', 'C', 'text', '열량이 없다는 의미'), JSON_OBJECT('id', 'D', 'text', '가격이 가장 싸다는 의미')), '어린이 기호식품 중 영양과 안전 기준을 충족한 제품에 품질인증을 부여하는 제도입니다.', 'label', 'medium', 'A'),
       ('multiple_choice', '오메가-3 지방산이 풍부한 식품은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '고등어 같은 등푸른 생선'), JSON_OBJECT('id', 'B', 'text', '설탕'), JSON_OBJECT('id', 'C', 'text', '쌀밥'), JSON_OBJECT('id', 'D', 'text', '탄산음료')), '등푸른 생선과 들기름, 호두 등에 오메가-3 계열 지방산이 풍부합니다.', 'nutrients', 'medium', 'A'),
       ('multiple_choice', '식품 보관에서 "선입선출"이란 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '나중에 들어온 식품을 먼저 쓰는 방법'), JSON_OBJECT('id', 'B', 'text', '식품을 섞어 두는 방법'), JSON_OBJECT('id', 'C', 'text', '식품을 버리는 방법'), JSON_OBJECT('id', 'D', 'text', '먼저 들어온 식품을 먼저 사용하는 방법')), '먼저 구입한 식품부터 사용하면 유통기한 경과로 인한 폐기를 줄일 수 있습니다.', 'hygiene', 'hard', 'D'),
       ('multiple_choice', '물 섭취와 피부 상태에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '물 섭취만으로 피부 상태가 결정되는 것은 아니며 전반적 수분 균형이 중요하다'), JSON_OBJECT('id', 'B', 'text', '물만 많이 마시면 피부가 항상 좋아진다'), JSON_OBJECT('id', 'C', 'text', '물은 피부와 완전히 무관하다'), JSON_OBJECT('id', 'D', 'text', '물을 마시면 피부가 항상 마른다')), '피부 상태는 수분 외에도 영양, 수면, 생활 습관 등 여러 요인에 영향을 받습니다.', 'water', 'hard', 'A'),
       ('multiple_choice', '비타민 B군이 몸에서 주로 하는 일은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '에너지 대사를 돕는 것'), JSON_OBJECT('id', 'B', 'text', '뼈만 만드는 것'), JSON_OBJECT('id', 'C', 'text', '체온을 낮추는 것'), JSON_OBJECT('id', 'D', 'text', '혈관을 막는 것')), '비타민 B군은 탄수화물·지방·단백질이 에너지로 쓰이는 대사 과정을 돕습니다.', 'nutrients', 'medium', 'A'),
       ('multiple_choice', '준비운동으로 어깨를 돌릴 때 알맞은 크기와 속도는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '처음부터 가장 크게 빠르게'), JSON_OBJECT('id', 'B', 'text', '어깨를 뒤로 꺾어 반동 주기'), JSON_OBJECT('id', 'C', 'text', '작은 원에서 시작해 점점 크게, 천천히'), JSON_OBJECT('id', 'D', 'text', '한쪽 어깨만 세게 돌리기')), '작은 범위에서 시작해 서서히 범위를 넓히면 어깨 관절에 무리 없이 움직임이 준비됩니다.', 'warmup', 'medium', 'C'),
       ('multiple_choice', '힙 힌지와 스쿼트의 가장 큰 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 같은 움직임이다'), JSON_OBJECT('id', 'B', 'text', '힌지는 엉덩이를 뒤로 접는 비중이 크고 스쿼트는 무릎 굽힘 비중이 크다'), JSON_OBJECT('id', 'C', 'text', '힌지는 팔 운동이다'), JSON_OBJECT('id', 'D', 'text', '스쿼트는 고관절을 전혀 쓰지 않는다')), '힌지는 고관절을 중심으로 접고, 스쿼트는 무릎과 고관절을 함께 굽히는 움직임 패턴입니다.', 'form', 'hard', 'B'),
       ('true_false', '스쿼트는 주로 하체 근육을 사용하는 운동이다.', NULL, '스쿼트는 허벅지와 엉덩이 등 하체 근육을 주로 사용합니다.', '운동', 'easy', 'O'),
       ('multiple_choice', '근육이 수축할 때 근섬유 안에서 일어나는 구조적 변화를 설명하는 이론은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '피부 이동설'), JSON_OBJECT('id', 'B', 'text', '혈액 응고설'), JSON_OBJECT('id', 'C', 'text', '뼈 성장설'), JSON_OBJECT('id', 'D', 'text', '활주설(액틴과 미오신의 미끄러짐)')), '근육 수축은 액틴과 미오신 필라멘트가 서로 미끄러지며 일어난다는 활주설로 설명합니다.', 'body', 'hard', 'D'),
       ('multiple_choice', '운동 강도를 정할 때 가장 먼저 고려할 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '친구의 운동 강도'), JSON_OBJECT('id', 'B', 'text', '인터넷 후기의 최고 기록'), JSON_OBJECT('id', 'C', 'text', '현재 나의 체력 수준'), JSON_OBJECT('id', 'D', 'text', '가장 힘든 강도')), '같은 운동도 사람마다 체력 수준이 달라 힘든 정도가 다릅니다. 현재 체력에 맞게 시작하는 것이 안전합니다.', 'basics', 'easy', 'C'),
       ('multiple_choice', '스트레칭 중 느껴야 하는 알맞은 느낌은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '약간 당기는 정도의 느낌'), JSON_OBJECT('id', 'B', 'text', '찌르는 듯한 통증'), JSON_OBJECT('id', 'C', 'text', '날카로운 아픔'), JSON_OBJECT('id', 'D', 'text', '저림이 심한 느낌')), '스트레칭은 약간 당기는 정도에서 멈추고 통증이 느껴지면 줄여야 합니다.', 'warmup', 'easy', 'A'),
       ('multiple_choice', '종아리 스트레칭이 도움이 되는 활동은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손가락 운동'), JSON_OBJECT('id', 'B', 'text', '시력 운동'), JSON_OBJECT('id', 'C', 'text', '달리기와 걷기'), JSON_OBJECT('id', 'D', 'text', '턱 운동')), '종아리 근육은 걷기와 달리기에서 많이 쓰이므로 스트레칭으로 뻐근함을 풀 수 있습니다.', 'warmup', 'medium', 'C'),
       ('multiple_choice', '가벼운 조깅 중 숨이 너무 차서 말을 거의 못 한다면 어떻게 조절할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '속도를 낮추어 강도를 줄이기'), JSON_OBJECT('id', 'B', 'text', '속도를 더 올리기'), JSON_OBJECT('id', 'C', 'text', '숨을 더 오래 참기'), JSON_OBJECT('id', 'D', 'text', '아무 조절도 하지 않기')), '말하기도 힘들 만큼 숨이 찬다면 강도가 높은 편입니다. 속도를 낮추면 더 오래 편하게 이어갈 수 있습니다.', 'basics', 'easy', 'A'),
       ('multiple_choice', '단백질이 부족할 때 나타날 수 있는 문제로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '키가 급격히 커짐'), JSON_OBJECT('id', 'B', 'text', '시력 향상'), JSON_OBJECT('id', 'C', 'text', '근육 감소와 회복 지연 등'), JSON_OBJECT('id', 'D', 'text', '체온 상승')), '단백질이 오래 부족하면 근육과 조직 유지가 어려워질 수 있습니다.', 'nutrients', 'medium', 'C'),
       ('multiple_choice', '"단축성 수축"과 "신장성 수축"의 차이로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '둘은 같은 말이다'), JSON_OBJECT('id', 'B', 'text', '단축성은 근육이 짧아지며 힘을 내고 신장성은 길어지며 힘을 낸다'), JSON_OBJECT('id', 'C', 'text', '단축성은 쉬는 상태'), JSON_OBJECT('id', 'D', 'text', '신장성은 근육이 사라지는 것')), '덤벨을 올릴 때가 단축성, 천천히 내릴 때가 신장성 수축에 해당합니다.', 'body', 'medium', 'B'),
       ('multiple_choice', '"이미 하고 있는 좋은 습관"을 식단에 활용하는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '기존 습관을 모두 버리기'), JSON_OBJECT('id', 'B', 'text', '습관을 바꾸지 않기'), JSON_OBJECT('id', 'C', 'text', '기존 습관(아침 커피 등)에 건강한 행동(물, 과일)을 붙이기'), JSON_OBJECT('id', 'D', 'text', '새 습관을 무시하기')), '기존 습관에 새 행동을 연결하면 새로운 습관을 형성하기 쉽습니다.', 'practice', 'medium', 'C'),
       ('multiple_choice', '유산소 운동의 일반적인 목표 주당 시간으로 알려진 권고는 대략 얼마일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '주당 10분'), JSON_OBJECT('id', 'B', 'text', '월 30분'), JSON_OBJECT('id', 'C', 'text', '주당 24시간'), JSON_OBJECT('id', 'D', 'text', '중강도 기준 주당 약 150분 이상')), '세계보건기구 등은 성인에게 중강도 유산소 운동을 주당 150분 이상 권장합니다.', 'intensity', 'medium', 'D'),
       ('multiple_choice', '한 끼 식사에서 곡류와 단백질, 채소의 비율을 정할 때 알맞은 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '곡류만 많이 먹기'), JSON_OBJECT('id', 'B', 'text', '채소를 충분히 늘리고 곡류와 단백질은 적당량으로 나누기'), JSON_OBJECT('id', 'C', 'text', '단백질만 많이 먹기'), JSON_OBJECT('id', 'D', 'text', '채소를 최소로 먹기')), '채소를 충분히 포함하고 곡류와 단백질은 활동량에 맞게 조절하면 균형을 맞추기 쉽습니다.', 'balance', 'medium', 'B'),
       ('multiple_choice', '식사 후 졸음을 줄이기 위한 방법으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '더 많이 먹기'), JSON_OBJECT('id', 'B', 'text', '식후 바로 눕기'), JSON_OBJECT('id', 'C', 'text', '당 음료 마시기'), JSON_OBJECT('id', 'D', 'text', '과식을 피하고 식후 가볍게 걷기')), '과식을 피하고 식후 가벼운 활동을 하면 졸음을 줄이는 데 도움이 될 수 있습니다.', 'habit', 'medium', 'D'),
       ('multiple_choice', '영양성분 표시에서 "열량 기준치"로 쓰이는 하루 열량은 보통 얼마일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '약 2,000kcal 기준으로 제시되는 경우가 많다'), JSON_OBJECT('id', 'B', 'text', '약 500kcal'), JSON_OBJECT('id', 'C', 'text', '약 10,000kcal'), JSON_OBJECT('id', 'D', 'text', '약 100kcal')), '많은 영양표시는 성인 하루 2,000kcal를 기준으로 % 영양성분 기준치를 계산합니다.', 'label', 'hard', 'A'),
       ('multiple_choice', '운동 중 거울이 없을 때 자세를 점검하는 간단한 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '눈을 감고 하기'), JSON_OBJECT('id', 'B', 'text', '자세 점검은 필요 없다'), JSON_OBJECT('id', 'C', 'text', '숨을 참고 해 보기'), JSON_OBJECT('id', 'D', 'text', '휴대전화로 옆모습을 촬영해 보기')), '옆에서 짧게 촬영해 보면 허리 굽힘이나 무릎 방향 같은 자세를 쉽게 확인할 수 있습니다.', 'form', 'easy', 'D'),
       ('multiple_choice', '키 성장기 청소년의 운동에서 특히 유의할 점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '성장판은 운동과 무관하다'), JSON_OBJECT('id', 'B', 'text', '무조건 최대 중량으로 훈련'), JSON_OBJECT('id', 'C', 'text', '성장판 부담을 고려해 과도한 반복이나 무리한 중량을 피하기'), JSON_OBJECT('id', 'D', 'text', '운동을 전혀 하지 않기')), '성장기에는 과도한 반복 훈련이나 무리한 중량이 부담이 될 수 있어 점진적이고 올바른 지도가 중요합니다.', 'body', 'hard', 'C'),
       ('multiple_choice', '운동 목표를 세울 때 알맞은 방식은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '막연하고 매우 큰 목표'), JSON_OBJECT('id', 'B', 'text', '현재 체력에 맞는 작고 구체적인 목표'), JSON_OBJECT('id', 'C', 'text', '남들과 똑같은 목표'), JSON_OBJECT('id', 'D', 'text', '목표 없이 하기')), '작고 구체적인 목표는 달성하기 쉬워 지속에 도움이 됩니다.', 'intensity', 'easy', 'B'),
       ('multiple_choice', '운동 효과의 개별성 원리가 뜻하는 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 사람은 같은 운동으로 같은 결과를 얻는다'), JSON_OBJECT('id', 'B', 'text', '같은 운동도 사람마다 반응이 다르다'), JSON_OBJECT('id', 'C', 'text', '운동은 나이와 무관하게 똑같다'), JSON_OBJECT('id', 'D', 'text', '체력은 변하지 않는다')), '유전, 나이, 생활습관에 따라 같은 운동에도 반응이 다를 수 있어 개인에게 맞는 계획이 필요합니다.', 'basics', 'medium', 'B'),
       ('multiple_choice', '근육이 늘어나면서 힘을 버티는 수축 형태를 무엇이라 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '단축성 수축'), JSON_OBJECT('id', 'B', 'text', '등척성 수축'), JSON_OBJECT('id', 'C', 'text', '신장성(에센트릭) 수축'), JSON_OBJECT('id', 'D', 'text', '무수축')), '아령을 천천히 내릴 때처럼 근육이 늘어나며 힘을 버티는 수축을 신장성 수축이라 합니다.', 'basics', 'hard', 'C'),
       ('multiple_choice', '덤벨이나 밴드를 이용해 근육에 저항을 주는 운동을 무엇이라고 할까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '스트레칭'), JSON_OBJECT('id', 'B', 'text', '호흡 운동'), JSON_OBJECT('id', 'C', 'text', '근력 운동'), JSON_OBJECT('id', 'D', 'text', '휴식 운동')), '근력 운동은 근육이 저항에 맞서 힘을 쓰게 하는 운동으로, 근육의 힘과 지구력을 키우는 데 도움이 됩니다.', 'basics', 'easy', 'C'),
       ('multiple_choice', '가공식품의 영양성분표를 비교할 때 같은 기준으로 비교하는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '포장 크기로 비교하기'), JSON_OBJECT('id', 'B', 'text', '가격으로만 비교하기'), JSON_OBJECT('id', 'C', 'text', '100g당 또는 같은 제공량 기준으로 환산해 비교하기'), JSON_OBJECT('id', 'D', 'text', '이름으로 비교하기')), '제공량이 다르면 숫자만 비교하면 오해할 수 있어 같은 기준(100g 등)으로 맞춰 비교합니다.', 'label', 'medium', 'C'),
       ('multiple_choice', '플랭크에서 팔꿈치의 위치로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '머리 위'), JSON_OBJECT('id', 'B', 'text', '발 옆'), JSON_OBJECT('id', 'C', 'text', '어깨 바로 아래'), JSON_OBJECT('id', 'D', 'text', '엉덩이 뒤')), '팔꿈치를 어깨 바로 아래에 두면 어깨 관절이 안정적으로 몸을 지탱합니다.', 'form', 'easy', 'C'),
       ('multiple_choice', '체력 검사에서 많이 쓰는 앉아 윗몸 앞으로 굽히기는 어떤 요소를 보는 것일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '유연성'), JSON_OBJECT('id', 'B', 'text', '심폐지구력'), JSON_OBJECT('id', 'C', 'text', '순발력'), JSON_OBJECT('id', 'D', 'text', '시력')), '앉은 자세에서 상체를 앞으로 굽혀 손이 닿는 거리를 재어 몸의 유연성을 평가합니다.', 'basics', 'medium', 'A'),
       ('multiple_choice', '한국인 영양소 섭취기준이 정기적으로 개정되는 이유로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '이름을 바꾸기 위해서'), JSON_OBJECT('id', 'B', 'text', '식비를 올리기 위해서'), JSON_OBJECT('id', 'C', 'text', '새로운 연구 결과와 식생활 변화를 반영하기 위해서'), JSON_OBJECT('id', 'D', 'text', '변하지 않기 때문에')), '영양과 건강에 관한 새로운 근거와 식생활 변화를 반영해 기준을 갱신합니다.', 'balance', 'hard', 'C'),
       ('multiple_choice', '주당 운동 횟수를 정할 때 초보자에게 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '처음부터 매일 2시간'), JSON_OBJECT('id', 'B', 'text', '한 달에 한 번'), JSON_OBJECT('id', 'C', 'text', '주 2~3회처럼 지킬 수 있는 횟수부터'), JSON_OBJECT('id', 'D', 'text', '횟수는 상관없다')), '지킬 수 있는 빈도로 시작해 습관을 만든 뒤 늘리는 것이 현실적입니다.', 'intensity', 'easy', 'C'),
       ('multiple_choice', '운동할 때 신발 선택의 기본 원칙은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '발에 맞고 쿠션과 지지가 있는 신발'), JSON_OBJECT('id', 'B', 'text', '가장 꽉 조이는 신발'), JSON_OBJECT('id', 'C', 'text', '굽이 높은 신발'), JSON_OBJECT('id', 'D', 'text', '맨발과 같은 느낌만 중요한 신발')), '발에 잘 맞고 운동 종류에 맞는 신발은 충격을 줄이고 발을 안정적으로 잡아 주어 발과 무릎의 부담을 낮춥니다.', 'basics', 'easy', 'A'),
       ('multiple_choice', '준비된 동작에서 시작 자세와 끝 자세를 정확히 지켜 하는 것의 이점은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동 효과와 안전성이 높아진다'), JSON_OBJECT('id', 'B', 'text', '운동 시간이 길어진다'), JSON_OBJECT('id', 'C', 'text', '근육이 사라진다'), JSON_OBJECT('id', 'D', 'text', '호흡이 안정되지 않는다')), '정해진 가동 범위를 지키면 목표 근육에 효과적으로 자극이 가고 관절 부담이 줄어듭니다.', 'form', 'easy', 'A'),
       ('multiple_choice', '운동 후 갑자기 일어설 때 어지러운 이유로 알려진 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '근육이 커져서'), JSON_OBJECT('id', 'B', 'text', '혈압이 일시적으로 떨어질 수 있어서'), JSON_OBJECT('id', 'C', 'text', '키가 줄어서'), JSON_OBJECT('id', 'D', 'text', '체온이 올라서')), '운동 직후 갑자기 일어나면 혈액이 하체로 몰려 혈압이 일시적으로 떨어질 수 있어 천천히 일어나는 것이 안전합니다.', 'safety', 'medium', 'B'),
       ('multiple_choice', '천천히 먹는 식사의 좋은 점으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '과식을 줄이고 식사 만족도가 높아질 수 있다'), JSON_OBJECT('id', 'B', 'text', '식사가 항상 더 빨리 끝난다'), JSON_OBJECT('id', 'C', 'text', '소화가 안 된다'), JSON_OBJECT('id', 'D', 'text', '맛을 느끼기 어렵다')), '천천히 먹으면 포만 신호가 전달되는 시간을 확보해 과식을 줄이기 쉽습니다.', 'habit', 'easy', 'A'),
       ('multiple_choice', '러닝이나 조깅 같은 운동은 주로 어떤 체력 요소를 키울까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '손의 악력만'), JSON_OBJECT('id', 'B', 'text', '심폐지구력'), JSON_OBJECT('id', 'C', 'text', '시력'), JSON_OBJECT('id', 'D', 'text', '청력')), '꾸준한 달리기는 심장과 폐가 산소를 효율적으로 쓰는 능력, 즉 심폐지구력을 키워 줍니다.', 'basics', 'easy', 'B'),
       ('multiple_choice', '스트레칭의 주된 목적은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '관절의 움직임 범위와 유연성 유지'), JSON_OBJECT('id', 'B', 'text', '근육 크기를 즉시 두 배로 키우기'), JSON_OBJECT('id', 'C', 'text', '심박수를 최대로 올리기'), JSON_OBJECT('id', 'D', 'text', '체지방 즉시 제거')), '스트레칭은 근육과 관절이 움직일 수 있는 범위를 유지하고 늘리는 데 도움이 됩니다.', 'basics', 'easy', 'A'),
       ('multiple_choice', '운동 후 정리운동을 생략하면 어떻게 될 수 있을까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '회복이 더딘 느낌이 들 수 있다'), JSON_OBJECT('id', 'B', 'text', '체중이 즉시 줄어든다'), JSON_OBJECT('id', 'C', 'text', '근육이 영구히 커진다'), JSON_OBJECT('id', 'D', 'text', '체력이 저절로 향상된다')), '정리운동은 호흡과 심박을 안정시키고 몸을 편안하게 돌리는 데 도움이 되므로 생략하면 개운하지 않을 수 있습니다.', 'warmup', 'easy', 'A'),
       ('multiple_choice', '스트레칭이 부상을 예방하는지에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 부상을 완벽히 예방한다'), JSON_OBJECT('id', 'B', 'text', '유연성에 도움이 되지만 부상 예방 효과는 상황에 따라 다르다'), JSON_OBJECT('id', 'C', 'text', '아무 효과도 없다'), JSON_OBJECT('id', 'D', 'text', '부상을 항상 유발한다')), '스트레칭은 가동 범위와 편안함에 도움이 되나 단독으로 부상을 막는다고 단정하기는 어렵습니다.', 'recovery', 'hard', 'B'),
       ('multiple_choice', '근육과 뼈를 이어 주는 조직은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '힘줄(건)'), JSON_OBJECT('id', 'B', 'text', '인대'), JSON_OBJECT('id', 'C', 'text', '혈관'), JSON_OBJECT('id', 'D', 'text', '신경')), '힘줄은 근육을 뼈에 연결해 근육의 힘을 뼈로 전달합니다.', 'body', 'easy', 'A'),
       ('multiple_choice', '영양성분표에서 열량이 같아도 영양 구성이 다를 수 있는 이유는 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '열량은 항상 같은 영양소 구성이어서'), JSON_OBJECT('id', 'B', 'text', '맛에 따라 열량이 달라져서'), JSON_OBJECT('id', 'C', 'text', '탄수화물·지방·단백질 비율과 당류·나트륨 함량이 다를 수 있어서'), JSON_OBJECT('id', 'D', 'text', '포장에 따라 열량이 달라져서')), '같은 열량이라도 구성하는 영양소와 나트륨, 당류 함량이 달라 영양적 질이 다를 수 있습니다.', 'label', 'medium', 'C'),
       ('multiple_choice', '근비대(근육 크기 증가)에 흔히 활용되는 반복 범위는 대략 어디일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '1회'), JSON_OBJECT('id', 'B', 'text', '1,000회'), JSON_OBJECT('id', 'C', 'text', '반복 없음'), JSON_OBJECT('id', 'D', 'text', '중간 반복 범위(대략 8~12회 안팎)')), '중간 정도의 반복 범위가 근육 크기 증가 목적에 자주 쓰이지만 개인과 목표에 따라 다릅니다.', 'intensity', 'medium', 'D'),
       ('multiple_choice', '엉덩이의 큰 근육은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '이두근'), JSON_OBJECT('id', 'B', 'text', '승모근'), JSON_OBJECT('id', 'C', 'text', '대둔근'), JSON_OBJECT('id', 'D', 'text', '복직근')), '대둔근은 몸에서 가장 큰 근육 중 하나로 일어서기, 계단 오르기에서 중요한 역할을 합니다.', 'body', 'easy', 'C'),
       ('multiple_choice', '스트레스를 받을 때 폭식하는 습관을 줄이는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '더 많이 먹기'), JSON_OBJECT('id', 'B', 'text', '식사를 완전히 끊기'), JSON_OBJECT('id', 'C', 'text', '산책이나 심호흡 같은 다른 방법으로 풀어 보기'), JSON_OBJECT('id', 'D', 'text', '혼자서 계속 참기')), '음식 외의 방법으로 스트레스를 풀면 정서적 폭식을 줄이는 데 도움이 됩니다.', 'habit', 'easy', 'C'),
       ('multiple_choice', '탄산수에 대한 설명으로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '모든 탄산수는 설탕이 들어 있다'), JSON_OBJECT('id', 'B', 'text', '탄산수는 물이 아니라 약이다'), JSON_OBJECT('id', 'C', 'text', '탄산수는 열량이 높다'), JSON_OBJECT('id', 'D', 'text', '무가당 탄산수는 수분 보충에 활용할 수 있다')), '당이 첨가되지 않은 탄산수는 수분 섭취에 활용할 수 있으나 제품마다 성분을 확인해야 합니다.', 'water', 'medium', 'D'),
       ('multiple_choice', '준비운동의 개인화가 필요한 경우로 알맞은 것은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '운동하지 않는 사람'), JSON_OBJECT('id', 'B', 'text', '오늘 쉬는 사람'), JSON_OBJECT('id', 'C', 'text', '운동복을 입지 않은 사람'), JSON_OBJECT('id', 'D', 'text', '평소 불편한 관절이나 근육이 있는 사람')), '불편한 부위가 있다면 그 부위를 더 신경 써서 부드럽게 준비하되 통증이 있으면 전문가와 상담하는 것이 좋습니다.', 'warmup', 'hard', 'D'),
       ('multiple_choice', '운동 강도를 느낌으로 표현하는 대표적인 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '신발 치수'), JSON_OBJECT('id', 'B', 'text', '체온계 눈금'), JSON_OBJECT('id', 'C', 'text', '운동자각도(RPE)'), JSON_OBJECT('id', 'D', 'text', '혈액형 검사')), 'RPE는 운동이 얼마나 힘들게 느껴지는지를 점수로 표현하는 방법으로, 심박 측정이 어려울 때 유용합니다.', 'basics', 'medium', 'C'),
       ('multiple_choice', '식사를 준비할 때 가족의 입맛과 건강을 함께 고려하는 방법은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '한 가지 음식만 반복하기'), JSON_OBJECT('id', 'B', 'text', '다양한 재료와 조리법을 활용해 맛과 영양을 균형 있게 맞추기'), JSON_OBJECT('id', 'C', 'text', '가공식품만 준비하기'), JSON_OBJECT('id', 'D', 'text', '채소를 제외하기')), '다양한 재료와 조리법을 활용하면 맛과 영양을 함께 챙길 수 있습니다.', 'habit', 'easy', 'B'),
       ('multiple_choice', '캔 제품이 심하게 부풀어 있을 때 알맞은 대응은 무엇일까요?', JSON_ARRAY(JSON_OBJECT('id', 'A', 'text', '그대로 먹기'), JSON_OBJECT('id', 'B', 'text', '데워서 먹기'), JSON_OBJECT('id', 'C', 'text', '먹지 않고 폐기하기'), JSON_OBJECT('id', 'D', 'text', '냉동 후 먹기')), '부푼 캔은 내부에서 세균이 증식하며 가스가 생겼을 수 있어 먹지 않아야 합니다.', 'label', 'easy', 'C'),
